DELETE FROM puntuaciones WHERE categoria='Playas';

INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27051','playa','Playa de las Catedrales (As Catedrais)',NULL,'Excelente. Impresionante monumento natural con arcos de roca monumentales. Arena fina y grisácea. No tiene Bandera Azul debido a las restricciones de acceso y protección medioambiental.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27051','playa','Playa de Os Castros','Bandera Azul','Excelente. Playa resguardada por altos acantilados con espectaculares formaciones rocosas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27051','playa','Playa de Illas','Bandera Azul','Muy buena. Conectada con Os Castros en bajamar, formando un precioso arenal rodeado de acantilados. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27051','playa','Playa de Rochas Blancas',NULL,'Regular. Pequeña cala de ría, muy resguardada del oleaje. Arena fina mezclada con restos de conchas y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27051','playa','Playa de Areosa',NULL,'Aceptable. Playa pequeña de ría de carácter seminatural. Arena fina y algo de lodo en marea baja. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90040','playa','Playa de Coto','Bandera Azul','Excelente. Playa muy extensa de mar abierto, ideal para pasear en bajamar. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90040','playa','Playa de Fontela-Balea','Bandera Azul','Muy buena. Amplio arenal con fuerte oleaje, perfecta para deportes de viento. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90040','playa','Playa de Longara','Bandera Azul','Muy buena. Paisaje rocoso espectacular, muy frecuentada por surfistas. Arena fina y afloramientos de piedra. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90040','playa','Playa de Pasada','Bandera Azul','Buena. Playa familiar, protegida del viento por acantilados bajos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90040','playa','Playa de Altar','Bandera Azul','Excelente. Situada en la desembocadura del río Masma, paisaje idílico de dunas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90040','playa','Playa de San Bartolo',NULL,'Aceptable. Pequeña cala rocosa de difícil acceso en pleamar. Arena fina y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90040','playa','Playa de Remior','Bandera Azul','Buena. Playa tranquila con un entorno natural dunar bien conservado. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27019','playa','Playa de Rapadoira','Bandera Azul','Excelente. Playa urbana principal, muy resguardada gracias a un espigón artificial. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27019','playa','Playa de Llas','Bandera Azul','Excelente. Gran arenal semiurbano rodeado de dunas naturales y fuerte oleaje. Arena fina y muy blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27019','playa','Playa de Peizás','Bandera Azul','Muy buena. Entorno rural y tranquilo, expuesta al mar abierto. Arena fina y zonas de piedra. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27019','playa','Playa de Pampillosa',NULL,'Buena. Situada junto a la desembocadura del río Ouro, entorno natural precioso. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27019','playa','Playa de Areoura','Bandera Azul','Muy buena. Cala recogida y familiar con aguas tranquilas de color turquesa. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27019','playa','Playa de Polas',NULL,'Aceptable. Pequeña cala rocosa de carácter secundario. Arena fina y abundante piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27019','playa','Playa de Fondás',NULL,'Buena. Continuación de Areoura, entorno tranquilo. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27902','playa','Playa de Portelo','Bandera Azul','Excelente. Playa urbana en forma de concha, con aguas cristalinas y paseo marítimo. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27902','playa','Playa de A Marosa','Bandera Azul','Muy buena. Playa de mar abierto con fuerte oleaje, rodeada de un entorno natural. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27902','playa','Playa de Ril',NULL,'Buena. Pequeña cala semicircular muy protegida del viento. Arena fina y grava fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27902','playa','Playa de O Cantiño',NULL,'Buena. Situada en una zona geológica singular con un área recreativa. Arena fina y abundante piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27902','playa','Playa de Perdouble',NULL,'Regular. Cala muy pequeña y rocosa de uso principalmente local. Arena gruesa y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90041','playa','Playa de O Torno (San Ciprián)','Bandera Azul','Excelente. Playa urbana resguardada con forma de media luna y aguas tranquilas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90041','playa','Playa de Cubelas',NULL,'Muy buena. Situada junto al puerto, muy segura para el baño familiar. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90041','playa','Playa de Caolín',NULL,'Excelente. Cala virgen escondida de extraordinaria belleza y aguas turquesas. Arena blanca finísima (antigua cantera de caolín). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90041','playa','Playa de Rueta',NULL,'Buena. Playa rural en la desembocadura de un riachuelo, entorno agreste. Arena fina y muchas rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90041','playa','Playa de Lieiro',NULL,'Regular. Próxima a zona industrial, expuesta a mar abierto. Arena fina y grisácea. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
