INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27025','playa','Playa de Lago',NULL,'Muy buena. Playa tranquila dividida por la desembocadura de un río, rodeada de un pinar. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27025','playa','Playa de Portocelo',NULL,'Buena. Cala resguardada en forma de u, aguas muy tranquilas y limpias. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27025','playa','Playa de Mendoiro',NULL,'Buena. Pequeña y aislada, ideal para huir de las aglomeraciones. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27025','playa','Playa de Morás',NULL,'Regular. Situada junto al puerto pesquero de Morás, entorno alterado. Arena fina y bloques de hormigón/ roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
