INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('28013','playa','Playa de Area','Bandera Azul','Excelente. Playa paradisíaca rodeada de vegetación, aguas tranquilas y transparentes. Arena fina y muy blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('28013','playa','Playa de Sacido',NULL,'Buena. Pequeña cala encajonada bajo un acantilado cubierto de pinos. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('28013','playa','Playa de Seiramar',NULL,'Aceptable. Continuación de la playa de Covas, carácter más rocoso. Arena fina y abundantes piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('28013','playa','Playa de Portonovo',NULL,'Buena. Cala aislada y virgen de difícil acceso a pie. Arena fina y entorno salvaje. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
