INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27064','playa','Playa de Moledos',NULL,'Buena. Cala pequeña y virgen aislada de los núcleos urbanos. Arena fina y entorno de piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
