INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('27064','playa','Playa de Vidreiro',NULL,'Aceptable. Situada junto al muelle, pequeña y resguardada. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90013','playa','Playa de Penarronda','Bandera Azul','Excelente. Monumento natural compartido con Tapia de Casariego, con una roca perforada única en el centro. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
