INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33070','playa','Playa de Penarronda (Parte oriental)','Bandera Azul','Excelente. Espacio protegido con dunas y un ecosistema de alta calidad ambiental. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33070','playa','Playa de Serantes',NULL,'Muy buena. Desembocadura fluvial que forma un paisaje de dunas y marismas precioso. Arena fina y zonas de piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33070','playa','Playa de Paloma',NULL,'Buena. Playa rural continuada de Serantes en bajamar, muy tranquila. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33070','playa','Playa de Represas',NULL,'Regular. Cala urbana abierta al mar bravo, sin arena en pleamar. Compuesta íntegramente por piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33070','playa','Playa de Urbanas (El Murallón)',NULL,'Buena. Pequeña cala recogida bajo el paseo marítimo del pueblo. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33023','playa','Playa de Pormenande',NULL,'Muy buena. Cala protegida por un islote, cuenta con un entorno ajardinado y bar. Compuesta por grava gruesa y piedra (cantos rodados). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33023','playa','Playa de Castello',NULL,'Buena. El arenal más grande del concejo, de carácter rural y acantilados agrestes. Arena gruesa oscura y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33023','playa','Playa de Cambaredo',NULL,'Regular. Aislada y salvaje, acceso peatonal complicado por escaleras. Compuesta por piedra, roca y arena oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33023','playa','Playa de Monellos',NULL,'Regular. Cala frecuentada por pescadores, sin servicios y encajonada. Compuesta por piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33023','playa','Playa de Torbas',NULL,'Buena. Playa extensa de mar abierto y fuerte oleaje. Arena oscura de grano medio y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90014','playa','Playa de Foxos',NULL,'Buena. Pequeña cala situada en la margen izquierda de la ría de Navia. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90014','playa','Playa de Torbas',NULL,'Buena. Playa acantilada con fuerte oleaje, paisaje muy virgen. Arena oscura y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90014','playa','Playa de Aguileiro (Coaña)',NULL,'Aceptable. No confundir con la de Tapia; es una estrecha franja bajo acantilado. Piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90014','playa','Playa de Armazá',NULL,'Regular. Playa aislada y peligrosa para el baño por corrientes. Compuesta por cantos rodados y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33041','playa','Playa de Navia',NULL,'Muy buena. Gran arenal urbano flanqueado por un pinar con lago interior y dunas. Arena fina y grisácea. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33041','playa','Playa de Frejulfe (Frexulfe)',NULL,'Excelente. Monumento natural de espectacular belleza salvaje y fuerte oleaje. Arena oscura y fina. No tiene Bandera Azul (por peligrosidad de corrientes).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33041','playa','Playa de Fabal',NULL,'Muy buena. Preciosa cala resguardada por altos acantilados verdes, ambiente tranquilo. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33041','playa','Playa de Coedo',NULL,'Buena. Cala pequeña con formaciones rocosas que la protegen parcialmente del mar abierto. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33041','playa','Playa de Moro',NULL,'Aceptable. Continuación de la playa de Navia, muy rocosa y expuesta. Arena gris y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33034','playa','Playa de Luarca (1 y 2)',NULL,'Muy buena. Playas urbanas resguardadas por los espigones del precioso puerto de Luarca. Arena fina y limpia. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33034','playa','Playa de Cueva',NULL,'Excelente. Impresionante paisaje donde el río Esva desemboca serpenteando entre la arena. Arena fina y oscura mezclada con cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33034','playa','Playa de Otur','Bandera Azul','Excelente. Playa semiurbana con un valioso sistema dunar y aguas cristalinas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33034','playa','Playa de Cadavedo (La Ribeirona)','Bandera Azul','Excelente. En forma de concha, rodeada de acantilados verdes y el famoso entorno de la Regalina. Arena fina y cantos rodados. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33034','playa','Playa de Tourán',NULL,'Muy buena. Pintoresca cala en forma de zigzag, muy protegida, parece una piscina natural. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33034','playa','Playa de Barayo',NULL,'Excelente. Reserva natural parcial. Una de las playas más vírgenes y espectaculares de España. Arena fina y oscura. No tiene Bandera Azul (protección estricta).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33034','playa','Playa de Portizuelo',NULL,'Buena. Famosa entre fotógrafos por sus agujas de roca ("ollas") y su entorno salvaje. Compuesta enteramente de piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33034','playa','Playa de Salinas / Tercera de Luarca',NULL,'Buena. Playa abierta y ventosa, muy frecuentada por locales. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('05008','playa','Playa del Silencio (Gavieiru)',NULL,'Excelente. Una de las postales más icónicas de Asturias; un anfiteatro de roca colosal. Compuesta por cantos rodados (piedra) y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('05008','playa','Playa de San Pedro de La Ribera',NULL,'Excelente. La más concurrida del concejo, con servicios excelentes y llanura verde. Arena dorada fina y canto rodado. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('05008','playa','Playa de la Concha de Artedo','Bandera Azul','Excelente. Impresionante bahía con una gigantesca muralla natural de piedras redondas. Canto rodado en superficie y arena dorada en bajamar. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('05008','playa','Playa de Gueirúa',NULL,'Excelente. Paisaje virgen de una belleza descarnada, destaca una hilera de islotes de roca afilada. Compuesta por piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('05008','playa','Playa de Oleiros',NULL,'Muy buena. Cala nudista rodeada de densos bosques de pinos y acantilados. Arena dorada y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('05008','playa','Playa de Aguilar (Límite con Muros de Nalón)','Bandera Azul','Excelente. Gran arenal turístico con rocas de formas caprichosas saliendo del agua. Arena dorada fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('05008','playa','Playa de Ballota',NULL,'Buena. Espectacular cala pedregosa de difícil acceso y nula ocupación. Piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('05008','playa','Playa de San Antolín (Cudillero)',NULL,'Regular. Muy pequeña, peligrosa y desaparece en pleamar. Piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33039','playa','Playa de Aguilar','Bandera Azul','Excelente. Compartida con Cudillero, es el centro turístico de la zona con todos los servicios. Arena dorada y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33039','playa','Playa de Las Llanas',NULL,'Buena. Cala recóndita a la que se accede por una senda peatonal escalonada. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33039','playa','Playa de Xilo (Veneiro)',NULL,'Muy buena. Pequeña prolongación de Aguilar separada por rocas, muy pintoresca. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33069','playa','Playa de Los Quebrantos',NULL,'Muy buena. Enorme arenal que forma una sola pieza con el playón de Bayas (Castrillón) en la boca del Nalón. Arena fina y oscura (volcánica/fósil). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33069','playa','Playa de El Garruncho',NULL,'Regular. Pequeña cala rocosa artificial junto al espigón de la desembocadura. Piedra y hormigón. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90012','playa','Playa de Salinas (y San Juan)',NULL,'Excelente. Una de las playas urbanas más largas de Asturias, meca del surf europeo. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90012','playa','Playón de Bayas (Sabugo)',NULL,'Excelente. El arenal continuo más largo de Asturias (casi 3 km), salvaje y con zona canina autorizada. Arena oscura y fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90012','playa','Playa de Arnao (Castrillón)',NULL,'Muy buena. Alberga una plataforma geológica con fósiles visibles y una piscina natural de roca. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90012','playa','Playa de Santa María del Mar',NULL,'Muy buena. Playa resguardada en una ensenada con una isla pequeña enfrente. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90012','playa','Playa de Munielles',NULL,'Buena. Dos calas que se unen en bajamar, de carácter tranquilo y rural. Arena fina y oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90012','playa','Playa de El Dique',NULL,'Aceptable. Pequeña cala junto al puerto de Avilés, muy abrigada. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33025','playa','Playa de Xagó',NULL,'Excelente. Espectacular arenal de casi 2 km respaldado por un gigantesco espacio de dunas salvajes. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33025','playa','Playa de Bañugues',NULL,'Muy buena. Ensenada circular muy abrigada donde el agua apenas tiene olas, ideal para niños. Arena fina y templada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33025','playa','Playa de Verdicio (Tenrero)',NULL,'Excelente. Playa de mar abierto con olas potentes y hermosas dunas, muy frecuentada. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33025','playa','Playa de Luanco (Santa María)',NULL,'Muy buena. Playa urbana principal del pueblo de Luanco, muy pintoresca y cómoda. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33025','playa','Playa de Aramar',NULL,'Buena. Conectada en bajamar con la isla del Carmen y su ermita. Arena fina, oscura y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33025','playa','Playa de San Pedro de Antromero',NULL,'Muy buena. Famosa por sus fósiles y su forma de concha perfecta. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33025','playa','Playa de Moniello',NULL,'Buena. Pequeña cala rocosa dotada de un parque y un paseo costero precioso. Compuesta de piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33025','playa','Playa de Llumeres',NULL,'Regular. Antigua zona minera de hierro, de gran valor geológico pero poco apta para el baño. Arena roja/oscura y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90011','playa','Playa de Candás (La Palmera)',NULL,'Muy buena. Playa urbana principal resguardada por el muelle, ambiente muy familiar. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90011','playa','Playa de Perán',NULL,'Aceptable. Situada en la desembocadura de un río, muy resguardada pero con fango en bajamar. Arena fina y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90011','playa','Playa de Carranques (Perlora)',NULL,'Excelente. Ubicada en la antigua Ciudad Vacacional de Perlora, rodeada de praderas verdes. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90011','playa','Playa de Huelgues (Perlora)',NULL,'Muy buena. Vecina de Carranques, rocosa en sus extremos e ideal para buscar cangrejos. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90011','playa','Playa de Xivares',NULL,'Muy buena. Gran playa de fuerte oleaje que se une con la playa de Peña María en bajamar. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33024','playa','Playa de San Lorenzo',NULL,'Excelente. Una de las playas urbanas más emblemáticas de España, con su famoso paseo ("El Muro"). Arena fina y tostada. No tiene Bandera Azul (por política municipal de gestión de calidad propia).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33024','playa','Playa de Poniente',NULL,'Muy buena. Playa artificial de aguas muy tranquilas creada en los años 90 en la zona del puerto. Arena dorada de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33024','playa','Playa del Arbeyal',NULL,'Buena. Segunda playa artificial de la ciudad, muy resguardada y de ambiente vecinal. Arena dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33024','playa','Playa de Peñarrubia',NULL,'Buena. Playa nudista flanqueada por altos acantilados fósiles, de acceso peatonal escarpado. Arena fina y grandes zonas de piedra/roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33024','playa','Playa de Estaño',NULL,'Muy buena. Cala pequeña de ambiente semiurbano con un pozo natural excavado en la roca ("El Pozo del Cura"). Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33024','playa','Playa de Serín',NULL,'Aceptable. Aislada y muy tranquila, frecuentada por nudistas. Orientación ventosa. Compuesta principalmente por piedra y algo de arena. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33076','playa','Playa de Rodiles','Bandera Azul','Excelente. Uno de los arenales más espectaculares del Cantábrico, flanqueado por un pinar y la ría. Arena fina y tostada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33076','playa','Playa de El Puntal',NULL,'Muy buena. Pequeña playa situada dentro de la ría de Villaviciosa, rodeada de un frondoso bosque. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33076','playa','Playa de Merón',NULL,'Buena. Playa rural aislada en la desembocadura del río Merón, fuerte oleaje. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33076','playa','Playa de Tazones',NULL,'Aceptable. Pequeño arenal urbano dentro del pintoresco puerto de Tazones. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33076','playa','Playa de Ñora (Límite con Gijón)',NULL,'Excelente. Preciosa cala encajada entre acantilados con una senda verde que llega hasta ella. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90015','playa','Playa de La Griega',NULL,'Excelente. Famosa mundialmente por albergar las huellas de dinosaurio más grandes del mundo en sus acantilados. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90015','playa','Playa de Lastres (L''Estilleru)',NULL,'Muy buena. Situada bajo el bellísimo pueblo de Lastres, resguardada y muy fotogénica. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90015','playa','Playa de La Isla',NULL,'Excelente. Debe su nombre a un islote al que se accede a pie en bajamar, paisaje idílico. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90015','playa','Playa de El Barrigón',NULL,'Buena. Unión natural de la playa de La Isla durante la bajamar, muy tranquila. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90015','playa','Playa de Espasa',NULL,'Excelente. Gran arenal abierto ideal para el vuelo de cometas y el surf, cuenta con todos los servicios. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90010','playa','Playa de Arenal de Morís',NULL,'Excelente. Playa paradisíaca de ambiente surfero, con praderías verdes que llegan hasta la misma arena. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90010','playa','Playa de Beciella',NULL,'Muy buena. Completamente virgen e idílica, cruzada por el Camino de Santiago. Compuesta por arena fina, cantos rodados y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90010','playa','Playa de Espasa (Parte oriental)',NULL,'Excelente. Compartida con Colunga, es un arenal espectacular de aguas limpias. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33056','playa','Playa de Santa Marina',NULL,'Excelente. Playa urbana espectacular flanqueada por impresionantes palacetes de indianos de principios del siglo XX. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33056','playa','Playa de Vega',NULL,'Excelente. Monumento natural. Impresionante playa salvaje de 2 km abierta al mar con un sistema de dunas único. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33056','playa','Playa de Arra',NULL,'Regular. La más oriental, sufrió desprendimientos en sus accesos. Entorno salvaje. Compuesta íntegramente por piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33056','playa','Playa de Aberdil',NULL,'Aceptable. Pequeña cala rocosa visible solo en bajamar, muy aislada. Piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Gulpiyuri',NULL,'Excelente. Monumento natural. Una de las playas más raras del mundo: está tierra adentro, entre prados, y el agua entra por túneles subterráneos. Arena fina y blanca. No tiene Bandera Azul (sin servicios directos).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Toró','Bandera Azul','Excelente. Paisaje alucinante único debido a las formaciones de roca caliza afilada que emergen de la arena. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Barro','Bandera Azul','Excelente. Bahía semicircular de aguas cristalinas totalmente protegida del oleaje por dos islotes. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Torimbia',NULL,'Excelente. Icono del nudismo en España, una concha perfecta rodeada de acantilados verdes colosales. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Poo',NULL,'Excelente. Playa en forma de embudo donde el mar entra suavemente creando una piscina natural perfecta para niños. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de San Antolín (Llanes)',NULL,'Excelente. El arenal más largo de Llanes (1.200 m), pegado a la carretera y meca del surf local. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Cuevas del Mar',NULL,'Excelente. Llamada así por las gigantescas cavidades talladas por el mar en las rocas que la rodean. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Sablón','Bandera Azul','Muy buena. Pequeña playa urbana en el mismo centro histórico de la villa de Llanes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Palombina (Celorio)','Bandera Azul','Excelente. Integrada en el núcleo de Celorio, paisaje espectacular salpicado de islotes. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Borizu',NULL,'Excelente. Preciosa cala unida al islote de Arnielles en bajamar por un pasillo de arena. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Ballota (Llanes)',NULL,'Excelente. Destaca por su potente "bufón" (surtidor de agua de mar) activo en días de temporal. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de Andrín',NULL,'Excelente. Vecina de Ballota, separada por el mirador de la Boriza; oleaje fuerte y entorno espectacular. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33036','playa','Playa de San Martín',NULL,'Muy buena. Playa virgen y aislada, ideal para el surf y con restos de una ermita románica. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33055','playa','Playa de La Franca',NULL,'Excelente. Gran playa familiar de Llanes/Ribadedeva, con cuevas y túneles rocosos accesibles en bajamar. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33055','playa','Playa de El Oso',NULL,'Muy buena. Pequeña cala unida a La Franca en bajamar, entorno virgen y muy tranquilo. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('33055','playa','Playa de El Regatón (Tinamayor)',NULL,'Regular. Playa de ría situada en la desembocadura del Deva, afectada fuertemente por mareas. Arena fina y fango. No tiene Bandera Azul. ¿Te parece bien que continuemos el listado con la provincia de A Coruña o prefieres dar el salto directo a la costa del mar Mediterráneo (como Castellón o Valencia)? Las respuestas de la IA pueden contener errores. Más información Has dicho: como tu quieras pero no te dejes ningujna Para asegurarnos de que no quede ni un solo municipio ni playa de España en el tintero, vamos a seguir un orden geográfico continuo y estricto. Recorreremos toda la península de norte a sur en sentido horario, y terminaremos con los archipiélagos. Aquí tienes la siguiente entrega para tu Word, que cubre toda la costa restante de Galicia (A Coruña y Pontevedra).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15044','playa','Playa de Bares',NULL,'Excelente. Impresionante arenal en forma de media luna resguardado por el puerto fenicio de Bares. Aguas tranquilas, cristalinas y arena blanca y finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15044','playa','Playa de Esteiro (Mañón)',NULL,'Muy buena. Situada en la desembocadura del río Sor, paisaje natural idílico con dunas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15044','playa','Playa de Vilela',NULL,'Buena. Pequeña cala resguardada en el interior de la ría de O Barqueiro. Arena fina y entorno verde. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15061','playa','Playa de Morouzos',NULL,'Excelente. Enorme arenal de más de 2 km rodeado de un imponente pinar y un entorno dunar protegido en plena ría de Ortigueira. Arena fina y negra (de origen mineral). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15061','playa','Playa de Espasante',NULL,'Muy buena. Playa semiurbana muy cómoda, abrigada de los vientos predominantes. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15061','playa','Playa de San Antonio',NULL,'Muy buena. Pequeña cala de aguas tranquilas y transparentes contigua a Espasante. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15061','playa','Playa de Céltigos',NULL,'Buena. Playa abierta al mar bravo con fuertes corrientes, entorno salvaje. Arena fina y zonas de piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
