INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15901','playa','Playa de A Basteira',NULL,'Muy buena. Gran playa urbana que bordea la ría de Ortigueira, con un agradable paseo marítimo. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15901','playa','Playa de Fornos',NULL,'Excelente. Espectacular cala de aguas tranquilas y cristalinas rodeada de montañas verdes. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15901','playa','Playa de Figueiras',NULL,'Buena. Pequeña y pedregosa, muy tranquila y aislada. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15022','playa','Playa de A Magdalena',NULL,'Excelente. Gran playa urbana situada en el interior de la bahía de Cedeira, aguas totalmente tranquilas ideales para niños. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15022','playa','Playa de Area Longa',NULL,'Buena. Situada en mar abierto, fuera de la protección de la bahía, con fuerte oleaje. Arena fina y zonas de piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15022','playa','Playa de Vilarrube',NULL,'Excelente (compartida con Valdoviño). Espectacular playa virgen en la desembocadura del río das Mestas. Aguas cristalinas y dunas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
