INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15087','playa','Playa de Pantín (O Rodo)',NULL,'Excelente. Famosa mundialmente por albergar el campeonato internacional "Pantín Classic" de surf. Ola perfecta y constante. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15087','playa','Playa de Vilarrube (Parte principal)',NULL,'Excelente. Bahía natural de aguas tranquilas y cálidas con forma de lengua de arena. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15087','playa','Playa de Baleo',NULL,'Muy buena. Playa salvaje encajonada entre acantilados, idónea para el surf. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15087','playa','Playa de Meirás (O Río)',NULL,'Muy buena. Pequeña playa rodeada de rocas, forma piscinas naturales en bajamar. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15087','playa','Playa de Campelo',NULL,'Buena. Playa salvaje encajada bajo acantilados verticales, acceso por escaleras y fuerte oleaje. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
