INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15048','playa','Playa Grande de Miño','Bandera Azul','Excelente. Enorme arenal urbano de aguas tranquilas y templadas, ideal para familias. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
