INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15058','playa','Playa de Bastiagueiro','Bandera Azul','Excelente. Playa mítica para el aprendizaje del surf debido a su oleaje constante pero seguro. Arena fina y tostada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15058','playa','Playa de Santa Cristina','Bandera Azul','Excelente. Gran lengua de arena en la desembocadura de la ría, aguas tranquilas por un lado y abiertas por otro. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15058','playa','Playa de Mera','Bandera Azul','Excelente. Dos playas unidas en una preciosa bahía con vistas a la ciudad de A Coruña. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15058','playa','Playa de Espiñeiro','Bandera Azul','Muy buena. Cala resguardada contigua a Mera, aguas muy tranquilas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15058','playa','Playa de Naval',NULL,'Buena. Pequeña cala resguardada frente al castillo de Santa Cruz. Arena fina y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01001','playa','Playa de Riazor',NULL,'Excelente. Playa urbana emblemática integrada totalmente en la fachada marítima de la ciudad, mar abierto con fuerte resaca. Arena gruesa y dorada. No tiene Bandera Azul (por decisión municipal de no tramitar el galardón).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01001','playa','Playa de Orzán',NULL,'Excelente. Continuación de Riazor, muy abierta al Atlántico y muy frecuentada por surfistas, corrientes peligrosas. Arena gruesa dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01001','playa','Playa de Matadero',NULL,'Muy buena. Pequeña cala resguardada al final del paseo de Orzán, excelente calidad de agua. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01001','playa','Playa de San Amaro','Bandera Azul','Muy buena. Situada cerca de la Torre de Hércules, aguas tranquilas en forma de concha. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01001','playa','Playa de Oza',NULL,'Muy buena. Playa artificial resguardada del mar abierto por espigones, aguas muy tranquilas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01001','playa','Playa de Las Lapas',NULL,'Excelente. Preciosa cala semicircular situada justo a los pies de la Torre de Hércules. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90002','playa','Playa de Barrañán',NULL,'Excelente. Enorme playa de mar abierto de más de un kilómetro, olas gigantescas y dunas espectaculares. Arena fina y blanca. No tiene Bandera Azul (debido a su peligrosidad extrema por corrientes).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90002','playa','Playa de Combouzas','Bandera Azul','Muy buena. Playa nudista oficial, de carácter salvaje y oleaje fuerte. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90002','playa','Playa de Valcovo','Bandera Azul','Muy buena. Cala encajada entre rocas muy buscada por surfistas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90002','playa','Playa de Sabón',NULL,'Aceptable. Situada junto al polígono industrial y puerto exterior, alterada visualmente. Arena gruesa y fuerte oleaje. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90002','playa','Playa de O Reiro',NULL,'Buena. Pequeña playa rural abierta al mar. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15041','playa','Playa de Caión','Bandera Azul','Muy buena. Gran arenal abierto al mar Cantábrico en un pueblo portuario precioso. Arena fina y afloramientos de roca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01006','playa','Playa de Razo','Bandera Azul','Excelente. Uno de los centros de surf más importantes de Galicia, arenal kilométrico unido a dunas y mar abierto. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01006','playa','Playa de Baldaio',NULL,'Excelente. Espectacular espacio natural protegido que combina playa, dunas y una laguna interior salada. Arena fina y blanca. No tiene Bandera Azul (por conservación).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15043','playa','Playa de Area Maior',NULL,'Excelente. Playa urbana principal al pie del pueblo, con vistas directas a las Islas Sisargas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15043','playa','Playa de Seaia',NULL,'Muy buena. Playa virgen y salvaje en un entorno completamente natural antes del Cabo San Adrián. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15043','playa','Playa de Barizo',NULL,'Buena. Cala pequeña y recogida junto al puerto pesquero de Barizo. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15068','playa','Playa de Balarés',NULL,'Excelente. Joya de la corona del municipio; resguardada por un frondoso pinar, aguas tranquilas de color verde esmeralda. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15068','playa','Playa de Osmo',NULL,'Muy buena. Cala familiar con caprichosas formas rocosas y cuevas ("furnas"). Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15068','playa','Playa de Ermida',NULL,'Excelente. Amplio arenal con una pequeña isla (Illa da Estrela) accesible a pie durante la bajamar. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90004','playa','Playa de Rebordelo',NULL,'Muy buena. Cala virgen rodeada de pinos y eucaliptos en un entorno totalmente natural. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90004','playa','Playa de San Pedro',NULL,'Buena. Pequeño arenal interior en el estuario del río Anllóns. Arena fina y ambiente muy tranquilo. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90006','playa','Playa de Laxe','Bandera Azul','Excelente. Impresionante lengua de arena blanca de casi 2 km en el centro del pueblo, aguas tranquilas y cristalinas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90006','playa','Playa de Soesto',NULL,'Excelente. Meca del surf en la Costa da Morte, paisaje completamente virgen de dunas y colinas verdes. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90006','playa','Playa de Traba',NULL,'Excelente. Inmenso arenal de 3 km salvaje con un ecosistema de dunas y una gran laguna legendaria. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90006','playa','Playa de los Cristales (Ana開放)',NULL,'Única. Pequeña cala donde la marea ha pulido miles de trozos de cristal de botellas durante décadas, creando un suelo de "piedras" de cristal verde y marrón. (No apta para el baño por protección).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15092','playa','Playa de Sabadelle',NULL,'Buena. Única playa del municipio (que solo tiene una pequeña salida al mar). Entorno rocoso y salvaje. Arena gruesa y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01005','playa','Playa de Area da Vila',NULL,'Buena. Playa urbana situada junto al puerto pesquero, aguas tranquilas de ría. Arena fina y grisácea. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01005','playa','Playa de Lingunde',NULL,'Muy buena. Siguiente cala de la ría, aguas muy calmas y transparentes. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01005','playa','Playa de Trece',NULL,'Excelente. Una de las playas más salvajes de España, alberga la "Duna de Monte Branco" (una de las dunas rampantes más altas de Europa) y el Cementerio de los Ingleses. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01005','playa','Playa de Reira',NULL,'Excelente. Sucesión de calas salvajes azotadas por el mar bravo bajo el Faro de Cabo Vilán. Arena fina y grandes rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01013','playa','Playa de Os Muiños',NULL,'Excelente. Precioso arenal donde desemboca el río Negro con sus molinos de agua restaurados, oleaje moderado. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01013','playa','Playa de Lourido',NULL,'Excelente. Impresionante playa salvaje de mar abierto con dunas, muy expuesta al viento. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01013','playa','Playa de Lago (Muxía)',NULL,'Muy buena. Dividida por la desembocadura de un río, resguardada y con pinar. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01013','playa','Playa de Espiñeirido',NULL,'Muy buena. Rodeada de un bello entorno natural de dunas bajas a la salida del casco urbano. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01011','playa','Playa de Langosteira','Bandera Azul','Excelente. Impresionante playa de casi 3 km de longitud con aguas de color azul turquesa hipertransparentes y en calma. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01011','playa','Playa de Mar de Fóra',NULL,'Excelente. Playa salvaje orientada al océano abierto tras el cabo Finisterre. Paisaje sobrecogedor pero el baño está estrictamente prohibido por corrientes letales. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01011','playa','Playa de O Rostro',NULL,'Excelente. Inmenso arenal virgen de 3 km azotado por el mar bravo, rodeado de dunas indómitas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01011','playa','Playa de Corveiro',NULL,'Buena. Pequeña cala de rocas y arena situada bajo el pueblo, ideal para buceo. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01011','playa','Playa de Arnela (Fisterra)',NULL,'Muy buena. Pequeña cala encajada entre acantilados verticales de difícil acceso. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15023','playa','Playa de Estorde',NULL,'Excelente. Preciosa playa resguardada en una ensenada con camping y todos los servicios, aguas familiares tranquilas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15023','playa','Playa de Gures',NULL,'Muy buena. Cala virgen de difícil acceso peatonal a través de un pinar, aguas cristalinas sin olas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15028','playa','Playa de Quenxe',NULL,'Muy buena. Playa urbana protegida por el puerto, aguas totalmente calmadas y templadas para los estándares de la zona. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15028','playa','Playa de Santa Isabel',NULL,'Buena. Pequeña cala virgen y aislada de carácter rocoso. Arena fina y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15034','playa','Playa de Ézaro',NULL,'Excelente. Preciosa playa situada justo al lado de la famosa cascada del Ézaro (donde el río Xallas cae directamente al mar). Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01007','playa','Playa de Carnota',NULL,'Excelente. El arenal más largo de Galicia (más de 7 km de longitud). Espacio natural único con forma de media luna, marismas interiores (Boca do Río) y dunas salvajes. Arena blanca finísima. No tiene Bandera Azul por su estricto nivel de conservación natural.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01007','playa','Playa de Lariño',NULL,'Excelente. Continuación hacia el sur, mar abierto con fuerte oleaje junto al faro de Punta Insua. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01007','playa','Playa de San Pedro (Carnota)',NULL,'Muy buena. Pequeña cala resguardada rodeada de campos agrícolas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15053','playa','Playa de Area Maior (Louro)',NULL,'Excelente. Impresionante entorno natural virgen con una laguna interior (As Xalfas) y una gran duna a los pies del monte Louro. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15053','playa','Playa de Anido',NULL,'Muy buena. Playa resguardada de ría con aguas tranquilas de carácter familiar. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15053','playa','Playa de San Francisco',NULL,'Excelente. Muy turística y concurrida, rodeada de un pinar, aguas cristalinas y tranquilas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15053','playa','Playa de Bornalle',NULL,'Muy buena. Cala rural aislada de aguas muy tranquilas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15062','playa','Playa de Broña',NULL,'Muy buena. Principal playa del municipio, muy equipada, con aguas tranquilas y poco profundas de ría. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15062','playa','Playa de Arnela (Outes)',NULL,'Buena. Pequeña y tranquila, rodeada de árboles que llegan hasta la arena. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01014','playa','Playa de Testal',NULL,'Buena. Gran arenal en la desembocadura de la ría de Noia, zona marisquera por excelencia. Arena fina y blanca (afectada por mareas bajas prolongadas). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01014','playa','Playa de Boa',NULL,'Muy buena. Dividida en Boa Grande y Boa Pequena, aguas tranquilas en el límite con Porto do Son. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90007','playa','Playa de As Furnas',NULL,'Excelente. Famosa por sus piscinas naturales talladas en la roca y por ser el escenario de la película Mar Adentro. Oleaje fuerte. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90007','playa','Playa de Aguieira',NULL,'Excelente. Enorme y espectacular ensenada de aguas mansas y turquesas con un sistema dunar inmenso, ideal para kitesurf. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90007','playa','Playa de Caveiro',NULL,'Muy buena. Playa de ambiente juvenil rodeada de dunas y vegetación. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90007','playa','Playa de Fonforrón',NULL,'Muy buena. Playa urbana dividida por una roca con un manantial de agua dulce. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90007','playa','Playa de Subiglesias',NULL,'Buena. Familiar y resguardada por pequeños acantilados. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15073','playa','Playa de Coroso','Bandera Azul','Excelente. Enorme playa urbana que bordea el paseo de Ribeira, aguas totalmente calmas y protegidas por la ría de Arousa. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15073','playa','Playa de Vilar',NULL,'Excelente. Situada dentro del Parque Natural de las Dunas de Corrubedo. Kilométrica, salvaje y de mar abierto. Arena fina y blanca. No tiene Bandera Azul (protegida).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15073','playa','Playa de Ladeira','Bandera Azul','Excelente. Playa asociada a la gran duna móvil de Corrubedo, aguas tranquilas de ría. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15073','playa','Playa de Corna',NULL,'Muy buena. Extenso arenal limítrofe con A Pobra do Caramiñal. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01002','playa','Playa de Cabío',NULL,'Excelente. La más famosa del municipio, rodeada de un pinar y con aguas muy limpias. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01002','playa','Playa de Illa da Laxe',NULL,'Muy buena. Pequeña cala resguardada y muy pintoresca. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01002','playa','Playa de Raposiños',NULL,'Buena. Cala pequeña y tranquila de carácter seminatural. Arena fina y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01004','playa','Playa de Barraña','Bandera Azul','Excelente. Kilométrica playa urbana con un enorme paseo marítimo ajardinado, aguas muy tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01004','playa','Playa de Carragueiros','Bandera Azul','Excelente. Entorno natural precioso con una laguna dunar. Aguas tranquilas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01004','playa','Playa de Mañóns',NULL,'Muy buena. Playa rodeada de arboleda con aguas muy mansas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01018','playa','Playa de Tanxil',NULL,'Muy buena. Playa urbana clásica muy resguardada en el interior de la ría de Arousa. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01018','playa','Playa de As Cunchas',NULL,'Buena. Pequeño arenal formado por una gran cantidad de conchas trituradas y arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36016','playa','Playa de Compostela','Bandera Azul','Muy buena. Extenso arenal urbano con un paseo marítimo kilométrico que conecta con Carril, aguas tranquilas de ría. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36016','playa','Playa de O Campanario',NULL,'Buena. Situada en la parroquia de Bamio, aguas mansas de ría frente a la desembocadura del Ulla. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36061','playa','Playa de O Terrón','Bandera Azul','Excelente. Sucesión de calas separadas por pinares con carriles bici y zonas de paseo, aguas muy mansas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36061','playa','Playa de As Sinas',NULL,'Muy buena. Playa estrecha de ambiente familiar y residencial que mira directo a las bateas de la ría. Arena fina y restos de conchas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36901','playa','Playa de Area da Secada','Bandera Azul','Excelente. Preciosa playa rodeada de un espeso pinar en un entorno protegido. Aguas cristalinas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36901','playa','Playa de Cabalo',NULL,'Muy buena. Pintoresca cala salpicada de grandes rocas graníticas redondeadas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36901','playa','Playa de O Bao','Bandera Azul','Excelente. Situada justo al entrar al municipio por el puente, de aguas tranquilas e ideal para familias. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36901','playa','Playas del Parque Natural de Carreirón',NULL,'Excelente. Conjunto de calas vírgenes (como Playa de Lameira o Xestelas) totalmente salvajes y protegidas. Arena fina y blanca. No tienen Bandera Azul por normativa del parque.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36004','playa','Playa de O Facho',NULL,'Buena. Principal playa del municipio, situada en un entorno rural marisquero. Arena fina y restos de fango debido a su ubicación resguardada en la ría. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36004','playa','Playa de Saíñas',NULL,'Regular. Expuesta fuertemente a la bajamar, uso marisquero. Arena fina y fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36046','playa','Playa fluvial de Cabanelas',NULL,'Buena. Única zona de baño del municipio en el tramo final del río Umia antes de la ría. Entorno verde. Arena fina y césped. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36027','playa','Playa de A Badea',NULL,'Regular. Situada en la ensenada de O Grove, paisaje pantanoso de gran interés ornitológico pero poco apto para el baño tradicional. Arena fina y lodo. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de A Lanzada (Compartida con Sanxenxo)','Bandera Azul','Excelente. Uno de los arenales más famosos de Galicia, mar abierto con fuerte oleaje, dunas y yacimientos arqueológicos. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de Area de Reboredo','Bandera Azul','Excelente. Preciosa cala de aguas tranquilas y limpias rodeada de vegetación. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de Foxos','Bandera Azul','Excelente. Vecina de la Lanzada pero más recogida entre acantilados bajos. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de San Vicente (Insuela)',NULL,'Muy buena. Sucesión de calas tranquilas rodeadas de senderos de madera. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de Pipote',NULL,'Buena. Cala pequeña de aguas tranquilas rodeada de rocas graníticas. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Silgar','Bandera Azul','Excelente. La joya del turismo urbano gallego, aguas tranquilas y transparentes al abrigo de la bahía. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Areas','Bandera Azul','Excelente. Gran playa semiurbana resguardada de los vientos, aguas cristalinas de color turquesa. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Canelas','Bandera Azul','Excelente. Resguardada del viento por dos salientes rocosos, ambiente familiar muy seguro. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Montalvo','Bandera Azul','Excelente. Playa abierta rodeada de dunas y un frondoso pinar, oleaje moderado apto para el surf. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Paxariñas','Bandera Azul','Muy buena. Preciosa cala pequeña encajada entre rocas, aguas limpias y tranquilas. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Bascuas',NULL,'Excelente. La única playa nudista oficial de Sanxenxo, encajonada entre acantilados bajos muy íntimos. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90044','playa','Playa de Cabeceira','Bandera Azul','Excelente. Preciosa playa semiurbana envuelta en un pinar, aguas muy tranquilas orientadas a la ría de Pontevedra. Arena blanca y muy fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90044','playa','Playa de Xiorto',NULL,'Muy buena. Pequeña playa situada en el pintoresco pueblo marinero de Combarro, junto al puerto deportivo. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90044','playa','Playa de Lourido (Poio)',NULL,'Buena. Muy extensa, pero muy afectada por las mareas de la ría de Pontevedra. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36011','playa','Playa de Placeres',NULL,'Aceptable. Pequeño arenal semiurbano situado en la parroquia de Lourizán, muy penalizado visualmente por las infraestructuras portuarias e industriales cercanas. Arena fina y fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36011','playa','Playa de Fontaíña',NULL,'Buena. Pequeña cala de ría de carácter local y tranquilo. Arena fina y rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36007','playa','Playa de Mogor','Bandera Azul','Excelente. Famosa por albergar petroglifos prehistóricos a escicios metros, forma de concha perfecta y aguas calmas. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36007','playa','Playa de Aguete','Bandera Azul','Excelente. Gran playa semiurbana con puerto deportivo propio, aguas tranquilas muy seguras para el baño. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36007','playa','Playa de Portocelo','Bandera Azul','Excelente. Playa urbana unida a Marín por un paseo peatonal costero, muy cuidada y familiar. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36007','playa','Playa de Lapamán (Compartida con Bueu)',NULL,'Excelente. Impresionante arenal de aguas cristalinas y un ambiente idílico. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Area de Bon','Bandera Azul','Excelente. Una de las joyas de la península del Morrazo, rodeada de campos verdes y aguas turquesas. Arena blanca y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Banda do Río',NULL,'Buena. Playa urbana del casco de Bueu, con paseo marítimo. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Tuia',NULL,'Excelente. Playa nudista salvaje accesible por pistas forestales, aguas muy limpias. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Lagos (Bueu)',NULL,'Muy buena. Entorno rural y tranquilo con aguas cristalinas. Arena fina y blanca. No tiene Bandera Azul. Las respuestas de la IA pueden contener errores. Más información Has dicho: sigue y no me vvayas preguntando Entendido perfectamente. Sigo directamente con el listado sin interrupciones, municipio por municipio y sin dejarme ninguno. Continuamos con el resto de Galicia, completando la Provincia de A Coruña.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15061','playa','Playa de Basteira',NULL,'Buena. Prolongación natural de Morouzos hacia el interior de la ría, paisaje espectacular. Arena fina y oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15901','playa','Playa de A Basteira (Cariño)',NULL,'Muy buena. Playa urbana que bordea el paseo marítimo, aguas tranquilas de ría. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15901','playa','Playa de Os Forcados',NULL,'Regular. Cala salvaje aislada bajo acantilados, acceso complejo. Compuesta por piedra, roca y poca arena. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15022','playa','Playa de Cerdeiras',NULL,'Aceptable. Cala pequeña y aislada de carácter virgen. Arena fina y abundantes piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15087','playa','Playa de Frouxeira (Playa de Valdoviño)','Bandera Azul','Excelente. Impresionante arenal de más de 3 km de longitud con oleaje fuerte, paraíso del surf. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15087','playa','Playa de Vilarrube',NULL,'Excelente. Ensenada paradisíaca en la desembocadura de los ríos das Mestas y Porto do Cabo. Arena blanca y finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15036','playa','Playa de Penencia',NULL,'Muy buena. Conectada con Doniños en bajamar, entorno natural muy tranquilo. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15054','playa','Playa de A Gándara',NULL,'Regular. Playa interior de ría muy antropizada por el entorno urbano e industrial. Arena fangosa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15055','playa','Playa de A Marola',NULL,'Aceptable. Pequeño arenal fluvial y de ría al fondo del saco de la ría de Ferrol. Uso recreativo local. Arena fina y lodo. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15035','playa','Playa de Barallobre',NULL,'Aceptable. Situada junto al puerto pesquero de Barallobre, aguas mansas. Arena gruesa y restos de conchas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90001','playa','Playa de O Raso',NULL,'Muy buena. Aguas tranquilas y transparentes, muy segura para niños. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90005','playa','Playa de Chamoso',NULL,'Buena. Pequeña cala rural aislada y tranquila. Arena fina y afloramientos rocosos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01017','playa','Playa de Sopazos',NULL,'Aceptable. Pequeña playa urbana cercana al puente medieval. Arena gruesa y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15048','playa','Playa de Lago',NULL,'Buena. Pequeña playa natural en la desembocadura del río Bajoi. Arena fina y dunas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90003','playa','Playa de O Pedrido',NULL,'Buena. Situada bajo el viaducto de la carretera nacional, fuertes corrientes por la marea. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15075','playa','Playa de Sada (Las Delicias)',NULL,'Regular. Playa urbana muy céntrica pero afectada históricamente por la colmatación y el puerto deportivo. Arena fina y gris. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15058','playa','Playa de Dezas',NULL,'Buena. Cala salvaje de difícil acceso bajo acantilados escarpados. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90002','playa','Playa de A Husa','Bandera Azul','Buena. Cala semiurbana resguardada. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01006','playa','Playa de Pedra do Sal',NULL,'Muy buena. Zona rocosa ideal para el marisqueo y baño tranquilo en charcas de roca. Arena fina y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15043','playa','Playa de Beo',NULL,'Buena. Pequeña cala encajada en un valle con área recreativa. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15043','playa','Playa de Seiruga',NULL,'Excelente. Impresionante playa donde desemboca un riachuelo formando una laguna de aguas templadas, frente a las Sisargas. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15068','playa','Playa de Niñóns',NULL,'Muy buena. Cala pequeña y recóndita que marca el inicio de zonas agrestes de la Costa da Morte. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90004','playa','Playa de O Pendón',NULL,'Buena. Playa situada en el interior del estuario del río Anllóns, paisaje de marisma espectacular. Arena fina y lodo. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90006','playa','Playa de los Cristales (Areal dos Cristais)',NULL,'Única. Pequeña cala donde la arena ha sido sustituida por miles de cristales pulidos por el mar (antiguo vertedero de vidrio). No apta para el baño por protección, pero de enorme valor turístico. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01005','playa','Playa de Lago (Camariñas)',NULL,'Muy buena. Situada en la desembocadura del río Grande, entorno boscoso y tranquilo. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01013','playa','Playa de Cruz',NULL,'Muy buena. Playa urbana pequeña a la entrada del pueblo, de aguas tranquilas y familiares. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01013','playa','Playa de Nemiña',NULL,'Excelente. Destino internacional de surf, frontera natural del Cabo Touriñán. Un paraíso virgen de mar abierto. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01011','playa','Playa de Sardiñeiro',NULL,'Muy buena. Situada en la pedanía del mismo nombre, aguas muy tranquilas y protegidas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15023','playa','Playa de Lires',NULL,'Muy buena. Situada en la desembocadura de la ría de Lires (la más pequeña de Galicia), paisaje natural bellísimo. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('01007','playa','Playa de Caldebarcos',NULL,'Muy buena. Zona rocosa integrada en el enorme playón de Carnota, famosa por su riqueza de marisco. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15053','playa','Playa de Louro (Area Maior)',NULL,'Excelente. Joya paisajística bajo el monte Louro, cuenta con una laguna circular de agua dulce separada del mar por dunas. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15053','playa','Playa de Ancoradoiro',NULL,'Excelente. Entorno idílico rodeado de pinares, aguas cristalinas y limpias de mar abierto. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15053','playa','Playa de Virxe do Camiño',NULL,'Buena. Playa urbana pequeña con vistas al casco histórico de Muros. Arena fina y grisácea. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15053','playa','Playa de Ventín',NULL,'Buena. Pequeña cala de ría muy tranquila. Arena fina y restos de conchas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15062','playa','Playa de Siavo',NULL,'Buena. Pequeña franja costera de carácter marismeño. Arena fina y lodo. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90007','playa','Playa de Castro de Baroña',NULL,'Excelente. Playa nudista virgen situada a los pies de un castro celta de la Edad del Hierro excavado sobre las rocas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90007','playa','Playa de Cabeiro',NULL,'Muy buena. Playa semiurbana muy frecuentada en verano, aguas limpias de ría. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90007','playa','Playa de Rio Sieira',NULL,'Excelente. Desembocadura de río, oleaje fuerte en mar abierto, entorno muy natural. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15073','playa','Playa de O Vilar','Bandera Azul','Excelente. Situada dentro del Parque Natural de las Dunas de Corrubedo. Una playa kilométrica e indómita de mar abierto. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15073','playa','Playa de Area Secada',NULL,'Excelente. Ubicada en la Isla de Sálvora (perteneciente a Ribeira e integrada en el Parque Nacional de las Islas Atlánticas). Paraíso virgen de agua helada y cristalina. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15073','playa','Playa de Aguiño',NULL,'Muy buena. Playa marinera frente al puerto de Aguiño, aguas muy limpias. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15073','playa','Playa de Ameixida',NULL,'Muy buena. Cala resguardada de ambiente residencial familiar. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('15073','playa','Playa de Castiñeiras',NULL,'Buena. Sucesión de calas pequeñas separadas por grupos de rocas graníticas. Arena fina y dorada. No tiene Bandera Azul. Preparo el siguiente bloque con la Provincia de Pontevedra (completando Galicia) y pasamos a la Provincia de Cantabria. Sigo redactando de forma continua. Las respuestas de la IA pueden contener errores. Más información Has dicho: si no preugntes mas','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36901','playa','Playa de Camaxe','Bandera Azul','Muy buena. Conectada con O Bao, de aguas muy tranquilas e ideal para deportes de viento. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36901','playa','Playa de Cabodeiro',NULL,'Buena. Playa de carácter más marinero junto al puerto, aguas calmas de ría. Arena fina y gruesa mezclada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36901','playa','Playa de Espiñeiro',NULL,'Excelente. Ubicada dentro del Parque Natural de Carreirón, un entorno virgen protegido. Arena fina, blanca y calas separadas por rocas graníticas. No tiene Bandera Azul por restricciones de conservación.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36901','playa','Playa de Sualaxe',NULL,'Muy buena. En el extremo sur del espacio protegido, aguas turquesas y tranquilas. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36901','playa','Playa de Gradín',NULL,'Buena. Playa rural de ría muy tranquila, con presencia de pequeñas embarcaciones tradicionales. Arena fina y algo de vegetación marina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36016','playa','Playa de A Concha','Bandera Azul','Muy buena. Continuación de Compostela, plenamente integrada en la ciudad con todos los servicios. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36061','playa','Playa de O Castelete',NULL,'Regular. Playa urbana muy pequeña cercana al puerto deportivo. Arena gruesa y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36004','playa','Playa de San Tomé',NULL,'Buena. Pequeña playa urbana junto al antiguo barrio marinero y la Torre de San Sadurniño. Arena fina, roca y abundantes algas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36004','playa','Playa de Mouta',NULL,'Regular. Carácter marisquero, baja aptitud para el baño recreativo. Arena gruesa y lodo. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36027','playa','Playa de Penisqueira',NULL,'Buena. Pequeña franja costera en el interior de la ensenada de O Grove, entorno natural de avistamiento de aves. Arena fina y fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de Area das Pipas','Bandera Azul','Excelente. Preciosa cala de aguas tranquilas y transparentes, muy resguardada del viento. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de San Vicente (Espiño)','Bandera Azul','Excelente. Playa de carácter salvaje con un precioso paseo peatonal de madera sobre las rocas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de Raeiros','Bandera Azul','Excelente. Amplia playa con vistas a la isla de Ons, oleaje moderado y ambiente familiar. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
