INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de Area Grande',NULL,'Muy buena. Situada en la cara norte de la península, aguas cristalinas pero bastante frías. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de Canelas (O Grove)',NULL,'Buena. Pequeña cala rural aislada y tranquila. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de Con Negro',NULL,'Excelente. Entorno completamente salvaje y rocoso, calas aisladas de una belleza descarnada. Arena fina y piedras graníticas. No tiene Bandera Azul por falta de accesos urbanizados.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Major','Bandera Azul','Excelente. Extenso arenal dotado de un complejo dunar protegido de alto valor ecológico. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Foxos','Bandera Azul','Excelente. Situada al inicio de la península de O Grove, fuerte oleaje y entorno histórico junto a una ermita. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Area de Agra','Bandera Azul','Muy buena. Cala salvaje encajada entre altos acantilados verdes, aguas de color turquesa. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Panadeira','Bandera Azul','Muy buena. Pequeña playa urbana muy tranquila, resguardada en el centro del pueblo. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90044','playa','Playa de Chancelas',NULL,'Buena. Amplio arenal de ría con zonas de fondeo de embarcaciones tradicionales. Arena fina y zonas de piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90044','playa','Playa de Ouriceira',NULL,'Buena. Cala tranquila de carácter semiurbano. Arena fina y restos de conchas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90044','playa','Playa de Campelo',NULL,'Regular. Próxima a zona de marisqueo tradicional, afectada por la marea. Arena gruesa y fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36011','playa','Playa fluvial de Ponte Sampaio',NULL,'Buena. Zona de baño interior acondicionada junto al puente histórico sobre el río Verdugo. Arena fina y césped. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36007','playa','Playa de Loira','Bandera Azul','Muy buena. Situada en la desembocadura de un riachuelo, ambiente muy familiar y resguardado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36007','playa','Playa de Santo do Mar',NULL,'Buena. Conectada en bajamar con un islote que alberga restos de una antigua ermita. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
