INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Bandaorrío','Bandera Azul','Muy buena. Playa urbana con excelentes equipamientos e integrada en el puerto pesquero de Bueu. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Lagos','Bandera Azul','Muy buena. Playa rural abierta al inicio de la ría de Aldán, aguas frías e hipertransparentes. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Portomaior','Bandera Azul','Excelente. Gran arenal resguardado de aguas cristalinas y arena fina muy compacta. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Melide (Isla de Ons)',NULL,'Excelente. Situada en la joya insular de Ons (Parque Nacional de las Islas Atlánticas). Un paraíso virgen de aguas caribeñas y gélidas. Arena fina y blanca. No tiene Bandera Azul por protección estricta.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Canexol (Isla de Ons)',NULL,'Muy buena. Junto a la aldea pesquera de la isla, aguas mansas. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90042','playa','Playa de Rodas (Islas Cíes - Pertenece al término municipal de Vigo)',NULL,'(Nota: Se describe en Vigo por gestión administrativa histórica de las islas).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90042','playa','Playa de Nerga','Bandera Azul','Excelente. Enorme complejo playero virgen con dunas finísimas y aguas transparentes frente a las Cíes. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90042','playa','Playa de Barra',NULL,'Excelente. Considerada la mejor playa nudista de Galicia, entorno totalmente virgen rodeado de un pinar inmenso. Arena blanca finísima. No tiene Bandera Azul por su estatus natural.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90042','playa','Playa de Melide (Cangas)','Bandera Azul','Excelente. Espectacular cala salvaje encajada entre los acantilados de Cabo Home, mar abierto con oleaje. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90042','playa','Playa de Menduíña','Bandera Azul','Excelente. Cala mítica de la ría de Aldán, aguas en calma absoluta de color turquesa y servicios excelentes. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
