INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39044','playa','Playa de Robayera',NULL,'Buena. Pequeña cala rocosa idónea para la pesca deportiva y el buceo. Arena fina y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39052','playa','Playa de Valdearenas (Liencres)',NULL,'Excelente. Situada en el Parque Natural de las Dunas de Liencres. Un entorno paradisíaco de dunas gigantes, pinares y olas espectaculares para el surf. Arena fina y dorada. No tiene Bandera Azul por el fuerte oleaje.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39052','playa','Playa de Canallave',NULL,'Excelente. Contigua a Valdearenas, muy cotizada por escuelas de surf por la constancia de sus olas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39052','playa','Playa de Somocuevas',NULL,'Excelente. Dividida en dos calas por una gran roca, es una playa de tradición nudista muy protegida del viento. Arena blanca y finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39052','playa','Playa de Portio',NULL,'Muy buena. Rodeada de impresionantes estructuras de roca caliza cortadas verticalmente. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39052','playa','Playa de La Arnía',NULL,'Excelente. Paisaje geológico único con una espectacular plataforma de abrasión y "urros" (islotes de roca afilada) saliendo del agua. Arena fina y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39052','playa','Playa de Pedruquios',NULL,'Buena. Sucesión de pequeñas calas salvajes de piedra visibles solo en bajamar. Compuesta por piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39073','playa','Playa de San Juan de la Canal',NULL,'Excelente. Preciosa cala semiurbana resguardada por un islote al que se puede cruzar a pie en bajamar. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39073','playa','Playa de Covachos',NULL,'Excelente. Impresionante cala virgen unida al islote de Castro por un tómbolo de arena visible solo en bajamar. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de El Sardinero (1 y 2)',NULL,'Excelente. Playas urbanas señoriales de fama mundial, amplios paseos y jardines históricos, oleaje moderado. Arena fina y dorada. No tiene Bandera Azul (por gestión integral propia de playas del ayuntamiento).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de Los Bikinis',NULL,'Excelente. Situada dentro de la bahía de Santander junto al Palacio de la Magdalena, aguas completamente calmas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de La Magdalena',NULL,'Muy buena. Ubicada en la península del Palacio de la Magdalena, aguas muy calmas ideales para niños. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de Mataleñas',NULL,'Excelente. Preciosa cala encajada entre los cabos de Menor y Mayor, acceso por escaleras y entorno muy exclusivo. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de Los Peligros',NULL,'Muy buena. Situada dentro de la bahía de Santander, protegida del mar por espigones, oleaje nulo y agua templada. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de El Camello',NULL,'Muy buena. Debe su nombre a una roca cuya silueta se asemeja a dicho animal, ambiente familiar muy popular. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de El Puntal (Extremo Occidental)',NULL,'Muy buena. Pequeña lengua de arena accesible en barco desde el paseo marítimo. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de Virgen del Mar',NULL,'Muy buena. Situada junto a la ermita de la patrona de la ciudad, en un entorno de acantilados azotados por el Cantábrico. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39016','playa','Playa de Punta Parayas',NULL,'Aceptable. Playa artificial creada en el interior de la bahía de Santander, junto al aeropuerto. Aguas estancadas y sin olas. Arena gruesa y césped artificial perimetral. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90030','playa','Playa de la Planchada',NULL,'Regular. Antigua zona de baño industrial hoy recuperada como paseo marítimo sobre la ría de Solía, no apta para baño convencional. Lodo y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39040','playa','Playa de El Rostro',NULL,'Buena. Situada en Pedreña, dentro de la bahía de Santander, aguas tranquilas ideales para el marisqueo y contemplar la ciudad. Arena fina y fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39061','playa','Playa de Somo',NULL,'Excelente. Impresionante arenal de más de 2 km unido a Loredo, primera Reserva de Surf de España. Vistas espectaculares a Santander. Arena blanca finísima. No tiene Bandera Azul (enfocada a la conservación natural del surf).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39061','playa','Playa de Loredo',NULL,'Excelente. Continuación de Somo, famosa por sus carreras de caballos en la arena durante el verano y sus escuelas de surf. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39061','playa','Playa de El Puntal',NULL,'Excelente. Impresionante flecha de arena de más de 2 km que se adentra en la bahía de Santander, aguas cristalinas a ambos lados. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39061','playa','Playa de Langre',NULL,'Excelente. Considerada una de las playas más bonitas de Cantabria; un semicírculo perfecto bajo acantilados verticales de 25 metros. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39061','playa','Playa de Galizano (La Arena)',NULL,'Muy buena. Situada en la desembocadura del río Herrera, resguardada y con pozas naturales en las rocas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90029','playa','Playa de Ajo (Antuerta)',NULL,'Excelente. Cala salvaje rodeada de acantilados agrestes, muy valorada por surfistas y nudistas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90029','playa','Playa de Cuberris',NULL,'Excelente. Gran playa semiurbana con buenos servicios, abierta al mar Cantábrico con oleaje moderado. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90028','playa','Playa de Los Locos (Isla)','Bandera Azul','Excelente. Hermosa playa urbana resguardada con forma de concha y aguas hipertransparentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90028','playa','Playa de El Sable (Isla)','Bandera Azul','Excelente. Muy segura para el baño infantil debido a su nulo oleaje, entorno turístico totalmente equipado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90028','playa','Playa de Arnadal',NULL,'Muy buena. Pequeña cala tranquila rodeada de formaciones rocosas. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90028','playa','Playa de Cándano',NULL,'Buena. Cala salvaje de baja ocupación y carácter natural. Arena gruesa y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39047','playa','Playa de Trengandín',NULL,'Excelente. Espectacular paisaje kárstico lunar donde emergen cientos de rocas afiladas de la arena en bajamar, aguas hipertransparentes. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39047','playa','Playa de Ris',NULL,'Excelente. Kilométrica playa urbana dotada de un gran sistema dunar y orientada hacia el norte, fuerte oleaje y múltiples servicios. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('10002','playa','Playa de El Regatón (Bárcena)',NULL,'Buena. Situada en el interior de la reserva natural de las Marismas de Santoña, entorno de estuario muy tranquilo. Arena fina y fango. No tiene Bandera Azul. Las respuestas de la IA pueden contener errores. Más información Has dicho: sigue','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36016','playa','Playa de Canelas (Vilagarcía)',NULL,'Buena. Pequeña playa semiurbana de carácter tranquilo y aguas limpias. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36016','playa','Playa de Bamio',NULL,'Buena. Situada en la desembocadura del río Ulla, paisaje muy bonito pero sometida a fuertes corrientes de marea. Arena fina y zonas de fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36004','playa','Playa de A Mouta',NULL,'Aceptable. Pequeño arenal de carácter intermareal muy afectado por la bajamar. Arena gruesa y lodo. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Areas Gordas','Bandera Azul','Excelente. Comparte entorno natural con Foxos, aguas limpísimas y transparentes. Arena fina y restos calcáreos. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Lapa','Bandera Azul','Excelente. Se une a la gran playa de La Lanzada, entorno natural protegido de dunas. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36013','playa','Playa de Pragueira','Bandera Azul','Excelente. Preciosa playa de mar abierto que se une con Foxos en bajamar, paisaje salvaje. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de A Lanzada','Bandera Azul','Excelente. Uno de los arenales más famosos de España (compartido con Sanxenxo), de más de 2 km en mar abierto con dunas protegidas. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36009','playa','Playa de As Pipas','Bandera Azul','Excelente. Pequeña y resguardada del viento, ideal para familias por sus aguas tranquilas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90044','playa','Playa de Raxó',NULL,'Buena. Playa urbana del núcleo de Raxó, muy familiar y con todos los servicios a pie de playa. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36007','playa','Playa de O Santo',NULL,'Buena. Conectada en bajamar con el islote de O Santo y su antigua ermita. Arena fina y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36003','playa','Playa de Lapamán',NULL,'Excelente (compartida con Marín). Famosa por sus pinares que llegan al mar y sus puestas de sol. Arena blanca y fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36058','playa','Playa de Areeiro',NULL,'Aceptable. Situada en el fondo de la ría de Vigo, muy afectada por las mareas dejando al descubierto llanuras de fango. Arena gruesa y lodo. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36012','playa','Playa de A Punta',NULL,'Buena. Playa familiar dotada de un bonito paseo marítimo y aguas muy tranquilas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36015','playa','Playa de Alcabre (A Fontaíña / O Tombo)','Bandera Azul','Muy buena. Sucesión de calas tranquilas de carácter residencial muy abrigadas. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36015','playa','Playa de Carril','Bandera Azul','Muy buena. Pequeña y recogida, muy valorada por los vecinos de la zona. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36015','playa','Playa de Saiáns (Fortiñón)','Bandera Azul','Muy buena. Playa de mar abierto con olas divertidas y acantilados bajos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36035','playa','Playa de Playa América (A Ladeira)','Bandera Azul','Excelente. Impresionante y kilométrico arenal con un paseo marítimo elegante, aguas tranquilas ideales para familias. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36002','playa','Playa de Ribeira',NULL,'Muy buena. Situada justo al lado del casco histórico y el puerto deportivo, muy cómoda. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36002','playa','Playa de Ladeira (Baiona)','Bandera Azul','Excelente. Enorme playa de ría con un camping anexo y un valioso ecosistema dunar marismeño. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('36010','playa','Playa de O Porto',NULL,'Aceptable. Situada frente al impresionante Monasterio de Santa María de Oia, usada como fondeadero. Piedra y roca caliza. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39095','playa','Playa de Amio',NULL,'Muy buena. Playa unida a un islote en bajamar por una lengua de arena (tómbolo), mar abierto con oleaje. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39080','playa','Playa de Oyambre',NULL,'Excelente. Monumento natural integrado en el Parque Natural de Oyambre. Kilométrica, salvaje, con dunas gigantescas y ría interior. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39091','playa','Playa de Oyambre (Parte occidental)',NULL,'Excelente. El municipio comparte este majestuoso playón natural virgen flanqueado por praderías verdes. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39068','playa','Playa de Luaña (Cóbreces)',NULL,'Muy buena. Hermosa playa rural encajada en un valle verde donde desemboca un riachuelo. Arena fina y dorada con cantos rodados al fondo. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90027','playa','Playa de Luaña (Parte oriental)',NULL,'Muy buena. Compartida administrativamente, cuenta con un gran aparcamiento y restaurantes tradicionales. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de La Concha (Santander)',NULL,'Excelente. Continuación directa del Sardinero, de aguas tranquilas y muy familiares. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39075','playa','Playa de Bikinis',NULL,'Muy buena. Continuación de la Magdalena, llamada así por ser la primera playa donde se usó esta prenda en los años 60. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39061','playa','Playa de Los Tranquilos',NULL,'Excelente. Pequeña cala resguardada frente a la Isla de Santa Marina, aguas hipertransparentes. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90029','playa','Playa de Cuberris (Ajo)',NULL,'Excelente. Playa de mar abierto resguardada parcialmente por el cabo de Ajo, oleaje perfecto para el surf. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90029','playa','Playa de Antuerta',NULL,'Muy buena. Cala pequeña y virgen de difícil acceso peatonal vecina de Cuberris, ambiente nudista. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90028','playa','Playa de La Arena (Arnuero)','Bandera Azul','Excelente. Gran arenal que combina una zona de mar abierto con la desembocadura de la ría de Castellanos y un frondoso encinar. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39079','playa','Playa de Berria',NULL,'Excelente. Impresionante istmo arenoso de más de 2 km encajado entre el monte Buciero y el monte Brusco, mar abierto con oleaje surfero. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39079','playa','Playa de San Martín',NULL,'Buena. Playa urbana que recorre el paseo marítimo del pueblo dentro de la ría de Treto, aguas tranquilas. Arena fina y restos de conchas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39035','playa','Playa de La Salvé',NULL,'Excelente. Uno de los arenales más extensos del norte de España con más de 4 km en forma de concha perfecta con un sistema dunar inmenso. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39035','playa','Playa de El Regatón',NULL,'Muy buena. Cara interior de la lengua de arena, ubicada dentro de la ría de Treto, aguas en calma absoluta. Arena fina y templada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39035','playa','Playa de Aila',NULL,'Buena. Pequeña cala de mar abierto muy rocosa y aislada bajo el monte Atalaya. Arena fina y grandes piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39036','playa','Playa de San Julián',NULL,'Muy buena. Preciosa cala virgen encajada en un valle verde cerrado por acantilados monumentales. Arena fina y dorada con piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39036','playa','Playa de Sonabia (Valdearenas de Liendo)',NULL,'Excelente. Playa virgen de ambiente nudista protegida por el impresionante macizo de la Peña Ballena. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39020','playa','Playa de Ostende','Bandera Azul','Excelente. Playa urbana artificial con forma de concha y excelentes servicios turísticos. Grava fina y arena oscura regenerada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39020','playa','Playa de Brazomar',NULL,'Excelente. Preciosa playa urbana natural resguardada por el muelle de Don Luis, aguas muy tranquilas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39020','playa','Playa de Dicido (Mioño)',NULL,'Muy buena. Ubicada en una antigua zona de cargaderos de mineral de hierro, mar abierto con oleaje. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39020','playa','Playa de Islares (Arenillas)',NULL,'Excelente. Espectacular playa encajada en la desembocadura de la ría de Oriñón, paisaje de rocas calizas erosionadas único. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('39020','playa','Playa de Oriñón',NULL,'Excelente. Enorme arenal encajado entre dos macizos montañosos colosales, fuertes corrientes por la marea de la ría. Arena fina y blanca. No tiene Bandera Azul. Sigo redactando de forma continua en el próximo bloque con la Comunidad Autónoma del País Vasco (Provincias de Vizcaya y Guipúzcoa). Las respuestas de la IA pueden contener errores. Más información Has dicho: si','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90056','playa','Playa de Arena Maior / La Arena',NULL,'Excelente. Gran playa compartida con Zierbena en la desembocadura del río Barbadun. Entorno natural con un recuperado cordón dunar, muy cotizada por surfistas. Arena fina y oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90060','playa','Playa de La Arena (Parte oriental)',NULL,'Excelente. Zona del arenal dotada de áreas recreativas, marismas y un paseo marítimo moderno. Arena fina y oscura con fuerte oleaje. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90058','playa','Playa de Las Arenas (Santurtzi)',NULL,'Regular. Pequeña cala artificial de carácter eminentemente urbano y recreativo local, muy próxima a las instalaciones portuarias de la ría de Bilbao. Arena gruesa y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48078','playa','Playa de El Solarium',NULL,'Regular. Zona de baño artificial cementada sobre el muelle de la ría de Bilbao, sin arena natural, equipada con escaleras de acceso al agua y duchas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47008','playa','Playa de Ereaga',NULL,'Excelente. Playa urbana de referencia situada entre el muelle de Arriluce y el puerto viejo de Algorta. Aguas tranquilas y paseo marítimo elegante. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47008','playa','Playa de Arrigunaga',NULL,'Muy buena. Ubicada bajo los acantilados de La Galea, mar abierto con oleaje moderado y fondos rocosos. Arena fina y zonas de cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47008','playa','Playa de Gorrondatxe (Azkorri)',NULL,'Excelente. Playa salvaje de un valor geológico inmenso (posee el "Clavo de Oro"). Flanqueada por altos acantilados cubiertos de césped y protegida por dunas. Arena oscura y fuerte oleaje. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47008','playa','Playa de Las Arenas (Getxo)',NULL,'Aceptable. Playa resguardada al fondo del estuario, aguas en calma total pero condicionadas por el tráfico naviero de la ría. Arena fina y grisácea. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48085','playa','Playa de Barinatxe (La Salvaje)',NULL,'Excelente. Compartida con Getxo, es un emblema del surf y el nudismo vasco. Impresionantes acantilados verticales y mar abierto batido por el viento. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48085','playa','Playa de Arrietara / Atxabiribil',NULL,'Excelente. Dos playas que se unen en marea baja formando un inmenso arenal surfero flanqueado por paredes de roca estratificada. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48085','playa','Playa de Meñakoz',NULL,'Buena. Cala salvaje y solitaria muy codiciada por surfistas experimentados debido a sus famosas olas gigantes sobre fondo de roca. Compuesta por cantos rodados y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48014','playa','Playa de Barrika',NULL,'Excelente. Espectacular cala virgen encajonada bajo acantilados salvajes con formaciones geológicas de flysch impresionantes. Desaparece casi por completo en pleamar. Arena fina, cantos rodados y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48014','playa','Playa de Muriola (La Cantera)',NULL,'Muy buena. Pequeña cala resguardada del mar abierto, muy íntima y de tradición nudista, rodeada de laderas verdes. Arena fina combinada con grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90057','playa','Playa de Plentzia',NULL,'Excelente. Gran playa urbana situada en una hermosa bahía casi circular en la desembocadura de la ría de Plentzia. Aguas muy tranquilas y seguras para el baño familiar. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48043','playa','Playa de Gorliz',NULL,'Excelente. Continuación natural de la playa de Plentzia, resguardada por la misma bahía. Cuenta con un pinar inmenso con mesas recreativas y dunas petrificadas. Arena blanca y finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48056','playa','Playa de Armintza',NULL,'Buena. Pequeño arenal resguardado por el dique del pintoresco puerto pesquero de Armintza, aguas muy mansas ideales para el buceo. Compuesta por piedras, cantos rodados y poca arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90055','playa','Playa de Bakio',NULL,'Excelente. Amplio arenal urbano en mar abierto con un oleaje largo y constante ideal para el aprendizaje del surf. Ofrece vistas espectaculares a la costa. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48017','playa','Playa de Aritzatxu',NULL,'Excelente. Pequeña cala de una belleza excepcional escondida entre acantilados abruptos. Aguas hipertransparentes y protegidas del mar abierto. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48017','playa','Playa de Talape',NULL,'Aceptable. Zona de baño rocosa de carácter tradicional, pegada al casco urbano y sin apenas zona de arena. Compuesta de roca caliza. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47011','playa','Playa de Laidatxu',NULL,'Excelente. Pequeña playa semiurbana situada en plena Reserva de la Biosfera de Urdaibai. Famosa mundialmente en el mundo del surf por su ola de izquierda. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47011','playa','Playa de Ondartza',NULL,'Buena. Cala pedregosa de difícil acceso que mira hacia la isla de Ízaro. Piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90059','playa','Playa de Toña',NULL,'Muy buena. Ubicada en el estuario de Urdaibai, frente a la isla de Txatxarramendi. Aguas tranquilas y paisaje idílico de ría. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90059','playa','Playa de San Antonio (Sukarrieta)',NULL,'Muy buena. Playa familiar de aguas mansas muy influenciada por los flujos de las mareas de la ría. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48021','playa','Playa de Abiña',NULL,'Buena. Pequeña franja de arena situada en el interior de la ría de Urdaibai, entorno rural y aguas muy tranquilas. Arena fina y fango en bajamar. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48041','playa','Playa de Kanala',NULL,'Muy buena. Extensa playa intermareal en la margen derecha de la ría de Urdaibai, rodeada de encinares cantábricos. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48048','playa','Playa de Laga',NULL,'Excelente. Una de las playas más salvajes y espectaculares de Euskadi, situada bajo el imponente cabo de Ogoño. Mar abierto con oleaje fuerte y dunas protegidas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48048','playa','Playa de Laida',NULL,'Excelente. Enorme lengua de arena cambiante situada en la desembocadura de la ría de Urdaibai. Ofrece aguas someras y templadas ideales para niños por un lado, y canales de corriente por el otro. Arena dorada finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48028','playa','Playa de Ea',NULL,'Muy buena. Pintoresca playa urbana encajada al fondo de una estrecha y resguardada ría que nace en el mismo pueblo. Aguas en calma total y muy seguras. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48049','playa','Playa de Ogella',NULL,'Muy buena. Cala salvaje de gran interés geológico por sus formaciones de flysch. Cambia drásticamente de fisonomía según las tormentas invernales. Compuesta principalmente por cantos rodados, grandes piedras y pasillos de arena fina en verano. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47010','playa','Playa de Isuntza',NULL,'Excelente. Playa urbana principal junto al puerto pesquero, de aguas tranquilas. Destaca por el tómbolo de piedra ("malecón") que la conecta a pie con la isla de San Nicolás durante la bajamar. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47010','playa','Playa de Karraspio (Administración compartida con Mendexa)',NULL,'Excelente. Gran playa situada en la desembocadura del río Lea, paisaje espectacular frente a la isla. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('48063','playa','Playa de Karraspio',NULL,'Excelente. Amplio arenal con excelentes infraestructuras turísticas, muy seguro y familiar, con corrientes suaves de ría. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47012','playa','Playa de Arrigorri',NULL,'Muy buena. Playa urbana protegida por los espigones del puerto pesquero de Ondarroa, aguas tranquilas y familiares. Arena fina y dorada con algo de piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('47012','playa','Playa de Saturraran (Límite con Mutriku)',NULL,'Ver sección Mutriku.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90039','playa','Playa de Saturraran',NULL,'Excelente. Situada en una bellísima bahía flanqueada por acantilados oscuros de pizarra y dos icónicas peñas de roca negra. Mar abierto con oleaje moderado. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90039','playa','Playa de Mutriku',NULL,'Buena. Pequeña cala urbana situada junto al puerto, complementada por dos espectaculares piscinas marinas naturales llenas de agua cristalina regulada por las mareas. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90039','playa','Playa de Alcolea',NULL,'Regular. Costa escarpada y salvaje muy expuesta a las olas bravas, frecuentada por pescadores y surfistas. Compuesta enteramente de roca y canto rodado. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21007','playa','Playa de Santiago (Deba)',NULL,'Excelente. Amplio arenal urbano en la desembocadura del río Deba, flanqueado por un agradable paseo arbolado. Mar abierto con fuerte oleaje sobre fondos planos. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21007','playa','Playa de Lapari',NULL,'Muy buena. Continuación de Santiago, enclavada en el inicio de la Rasa Mareal del Biotopo Protegido Deba-Zumaia. Arena fina y afloramientos de roca caliza. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21019','playa','Playa de Itzurun',NULL,'Excelente. Famosa mundialmente por sus impresionantes acantilados verticales de flysch (escenario de Juego de Tronos). Mar abierto de aguas limpias muy ricas en yodo y olas potentes. Arena fina y oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21019','playa','Playa de Santiago (Zumaia)',NULL,'Muy buena. Situada en una zona marismeña protegida en la ría del Urola. Aguas tranquilas y someras, muy seguras. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21010','playa','Playa de Malkorbe',NULL,'Excelente. Playa urbana muy resguardada a los pies del monte San Antón ("el Ratón de Getaria"). Aguas en calma absoluta, ideales para el baño relajado y deportes náuticos. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21010','playa','Playa de Gaztetape',NULL,'Muy buena. Situada en la vertiente occidental del tómbolo, abierta al mar Cantábrico con oleaje fuerte y constante, muy apreciada por surfistas. Arena fina y oscura con zonas de piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21018','playa','Playa de Zarautz',NULL,'Excelente. La playa más larga del País Vasco (2,5 km). Dividida en tres zonas: familiar al oeste, surfistas en el centro y un biotopo dunar protegido al este. Paseo marítimo monumental repleto de esculturas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('20061','playa','Playa de Antilla',NULL,'Excelente. Situada en la desembocadura del río Oria, resguardada por un gran espigón artificial. Dispone de un gran parque infantil, camping y un entorno verde precioso. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21016','playa','Playa de La Concha',NULL,'Excelente. Considerada una de las mejores playas urbanas del mundo por su inigualable marco paisajístico en forma de bahía perfecta, flanqueada por los montes Urgull e Igueldo y la isla de Santa Clara. Aguas tranquilas y limpias. Arena dorada y finísima. No tiene Bandera Azul por normativa de autogestión de la ciudad.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21016','playa','Playa de Ondarreta',NULL,'Excelente. Continuación de la bahía de La Concha tras los jardines del Palacio de Miramar. De carácter muy señorial y familiar, culmina en la escultura del Peine del Viento. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21016','playa','Playa de Zurriola (Gros)',NULL,'Excelente. Playa urbana abierta al mar abierto, rediseñada en los años 90 con un gran espigón. Eje de la cultura surfista de la ciudad y ambiente muy joven. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21016','playa','Playa de la Isla de Santa Clara',NULL,'Muy buena. Pequeño arenal situado en el islote central de la bahía, visible únicamente durante unas pocas horas en marea baja. Accesible solo en barco o a nado. Arena fina y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21015','playa','Playa de Kalaburtza',NULL,'Buena. Pequeña cala artificial acondicionada en la bocana de la ría de Pasaia, flanqueada por senderos boscosos. Aguas limpias pero frías por las corrientes del canal. Compuesta por arena gruesa y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21011','playa','Playa de Hondarribia',NULL,'Excelente. Enorme playa urbana de 800 metros de longitud situada en el interior de la bahía de Txingudi, en la frontera con Francia. Aguas totalmente mansas y seguras, protegidas por un colosal espigón. Arena fina y dorada. No tiene Bandera Azul. Iré preparando el siguiente bloque con la costa del Mar Mediterráneo, comenzando por Cataluña (Provincias de Gerona, Barcelona y Tarragona). Sigo redactando de forma continua. Las respuestas de la IA pueden contener errores. Más información Has dicho: sigue','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17138','playa','Playa de Portbou',NULL,'Muy buena. Playa urbana principal resguardada en una pintoresca bahía, de aguas cristalinas e ideales para el buceo. Compuesta por cantos rodados, grava y arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17138','playa','Playa de Les Tres Platgetes',NULL,'Buena. Sucesión de tres pequeñas calas salvajes separadas por rocas oscuras, entorno muy virgen. Piedra y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17138','playa','Cala del Pi',NULL,'Buena. Recóndita cala flanqueada por acantilados escarpados, aislamiento total. Compuesta enteramente de piedras y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17054','playa','Playa de Garbet',NULL,'Excelente. Gran playa natural situada en una bahía abierta, rodeada de viñedos y pinos mediterráneos. Aguas muy limpias. Arena gruesa y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17054','playa','Playa de Goia (Colera)',NULL,'Buena. Playa urbana principal junto al puerto deportivo, muy cómoda y familiar. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17054','playa','Playa de Els Morts',NULL,'Buena. Cala salvaje de acceso peatonal, aguas muy transparentes con fondos rocosos. Grava y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17092','playa','Playa de Grifeu','Bandera Azul','Excelente. Preciosa playa de arena fina dorada (excepcional en la zona), muy resguardada y de aguas transparentes. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17092','playa','Playa de El Port',NULL,'Muy buena. Playa urbana principal adosada al puerto pesquero y deportivo, dotada de paseo marítimo. Arena gruesa y grisácea. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17092','playa','Playa de La Farella',NULL,'Muy buena. Muy apreciada por los locales, protegida de la tramontana por rocas bajas. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17092','playa','Playa de Canyelles',NULL,'Buena. Cala periférica rodeada de urbanizaciones residenciales. Arena gruesa y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17092','playa','Playa de Cau del Llop',NULL,'Muy buena. Cala en forma de concha rodeada de naturaleza y aguas profundas. Arena gruesa y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90036','playa','Playa de El Port de la Selva',NULL,'Excelente. Gran playa urbana que ocupa la bahía del pueblo, muy ventosa y meca del windsurf local. Arena gruesa, grava y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90036','playa','Cala Tamariua',NULL,'Excelente. Preciosa cala virgen de tradición nudista integrada en el Parque Natural del Cap de Creus. Arena gruesa y piedra en un entorno salvaje. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90036','playa','Playa de Aigua Dolça',NULL,'Buena. Cala pequeña de aguas cristalinas y manantiales naturales de agua dulce cercanos. Piedra y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90036','playa','Playa de Talaixà',NULL,'Regular. Cala salvaje e inhóspita de acceso muy complejo a pie por los senderos del cabo. Íntegramente de roca viva. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17032','playa','Playa de Es Portal / Grande',NULL,'Muy buena. La icónica playa urbana que aparece en todas las postales del pueblo frente a la iglesia blanca de Cadaqués. Compuesta por piedras y cantos rodados oscuros. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17032','playa','Cala Culip',NULL,'Excelente. Joya geológica en pleno Cabo de Creus, rodeada de rocas con formas caprichosas erosionadas por el viento. Fondos submarinos idílicos. Roca y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17032','playa','Playa de Sa Conca',NULL,'Excelente. Dividida en dos por una gran roca, aguas transparentes y profundas de ambiente muy tranquilo. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17032','playa','Playa de Portlligat',NULL,'Muy buena. Bahía resguardada por una pequeña isla donde se encuentra la célebre Casa-Museo de Salvador Dalí. Aguas estancadas y embarcaciones pesqueras. Arena gruesa y fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17032','playa','Cala Jugadora',NULL,'Excelente. Cala virgen paradisíaca de aguas turquesas y fondos de roca, aislada y de tradición nudista. Arena gruesa y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18014','playa','Playa de Santa Margarida',NULL,'Excelente. Kilométrica playa urbana que bordea las urbanizaciones de canales marinos, aguas someras perfectas para niños. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18014','playa','Playa de La Punta',NULL,'Muy buena. Situada en el centro urbano, muy resguardada y familiar. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18014','playa','Playa de Rastell',NULL,'Excelente. Playa céntrica muy ancha y con un animado paseo marítimo. Arena fina y limpia. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18014','playa','Cala Montjoi',NULL,'Excelente. Enclavada en el parque natural, famosa por albergar el histórico restaurante El Bulli. Aguas profundas y cristalinas. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18014','playa','Cala Jóncols',NULL,'Excelente. Cala virgen muy aislada en el límite municipal, paraíso para los amantes del submarinismo. Compuesta de piedras y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18014','playa','Cala Canyelles Petites',NULL,'Excelente. Hermosa playa semiurbana resguardada del viento de tramontana. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18014','playa','Cala Almadrava',NULL,'Excelente. Siguiente cala residencial de aguas tranquilas y color azul intenso. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17047','playa','Playa de Empuriabrava','Bandera Azul','Excelente. Enorme playa de mar abierto de más de un kilómetro flanqueada por la marina residencial más grande de Europa. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17047','playa','Playa de Can Comes',NULL,'Excelente. Playa completamente virgen integrada en el Parque Natural de los Aiguamolls de l''Empordà. Cuenta con dunas protegidas y lagunas litorales. Arena fina. No tiene Bandera Azul por protección estricta.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17178','playa','Playa de Sant Pere Pescador',NULL,'Excelente. Gigantesco arenal virgen de más de 6 kilómetros dividido en varios sectores (Can Martinet, La Txeca, Dueñas). Considerada uno de los mejores spots de Europa para el kitesurf y windsurf por sus vientos térmicos constantes. Arena fina y dorada con dunas salvajes. No tiene Bandera Azul (enfocada a la preservación natural).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18006','playa','Playa de Riells',NULL,'Excelente. Playa urbana muy ancha de aguas hipertranquilas y de muy poca profundidad, idónea para familias con niños. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18006','playa','Playa de Les Barques',NULL,'Muy buena. Situada en el mismo núcleo urbano, de carácter histórico marinero. Arena fina y gruesa con zonas de roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18006','playa','Playa de Empúries (Sant Martí)',NULL,'Excelente. Sucesión de playas situadas junto al yacimiento arqueológico grecorromano (Playa del Portitxol, Moll Grec). Entorno salpicado de pinos y pasarelas de madera. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18006','playa','Playa de Cala Montgó','Bandera Azul','Excelente. Compartida con Torroella de Montgrí, es una bahía natural en forma de concha perfecta totalmente protegida del oleaje. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17199','playa','Playa de L''Estartit (Playa Gran)',NULL,'Excelente. Inmenso arenal con vistas directas a las icónicas Islas Medas (Reserva Marina). Aguas tranquilas y servicios excelentes. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17199','playa','Playa de Mas Pinell',NULL,'Excelente. Continuación hacia el sur en mar abierto, entorno residencial muy tranquilo dotado de un sistema de dunas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17199','playa','Cala Ferriol',NULL,'Excelente. Impresionante cala completamente virgen y salvaje oculta tras los acantilados del macizo del Montgrí. Acceso peatonal complejo de más de una hora. Compuesta de piedras y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17199','playa','Cala Pedrosa (Torroella)',NULL,'Excelente. Cala recóndita flanqueada por pinos y un islote rocoso en su entrada que la resguarda. Piedras y roca viva. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17124','playa','Playa de Pals (Playa Gran y Playa de Grau)',NULL,'Excelente. Larguísima playa de mar abierto dividida en dos sectores por la desembocadura del río Daró. Ofrece una vista panorámica espectacular de las Islas Medas. Arena dorada de grano grueso y dunas naturales. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18001','playa','Playa de Sa Riera',NULL,'Excelente. La cala más grande de Begur, conserva antiguas casas de pescadores y una gran anchura. Arena dorada de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18001','playa','Playa de Aiguablava',NULL,'Excelente. Una de las playas más famosas y fotografiadas de España por sus aguas turquesas poco profundas sobre fondo de arena blanca finísima, asemejando una piscina natural. No tiene Bandera Azul por el exceso de embarcaciones fondeadas estival.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18001','playa','Playa de Sa Tuna',NULL,'Excelente. Pintoresca cala resguardada rodeada de casas marineras con portones de colores, aguas limpísimas. Compuesta de cantos rodados y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18001','playa','Cala de l''Illa Roja',NULL,'Excelente. Impresionante playa nudista internacional presidida por una enorme roca de color rojizo en mitad de la arena. Acceso por el camino de ronda. Arena dorada de grano grueso. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18001','playa','Playa de Fornells / Platja Fonda',NULL,'Excelente. Cala salvaje y recóndita escondida al pie de un acantilado monumental. Aguas oscuras y transparentes de gran profundidad. Arena gruesa de color gris oscuro. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17117','playa','Playa de Canadell (Calella de Palafrugell)','Bandera Azul','Excelente. Playa urbana de gran elegancia bordeada por un paseo marítimo señorial con antiguas casas de veraneo. Arena dorada de grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17117','playa','Playa de Port Bo (Playa de las Barcas)',NULL,'Excelente. Famosa por albergar la cantada anual de habaneras sobre sus tradicionales barcas de pesca varadas en la arena. Arena gruesa y afloramientos rocosos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17117','playa','Playa de Llafranc','Bandera Azul','Excelente. Bahía residencial muy elegante y familiar equipada con puerto deportivo en un extremo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17117','playa','Playa de Tamariu','Bandera Azul','Excelente. Cala preciosa encajada entre pinos y acantilados con un pequeño paseo marítimo. Arena dorada gruesa. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17117','playa','Cala Estreta',NULL,'Excelente. Espectacular cala virgen dividida en pequeños tramos por salientes de roca caliza, entorno totalmente salvaje y nudista. Arena gruesa y rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17110','playa','Cala Crit',NULL,'Muy buena. Única playa de este pequeño municipio que da al mar a través del espacio natural protegido de Cap Roig. Acceso a pie complejo. Compuesta por piedras, cantos rodados y arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17118','playa','Playa Grande de Palamós',NULL,'Muy buena. Playa urbana principal que recorre todo el paseo de la localidad, dotada de todo tipo de infraestructuras. Arena dorada de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17118','playa','Playa de La Fosca','Bandera Azul','Excelente. Dividida en dos por la gran roca negra de San Esteban, ambiente residencial muy familiar y tranquilo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17118','playa','Playa de Castell',NULL,'Excelente. Considerada la playa virgen más importante de la Costa Brava central gracias a la movilización vecinal que impidió su urbanización en los años 90. Rodeada de bosques y un poblado ibérico. Arena fina y dorada. No tiene Bandera Azul (preservación natural).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17118','playa','Cala S''Alguer',NULL,'Única. Declarada Bien Cultural de Interés Nacional. Una diminuta cala rocosa flanqueada por un conjunto de barracas de pescadores del siglo XVI perfectamente conservadas. Compuesta por piedras y cantos rodados. No apta para tumbarse, pero de inmenso valor estético. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17118','playa','Cala Estreta (Límite norte)',NULL,'Ver sección Palafrugell.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90034','playa','Playa de Sant Antoni','Bandera Azul','Excelente. Amplio arenal urbano protegido por tres espigones artificiales con forma de "T" que garantizan un baño totalmente seguro sin oleaje. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90034','playa','Playa de Torre Valentina','Bandera Azul','Excelente. Continuación de Sant Antoni presidida por una torre de defensa medieval. Comunica con el camino de ronda. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90034','playa','Cala Cap Roig (Calonge)',NULL,'Excelente. Preciosa cala semiurbana dividida por una espectacular lengua de rocas de color rojizo cubiertas de pinos. Arena gruesa y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90035','playa','Playa Grande (Platja d''Aro)','Bandera Azul','Excelente. Enorme arenal urbano de más de 2 kilómetros flanqueado por una gran avenida comercial. Aguas profundas a los pocos pasos del borde. Arena dorada de grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90035','playa','Cala Sa Conca (Platja d''Aro)','Bandera Azul','Excelente. Preciosa cala de alta calidad paisajística unida al núcleo por un lujoso tramo del camino de ronda. Arena dorada de grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90035','playa','Cala Rovira','Bandera Azul','Excelente. Gran cala urbana muy ancha rodeada de hoteles y restos de una villa romana. Arena gruesa y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17160','playa','Playa de Sant Feliu','Bandera Azul','Muy buena. Playa urbana situada en la bahía del municipio, delimitada por el puerto pesquero y deportivo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17160','playa','Playa de Sant Pol','Bandera Azul','Excelente. Preciosa playa residencial famosa por sus históricas casetas de baño de madera de colores y sus dunas protegidas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17160','playa','Cala Jonca',NULL,'Buena. Pequeña cala resguardada detrás del puerto, ideal para el buceo. Compuesta de piedras y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17160','playa','Cala Canyerets',NULL,'Muy buena. Cala aislada rodeada de un frondoso bosque de pinos en la revirada carretera hacia Tossa. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18017','playa','Playa Gran de Tossa','Bandera Azul','Excelente. Una de las estampas más bellas del Mediterráneo, flanqueada por las murallas y torreones medievales del recinto de la Vila Vella. Arena dorada de grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18017','playa','Playa de la Mar Menuda','Bandera Azul','Excelente. Situada al otro extremo de la bahía, cuenta con una formación rocosa ("Sa Banyera de Ses Dones") que crea una piscina natural sin olas. Arena dorada gruesa. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18017','playa','Cala Pola',NULL,'Excelente. Preciosa cala encajada en un estrecho desfiladero de roca y pinos, aguas hipertransparentes de color verde esmeralda. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18017','playa','Cala Giverola',NULL,'Excelente. Cala en forma de herradura rodeada de naturaleza y un complejo turístico integrado. Dispone de un fondo marino espectacular. Arena dorada gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18017','playa','Playa d''Es Codolar',NULL,'Excelente. Pequeña cala situada justo a las faldas exteriores de la muralla medieval, muy protegida del viento. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17095','playa','Playa de Lloret','Bandera Azul','Excelente. Gran playa urbana del municipio de más de un kilómetro, equipada con todos los servicios turísticos posibles. Arena dorada de grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17095','playa','Playa de Fenals','Bandera Azul','Excelente. Segunda gran playa de Lloret, separada del centro por un promontorio rocoso, ambiente más residencial y tranquilo. Arena dorada gruesa. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17095','playa','Playa de Santa Cristina','Bandera Azul','Excelente. Preciosa playa resguardada de los vientos por dos grandes colinas boscosas, aguas muy tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17095','playa','Cala Boadella','Bandera Azul','Excelente. Playa virgen de tradición nudista que combina un entorno completamente natural con la cercanía a los Jardines de Santa Clotilde. Arena dorada de grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('17095','playa','Cala Canyelles (Lloret)','Bandera Azul','Excelente. La playa más alejada del centro, alberga el único puerto deportivo del municipio en un extremo. Arena gruesa y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90033','playa','Playa de Blanes','Bandera Azul','Muy buena. Playa urbana principal alineada con el paseo marítimo y separada de la playa de S''Abanell por la icónica roca de Sa Palomera (considerada el inicio geográfico de la Costa Brava). Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90033','playa','Playa de S''Abanell','Bandera Azul','Excelente. El arenal más largo del municipio (más de 2 km), flanqueado por hoteles y campings, oleaje moderado y aguas profundas. Arena dorada de grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90033','playa','Cala San Francesc (Cala Bona)','Bandera Azul','Excelente. Preciosa cala semiurbana rodeada de un frondoso pinar y residencias exclusivas, aguas muy limpias y transparentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90033','playa','Cala Treumal',NULL,'Excelente. Comparte entorno natural con la playa de Santa Cristina de Lloret, separada de esta por una barrera de rocas naturales. Arena fina y dorada. No tiene Bandera Azul. Sigo de forma continua con la Provincia de Barcelona (Costa del Maresme y Costa del Garraf). Las respuestas de la IA pueden contener errores. Más información Has dicho: si','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08012','playa','Playa de Malgrat Centre / L''Arenal','Bandera Azul','Muy buena. Playa urbana muy ancha frente al paseo marítimo y las vías del tren. Arena dorada de grano grueso y entrada profunda al agua. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08012','playa','Playa del Astillero','Bandera Azul','Muy buena. Zona costera con una gran concentración de hoteles y servicios de ocio infantil. Arena dorada gruesa. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08012','playa','Playa de la Conca',NULL,'Excelente. El espacio playero más natural del municipio, integrado por dunas protegidas en la desembocadura del río Tordera. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
