INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08261','playa','Playa de las Caletes',NULL,'Buena. Sucesión de pequeñas calas separadas por pequeños muros de roca artificiales. Arena gruesa y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
