INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08016','playa','Playa de Pescadors','Bandera Azul','Excelente. Muy amplia y con servicios excelentes para personas con movilidad reducida. Arena dorada gruesa. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
