INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08126','playa','Playa de las Barques (Montgat)',NULL,'Muy buena. Conserva el encanto de los barrios marineros y una antigua lonja de pescado. Arena dorada de grano grueso. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08126','playa','Playa de Can Tano',NULL,'Buena. Arena gruesa y presencia de zonas de roca ideales para la pesca con caña. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08126','playa','Playa de los Tussilas',NULL,'Regular. Muy afectada por la erosión costera estacional. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90024','playa','Playa del Coco',NULL,'Muy buena. Playa urbana muy céntrica dotada de un paseo marítimo moderno que conecta con el puerto. Arena dorada de grano grueso. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90024','playa','Playa de los Pescadores',NULL,'Muy buena. Ubicada frente al centro histórico, reconocible por las barcas tradicionales expuestas. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90024','playa','Playa del Cristall',NULL,'Muy buena. Recibe este nombre por una antigua fábrica de vidrio colindante. Arena dorada de grano grueso. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90024','playa','Playa de la Estación',NULL,'Buena. Situada justo al lado de la estación de ferrocarril, muy concurrida. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90024','playa','Playa del Pont del Petroli',NULL,'Excelente. Famosa por el icónico pantalán que se adentra 250 metros en el mar (reconstruido tras temporales). Arena gruesa. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08194','playa','Playa del Fòrum',NULL,'Aceptable. Situada junto a la desembocadura del río Besòs y la central térmica (las tres chimeneas). Entorno muy transformado artificialmente. Arena dorada gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08194','playa','Playa de la Litoral',NULL,'Regular. Playa urbana industrial recuperada tras intensos procesos de descontaminación de suelos. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08003','playa','Playa de la Barceloneta',NULL,'Muy buena. La playa más famosa y masificada de la ciudad, con un ambiente internacional asombroso y todo tipo de servicios, pero penalizada por la masificación. Arena dorada de grano grueso (regenerada). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08003','playa','Playa de San Sebastián',NULL,'Muy buena. Situada en el extremo sur de la fachada costera, bajo el icónico Hotel W (Vela). Cuenta con zonas nudistas tradicionales. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08003','playa','Playa de Bogatell','Bandera Azul','Excelente. Diseñada con motivo de los JJOO de 1992, es más tranquila y espaciosa que la Barceloneta. Arena dorada gruesa. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08003','playa','Playa de la Mar Bella','Bandera Azul','Excelente. Dispone de un área nudista consolidada y un centro de deportes náuticos base. Arena dorada de grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08003','playa','Playa de la Nova Mar Bella',NULL,'Muy buena. Ambiente muy residencial, tranquilo y frecuentado por público local de los barrios nuevos. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08003','playa','Playa de Somorrostro',NULL,'Muy buena. Tramo de playa recuperado históricamente situado entre el Hospital del Mar y el Puerto Olímpico. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08003','playa','Playa de Llevant (Barcelona)',NULL,'Buena. La playa más septentrional de la ciudad, cuenta con una de las pocas zonas delimitadas oficialmente para el acceso con perros. Arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08003','playa','Zona de Baños del Fòrum',NULL,'Única. Piscina de agua marina controlada sin arena, suelo pavimentado y rampas directas al agua. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08169','playa','Playa de El Prat (Remolar)',NULL,'Excelente. Playa completamente virgen de gran valor ecológico, flanqueada por las lagunas del delta del Llobregat y dunas naturales. Avistamiento constante de aviones por su cercanía al aeropuerto. Arena dorada fina. No tiene Bandera Azul (protección medioambiental).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08301','playa','Playa de la Murtra',NULL,'Muy buena. Entorno seminatural protegido que carece de paseo marítimo urbanizado. Arena dorada de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08301','playa','Playa de la Pineda (Viladecans)',NULL,'Buena. Playa virgen contigua a pinares litorales protegidos. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08089','playa','Playa de Gavà Mar',NULL,'Excelente. Magnífico diseño urbano sostenible donde las casas y el paseo marítimo peatonal de madera se integran perfectamente dentro de un denso bosque de pinos y dunas. Arena dorada de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08056','playa','Playa de la Pineda (Castelldefels)','Bandera Azul','Excelente. Enorme anchura (más de 100 metros de arena hasta el agua), ideal para la práctica del windsurf y kitesurf. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08056','playa','Playa de Lluminetes','Bandera Azul','Excelente. Zona central de la costa del municipio repleta de restaurantes históricos y chiringuitos tradicionales de playa. Arena fina dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08056','playa','Playa del Baixador','Bandera Azul','Excelente. La zona más cercana al parque natural del Garraf, muy espaciosa y limpia. Arena fina y dorada. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08023','playa','Playa de San Sebastián (Sitges)','Bandera Azul','Excelente. Preciosa playa urbana situada en el casco antiguo, con un paseo marítimo idílico muy aclamado internacionalmente. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08023','playa','Playa de la Ribera','Bandera Azul','Excelente. Muy céntrica y concurrida, situada justo enfrente de los principales ejes comerciales del pueblo. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08023','playa','Playa de la Fragata',NULL,'Muy buena. Situada justo al pie de la fotogénica iglesia de San Bartolomé, no dispone de hamacas ya que está dedicada a actividades náuticas y deportivas. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08023','playa','Playa de Aiguadolç','Bandera Azul','Excelente. Pequeña y resguardada cala situada detrás del puerto deportivo, ambiente muy familiar y tranquilo con zona nudista. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08023','playa','Playa de Garraf',NULL,'Excelente. Preciosa y única cala marinera flanqueada por las famosas casitas de madera de pescadores pintadas de blanco y verde (declaradas bien de interés). Arena fina mezclada con piedras calizas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08023','playa','Playa de Terramar','Bandera Azul','Excelente. Protegida por cuatro espigones artificiales que forman calas circulares de aguas tranquilas y limpias. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08023','playa','Playa de las Anquines',NULL,'Muy buena. Cala artificial muy segura creada en los años 20 para dar servicio a un hotel histórico. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08023','playa','Playa de Balmins',NULL,'Excelente. Formada por tres pequeñas calas unidas, de tradición nudista y con magníficas vistas al perfil del pueblo. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08023','playa','Playa de Home Mort',NULL,'Muy buena. Cala virgen de difícil acceso a pie bajo los acantilados del macizo del Garraf, referente de tradición LGTBI internacional. Compuesta enteramente de piedras y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08231','playa','Playa de la Vidre',NULL,'Buena. Pequeño tramo playero encajonada entre el término de Sitges y el puerto deportivo de las Botigues. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90026','playa','Playa de Ribes Roges','Bandera Azul','Excelente. Inmenso arenal urbano totalmente llano de más de un kilómetro flanqueado por un gran parque verde que alberga un tren miniatura. Arena blanca y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90026','playa','Playa de Adarró','Bandera Azul','Excelente. Continuación de Ribes Roges, delimitada por una escultura monumental dedicada a Pasífae. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90026','playa','Playa del Far de Sant Cristòfol','Bandera Azul','Excelente. Amplia playa de ambiente muy tranquilo resguardada por el dique del puerto pesquero y un faro histórico. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90026','playa','Playa de Ibersol','Bandera Azul','Muy buena. Playa residencial de baja densidad en el límite con Cubelles. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08074','playa','Playa de la Mota de Sant Pere','Bandera Azul','Excelente. Gran playa familiar delimitada por la desembocadura del río Foix (zona húmeda protegida). Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('08074','playa','Playa Larga (Cubelles)','Bandera Azul','Muy buena. Dividida por una sucesión de pequeños espigones de piedra rectos que calman el oleaje. Arena fina. Sí tiene Bandera Azul. Sigo de forma continua con la Provincia de Tarragona (Costa Daurada). Las respuestas de la IA pueden contener errores. Más información 8 sitios','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43051','playa','Playa de Cunit','Bandera Azul','Excelente. Dividida en siete calas semicirculares mediante espigones de piedra artificiales en forma de isla, lo que frena por completo el oleaje. Arena fina y dorada. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43037','playa','Playa de Calafell','Bandera Azul','Excelente. Conocida históricamente como "el biberón de Europa" por la extrema tranquilidad de sus aguas, su poca profundidad y la alta concentración de yodo. Arena dorada y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43037','playa','Playa de Segur de Calafell','Bandera Azul','Excelente. Gran tramo playero urbano situado frente al paseo marítimo y contiguo al puerto deportivo. Arena fina y dorada. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43037','playa','Playa de Mas Mel','Bandera Azul','Excelente. Playa residencial muy ancha y con pendientes de entrada al mar muy suaves. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('42005','playa','Playa de Coma-ruga','Bandera Azul','Excelente. Famosa por albergar el manantial de agua termal medicinal del Estany i el Riuet, que brota en la misma arena a temperatura constante. Arena fina y dorada. Sí tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('42005','playa','Playa de Sant Salvador','Bandera Azul','Excelente. Extenso arenal bordeado por un paseo marítimo peatonal señorial donde destaca la casa-museo del músico Pau Casals. Arena fina. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('42005','playa','Playa de El Francàs','Bandera Azul','Excelente. La zona costera más meridional y tranquila del municipio, ideal para el descanso familiar. Arena fina y dorada. Sí tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43131','playa','Playa Llarga (Roda de Berà)','Bandera Azul','Excelente. Playa extensa semiurbana dotada de un camping y protegida por un pequeño cordón de dunas regeneradas. Arena fina y dorada. Sí tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43131','playa','Playa de Punta de Guineu','Bandera Azul','Excelente. Preciosa cala pequeña situada al pie del pintoresco conjunto arquitectónico del Roc de Sant Gaietà. Aguas cristalinas. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43131','playa','Playa de Costa Daurada (La Capella)','Bandera Azul','Muy buena. Continuación de los acantilados del municipio, ambiente residencial agradable. Arena fina y dorada. Sí tiene Bandera Azul. [1, 2, 3]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43050','playa','Playa de Creixell','Bandera Azul','Excelente. Inmenso arenal de casi dos kilómetros que destaca por conservar un ecosistema dunar protegido ("Els Muntanyans") prácticamente virgen. Arena fina, blanda y dorada. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43153','playa','Playa de La Paella','Bandera Azul','Excelente. Gran playa urbana situada junto al puerto deportivo, dotada de zonas deportivas y aguas muy tranquilas de poca profundidad. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43153','playa','Playa de Baix a Mar','Bandera Azul','Excelente. Ubicada en el antiguo barrio de pescadores, destaca por albergar en su mar una escultura vanguardista sumergida. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43153','playa','Playa de Els Muntanyans','Bandera Azul','Excelente. Espacio de alto valor ecológico compartido con Creixell, con dunas semimóviles y lagunas de agua salada salvajes. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43153','playa','Playa de El Canyadell','Bandera Azul','Excelente. Preciosa cala virgen encajonada bajo acantilados escarpados y presidida por el último faro construido en España. Arena fina y dorada. Sí tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90048','playa','Playa de Altafulla','Bandera Azul','Excelente. Precioso arenal que combina el encanto de las antiguas casas coloniales de pescadores en primera línea de mar con las vistas al imponente castillo de Tamarit. Arena fina y dorada. Sí tiene Bandera Azul. [1, 2, 3]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43148','playa','Playa del Miracle',NULL,'Muy buena. La playa urbana principal de la ciudad, accesible a pie desde el anfiteatro romano a través de una pasarela. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43148','playa','Playa de L''Arrabassada','Bandera Azul','Excelente. Playa semiurbana muy cuidada, muy querida por los locales y con excelentes servicios para el baño familiar. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43148','playa','Playa de La Savinosa','Bandera Azul','Excelente. Hermosa playa delimitada por rocas calizas y un espeso bosque de pinos, con una zona nudista muy consolidada. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43148','playa','Playa Llarga (Tarragona)',NULL,'Excelente. Kilométrico arenal salvaje rodeado por el bosque de la Marquesa y zonas residenciales de baja densidad. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43148','playa','Cala Fonda (Waikiki)',NULL,'Excelente. Joya virgen de la Costa Daurada. Aislada por completo, sin servicios, rodeada de acantilados arcillosos y pinos que llegan hasta el agua. Nudista. Arena fina y dorada. No tiene Bandera Azul por preservación ecológica.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43148','playa','Cala Jovera',NULL,'Excelente. Pequeña cala de ensueño situada justo debajo del romántico perfil del Castillo de Tamarit. Entorno idílico. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43148','playa','Playa de La Móra','Bandera Azul','Excelente. Enclavada en una urbanización residencial, cuenta con aguas muy tranquilas e ideales para el snorkel. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43148','playa','Playa de Tamarit','Bandera Azul','Excelente. Amplia playa de mar abierto flanqueada por un pinar y zonas de marismas protegidas. Arena fina y dorada. Sí tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('42016','playa','Playa de La Pineda (Vila-seca)','Bandera Azul','Excelente. Enorme playa urbana de casi tres kilómetros dotada de un paseo marítimo colosal con esculturas vanguardistas de pinos de hierro. Aguas muy someras y tranquilas. Arena fina y dorada. Sí tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43905','playa','Playa de Llevant (Salou)','Bandera Azul','Excelente. La playa principal y más turística de la localidad, flanqueada por el paseo de Jaume I, sus palmeras y fuentes luminosas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43905','playa','Playa de Ponent (Salou)','Bandera Azul','Excelente. Continuación de Llevant hacia el oeste, colindante con el puerto, de ambiente muy familiar y aguas tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43905','playa','Playa de Capellans','Bandera Azul','Excelente. Hermosa cala resguardada por acantilados bajos, muy recogida del viento y de gran belleza. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43905','playa','Cala Crancs','Bandera Azul','Excelente. Situada en el Cap Salou, es la cala más apartada y natural del municipio, rodeada de abundante vegetación mediterránea. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43905','playa','Playa de Llarga (Salou)',NULL,'Excelente. Gran playa rodeada de un frondoso bosque de pinos, accesible mediante el camino de ronda, combinando naturaleza y servicios. Arena fina. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43038','playa','Playa del Regueral / Prat d''en Forès','Bandera Azul','Excelente. Playa urbana principal de Cambrils, muy ancha, situada junto al puerto pesquero y deportivo, con servicios excelentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43038','playa','Playa de Vilafortuny','Bandera Azul','Excelente. Amplia playa de carácter residencial unida a Salou por un animado carril bici costero. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43038','playa','Playa de Cavet','Bandera Azul','Excelente. Playa tranquila que combina zonas de baño con un canal para la práctica de deportes de vela y windsurf. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43038','playa','Playa de L''Esquirol','Bandera Azul','Excelente. Gran extensión de arena ideal para largos paseos a pie, muy cómoda y accesible. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43038','playa','Playa de La Llosa',NULL,'Excelente. Protegida por espigones artificiales exentos en el mar que calman por completo el oleaje creando calas familiares. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43038','playa','Playa de L''Ardiaca',NULL,'Muy buena. Situada en el extremo sur del municipio, delimitada por espigones en forma de herradura. Arena fina mezclada con algo de grava gruesa. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90051','playa','Playa de El Cavet (Tramo norte)',NULL,'Muy buena. Pequeña franja costera gestionada por este municipio rural, encajada entre Cambrils y el término de Salou. Arena fina y dorada. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90050','playa','Playa de Pixerota','Bandera Azul','Excelente. Gran playa elegida históricamente por el pintor Joan Miró para inspirarse. Arena fina y dorada mezclada con cantos rodados finos. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90050','playa','Playa de Cristall','Bandera Azul','Excelente. Ubicada en el núcleo de Miami Platja, es un arenal amplio de gran calidad turística y aguas cristalinas profundas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90050','playa','Cala Vianes / Cala Misteri','Bandera Azul','Excelente. Sucesión de calas preciosas excavadas bajo acantilados de tierra rojiza cubiertos de pinos mediterráneos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90050','playa','Playa de L''Estany Gelat',NULL,'Muy buena. Playa natural asociada a una pequeña laguna costera donde desemboca un torrente. Arena fina y cantos rodados. No tiene Bandera Azul. [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43162','playa','Playa de L''Arenal (L''Hospitalet)','Bandera Azul','Excelente. Inmenso arenal que flanquea el pueblo, muy ancho y dotado de una base náutica de deportes náuticos de referencia. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43162','playa','Playa de Punta del Riu','Bandera Azul','Excelente. Situada junto al puerto deportivo y la desembocadura del río Llastres, ideal para deportes de viento. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43162','playa','Playa del Torn','Bandera Azul','Excelente. Una de las playas naturistas más famosas de Europa. Un entorno completamente virgen integrado en un espacio de interés natural con un islote rocoso fortificado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43162','playa','Playa de L''Almadrava (Vandellòs)','Bandera Azul','Excelente. Pequeño núcleo marinero de casitas blancas tradicionales a pie de playa, de aguas en calma absoluta. Arena fina y cantos rodados. Sí tiene Bandera Azul. [1, 2, 3]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90049','playa','Cala Forn','Bandera Azul','Excelente. Preciosa cala de aguas hipertransparentes de color verde esmeralda rodeada de frondosos pinos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90049','playa','Playa de l''Alguer','Bandera Azul','Excelente. Playa urbana situada en el mismo pueblo pesquero de L''Ametlla, muy acogedora y familiar. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90049','playa','Cala Calafató','Bandera Azul','Excelente. Pequeña cala virgen encajada entre acantilados bajos, un paraíso absoluto para el buceo y el snorkel. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90049','playa','Playa de Sant Jordi','Bandera Azul','Excelente. Presidida por un imponente castillo medieval restaurado del siglo XIII, cuenta con calas y servicios magníficos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90049','playa','Cala Pixavaques',NULL,'Muy buena. Contigua a l''Alguer, compartiendo sus aguas limpias y tranquilas. Arena fina y dorada. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43104','playa','Playa de Santa Llúcia',NULL,'Excelente. Gran playa rodeada de pinos y senderos naturales de roca, de ambiente muy tranquilo y familiar. Arena fina, dorada y guijarros en los extremos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43104','playa','Playa de Cala Moros',NULL,'Muy buena. Pequeña cala resguardada con aguas cristalinas de poca profundidad. Arena fina y piedras calizas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43104','playa','Playa de Pont de l''Àliga',NULL,'Buena. Paisaje virgen abrupto cruzado por el antiguo camino de ronda, oleaje moderado. Grava y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43906','playa','Playa de l''Arenal (L''Ampolla)','Bandera Azul','Excelente. Situada en el inicio de la bahía del Fangar (Delta del Ebro). De gran extensión y aguas extremadamente someras y cálidas. Arena dorada y muy fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43906','playa','Playa de Cap Roig','Bandera Azul','Excelente. Impresionante playa rodeada de acantilados rojizos cubiertos de vegetación baja, de gran valor paisajístico. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43906','playa','Playa de Les Avellanes',NULL,'Muy buena. Playa urbana central muy cómoda, con un paseo marítimo animado y todos los servicios a pie de playa. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43906','playa','Playa de Els Capellans',NULL,'Buena. Pequeña cala resguardada de piedras y rocas, muy tranquila. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43901','playa','Playa de Punta del Fangar',NULL,'Excelente. Espectacular desierto de dunas móviles kilométricas rodeado de espejismos marinos, coronado por el icónico faro del Fangar. Entorno estrictamente virgen e integrado en el Parque Natural del Delta del Ebro. Arena blanca finísima. No tiene Bandera Azul (sin servicios urbanos por protección).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43901','playa','Playa de Riumar','Bandera Azul','Excelente. Situada junto a la urbanización del mismo nombre y la desembocadura del río Ebro. Cuenta con pasarelas de madera elevadas sobre dunas protegidas y es muy buscada para la pesca deportiva. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43901','playa','Playa de La Marquesa',NULL,'Excelente. Playa salvaje e infinita de mar abierto que sufre la regresión del delta. Un paraíso de paz. Arena fina y dorada. No tiene Bandera Azul. [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43902','playa','Playa del Serrallo',NULL,'Excelente. Playa totalmente aislada e interminable en el corazón del Delta del Ebro, flanqueada por campos de arroz y dunas bajas. Nula masificación turística. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43902','playa','Playa de Migjorn',NULL,'Excelente. Situada junto a la antigua desembocadura del río (gola de Migjorn) y la isla de Buda. Entorno totalmente natural. Arena fina. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43014','playa','Playa de Eucaliptus',NULL,'Excelente. Kilométrica playa virgen que debe su nombre a los árboles que flanquean sus accesos. Caracterizada por la inmensidad del paisaje y la presencia de dunas con vegetación salina. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43136','playa','Playa de Les Delícies','Bandera Azul','Excelente. Playa urbana principal resguardada de las olas por la Bahía de los Alfaques, lo que garantiza aguas mansas y templadas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43136','playa','Playa de El Garbí','Bandera Azul','Excelente. Situada frente al gran paseo marítimo y dotada de zonas verdes de césped anexas a la arena. Aguas poco profundas ideales para niños. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43136','playa','Playa de Capri',NULL,'Muy buena. Pequeña y céntrica, muy protegida por espigones. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43136','playa','Playa de Aiguassera',NULL,'Buena. Rodeada de un ambiente tranquilo de segundas residencias, oleaje nulo. Arena fina y grava fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('43136','playa','Playa del Trabucador',NULL,'Excelente. Espectacular e infinita lengua de arena de solo unos metros de ancho con el mar a ambos lados (el mar abierto por fuera y la tranquila bahía por dentro). Meca internacional del kitesurf. Arena dorada finísima. No tiene Bandera Azul (protección estricta). [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90047','playa','Playa de Les Cases d''Alcanar',NULL,'Muy buena. Ubicada en el encantador núcleo pesquero tradicional del municipio, aguas limpias y tranquilas de ambiente familiar. Compuesta principalmente por cantos rodados pulidos (piedras redondas). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90047','playa','Playa de Martinenca',NULL,'Muy buena. Amplia playa de aguas tranquilas protegida por el dique de una fábrica de cemento cercana, de excelente calidad de aguas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90047','playa','Playa de Maricel',NULL,'Buena. Playa lineal de carácter tranquilo alejada de aglomeraciones urbanas. Compuesta de grava fina y arena oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90047','playa','Playa de Sòl de Riu',NULL,'Muy buena. Situada en la misma desembocadura del río Cenia, frontera natural con la Comunidad Valenciana. Paisaje de acantilados bajos muy vírgenes. Cantos rodados y piedras. No tiene Bandera Azul. [1] Sigo de forma continua con la Comunidad Valenciana, empezando por la Provincia de Castellón (Costa del Azahar). Las respuestas de la IA pueden contener errores. Más información 47 sitios','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90047','playa','El dilema provincial de Cunit',NULL,'¿ Quedarse en Tarragona o irse a Barcelona? 20 oct 2025 — El alcalde de Cunit plantea una consulta ciudadana para que los vecinos de la localidad puedan decidir un posible cambio de provin... COPE','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90047','playa','Playas de Tarragona',NULL,'un paraíso costero por descubrir 23 sept 2025 — Este verano fuimos a la playa de Cunit, ya hacía tiempo que no íbamos y sigue siendo tan bonita como la recordaba. La arena suave ... Minube','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11018','playa','Playa de Fora Forat','Bandera Azul','Excelente. Gran playa urbana situada junto al paseo marítimo y rodeada de palmeras. Arena dorada de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11018','playa','Playa de El Fortí','Bandera Azul','Excelente. Playa céntrica y muy espaciosa con un nivel de servicios muy elevado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11018','playa','Cala de Sól de Riu',NULL,'Muy buena. Situada al norte, en la desembocadura del río Cenia (frontera con Cataluña). Entorno natural protegido con acantilados rojizos. Grava y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11018','playa','Cala Els Pinets',NULL,'Buena. Pequeña cala resguardada rodeada de vegetación baja. Arena gruesa y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11018','playa','Playa de Aiguadoliva',NULL,'Aceptable. Primera playa canina oficial de la zona, situada al sur en la desembocadura de un barranco. Compuesta por piedras y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12027','playa','Playa de la Morrongo','Bandera Azul','Excelente. Tradicional playa urbana del municipio, muy protegida por el puerto y con aguas muy mansas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12027','playa','Playa de la Caracola','Bandera Azul','Muy buena. Enlace natural con Peñíscola, de carácter semiurbano y ambiente muy tranquilo. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12027','playa','Playa de Gurugú',NULL,'Buena. Playa abierta muy extensa y tranquila, ideal para huir de las masas. Grava fina y arena. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12027','playa','Playa de Mar Xica',NULL,'Buena. Situada junto al puerto deportivo, aguas muy limpias y profundas a pocos metros. Compuesta íntegramente de cantos rodados (piedras). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12089','playa','Playa Norte (Peñíscola)','Bandera Azul','Excelente. Impresionante y kilométrico arenal urbano con el castillo templario del Papa Luna siempre en el horizonte. Aguas tranquilas y servicios excelentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12089','playa','Playa Sur (Peñíscola)',NULL,'Muy buena. Resguardada al pie de las murallas y el puerto, aguas en calma absoluta pero con menor ventilación que la playa norte. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12089','playa','Playa de Torrenova',NULL,'Excelente. Ubicada en pleno Parque Natural de la Sierra de Irta, entorno virgen y salvaje sin ninguna edificación. Arena fina y piedra. No tiene Bandera Azul (protección medioambiental).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12089','playa','Cala Badum',NULL,'Excelente. Espectacular cala oculta bajo un acantilado monumental coronado por una torre vigía. Compuesta por grava, piedras y fondos rocosos para snorkel. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12089','playa','Playa del Ruso',NULL,'Muy buena. Una de las pocas playas de arena fina naturales dentro de la Sierra de Irta, acceso por pistas de tierra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12089','playa','Playa de Pebret',NULL,'Muy buena. Vecina de la del Ruso, rodeada de dunas protegidas y vegetación costera mediterránea. Arena fina y conchas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11001','playa','Playa de Las Fuentes','Bandera Azul','Excelente. Única por sus manantiales de agua dulce procedentes de un acuífero que brotan directamente desde la arena del mar. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11001','playa','Playa de Cargador','Bandera Azul','Excelente. La playa más céntrica y ancha del núcleo urbano, dotada de dunas protegidas en un extremo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11001','playa','Playa Romana','Bandera Azul','Excelente. Separada de Cargador por una duna de alto valor ecológico, aguas muy limpias. Arena dorada de excelente calidad. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11001','playa','Playa del Moro','Bandera Azul','Excelente. Debe su nombre a una roca que emerge frente a ella, ambiente familiar impecable. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11001','playa','Playa de Manyetes / Tropicana','Bandera Azul','Excelente. Situada en una zona semiurbana tranquila rodeada de campos agrícolas. Arena fina y cantos rodados en el borde. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11001','playa','Cala Blanca',NULL,'Buena. Pequeña cala virgen al norte del municipio, pegada a la Sierra de Irta. Grava fina y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12117','playa','Playa de Torrenostra','Bandera Azul','Excelente. Gran playa urbana protegida por espigones paralelos a la costa que calman el oleaje por completo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12117','playa','Playa de la Nord','Bandera Azul','Excelente. Continuación urbana con un paseo moderno y zonas de juego infantiles. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12117','playa','Playa de El Prat',NULL,'Excelente. Espacio totalmente virgen integrado en el Parque Natural del Prat de CabanesTorreblanca (zona de marismas y humedales). Nula edificación. Grava, cantos rodados y arena gruesa. No tiene Bandera Azul por preservación ecológica.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12033','playa','Playa de la Torre de la Sal',NULL,'Muy buena. Debe su nombre a una antigua torre vigía fortificada, rodeada de un frondoso bosque de eucaliptos y campings populares. Grava fina y pasillos de arena dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12033','playa','Playa del Cuartell Vell',NULL,'Buena. Espacio natural muy tranquilo lindando con el parque natural, escasa afluencia. Piedras y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12085','playa','Playa de Les Amplaries','Bandera Azul','Muy buena. El arenal más extenso del municipio, flanqueado por los grandes complejos de Marina d''Or y amplias zonas verdes ajardinadas. Arena fina y dorada con grava. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12085','playa','Playa de Morro de Gos','Bandera Azul','Excelente. Amplia playa semiurbana peatonal de aguas limpias y oleaje moderado. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12085','playa','Playa de La Concha (Oropesa)','Bandera Azul','Excelente. Bahía natural con forma de concha perfecta que frena las corrientes y el oleaje. El centro neurálgico del turismo local. Arena dorada y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12085','playa','Cala Oropesa la Vella',NULL,'Muy buena. Diminuta cala que parece una prolongación natural de La Concha, separada de esta por un pequeño promontorio rocoso. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12085','playa','Playa de Les Platgetes de Bellver','Bandera Azul','Excelente. Zona residencial tranquila protegida por espigones que forman calas seguras de aguas transparentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12085','playa','Cala Retor',NULL,'Buena. Cala pequeña y resguardada situada junto al puerto deportivo, ideal para el baño de niños por su nulo oleaje. Arena fina y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12085','playa','Playa de la Renegá',NULL,'Excelente. Un paraje salvaje espectacular esculpido por el mar, rodeado de pinos tortuosos que llegan al agua y rocas rotas. Paraíso del snorkel. Compuesta íntegramente por rocas y grava. No tiene Bandera Azul (carácter virgen).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11004','playa','Playa de Voramar','Bandera Azul','Excelente. Famosa por estar flanqueada por las espectaculares villas modernistas de principios del siglo XX (la "Biarritz valenciana"). Aguas hipertransparentes y tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11004','playa','Playa de Almadraba','Bandera Azul','Excelente. Continuación del paseo de las villas, dotada de biblioteca del mar y accesibilidad universal. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11004','playa','Playa de Torre de San Vicente','Bandera Azul','Excelente. Presidida por una imponente torre de defensa del siglo XVI en mitad del paseo marítimo, muy animada. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11004','playa','Playa de Els Terrers','Bandera Azul','Excelente. Diseñada con espigones circulares que retienen la arena y crean un ambiente ideal para escuelas de vela y windsurf. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11004','playa','Playa de Heliópolis','Bandera Azul','Excelente. La playa más kilométrica de Benicàssim, recorrida por un carril bici muy amplio que conecta con Castellón. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12040','playa','Playa del Gurugú (Castellón)','Bandera Azul','Excelente. Playa urbana que se extiende desde el puerto hasta el cruce del río Seco, dotada de aeroclub anexo y chiringuitos muy activos en verano. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12040','playa','Playa del Pinar','Bandera Azul','Excelente. Situada junto al gran parque del Pinar y el planetario de la ciudad, muy ancha y espaciosa. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12040','playa','Playa Serradal','Bandera Azul','Excelente. Destaca por albergar una microrreserva dunar protegida donde anida el chorlitejo patinegro, combinando turismo y ecología. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12009','playa','Playa de Benafelí',NULL,'Buena. Dividida por espigones de piedra para frenar la erosión costera, ambiente marcadamente residencial local. Arena dorada gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12009','playa','Playa de les Goles',NULL,'Aceptable. Situada junto a la desembocadura del río Mijares, entorno natural protegido pero poco apto para el baño cómodo. Compuesta de piedras y fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12032','playa','Playa de L''Arenal (Burriana)','Bandera Azul','Excelente. Inmenso arenal urbano célebre por albergar el festival de música Arenal Sound. Muy ancha y de aguas tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12032','playa','Playa de Grao',NULL,'Buena. Situada al norte del puerto, de carácter más residencial y menor densidad de bañistas. Arena fina y piedras gruesas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12082','playa','Playa de Nules (Les Marines)',NULL,'Buena. Sucesión de calas protegidas por espigones de piedra rectos, ambiente de casitas tradicionales de veraneo en primera línea de mar. Compuesta por grava fina, cantos rodados y pasillos de arena dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12077','playa','Playa del Grao','Bandera Azul','Excelente. Playa céntrica muy cuidada con un paseo marítimo animado y todos los servicios turísticos. Arena dorada y grava. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12077','playa','Playa de L''Estanyol','Bandera Azul','Excelente. Cuenta con una zona de dunas protegidas y es muy tranquila. Arena fina y cantos rodados. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12077','playa','Playa de Masbó','Bandera Azul','Excelente. Muy limpia y de aguas transparentes con pendientes de entrada al mar moderadas. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12077','playa','Playa de Pedra Roja','Bandera Azul','Excelente. Siguiente tramo costero premiado por su calidad ambiental e infraestructuras. Arena dorada y grava. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12053','playa','Playa de El Cerezo','Bandera Azul','Excelente. Playa urbana muy singular gracias a una gran pasarela de madera que se adentra de forma peatonal sobre el mar. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12053','playa','Playa de Les Cases (Chilches)','Bandera Azul','Excelente. Amplio arenal que combina zonas urbanizadas con pinadas y zonas recreativas excelentes. Arena dorada de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12074','playa','Playa de La Llosa',NULL,'Buena. Franja playera completamente virgen y aislada rodeada de campos de cultivo marismeños, sin paseo marítimo. Compuesta de grava gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('12011','playa','Playa de Casablanca',NULL,'Muy buena. Playa de carácter tranquilo que conserva dunas naturales regeneradas con pasarelas de madera, alejada del ladrillo masivo. Compuesta por cantos rodados en la orilla y arena dorada de grano grueso. No tiene Bandera Azul. Sigo de forma continua con la Provincia de Valencia. Las respuestas de la IA pueden contener errores. Más información Has dicho: sigue','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('45013','playa','Playa del Puerto de Sagunto','Bandera Azul','Excelente. Enorme playa urbana muy ancha, resguardada por el dique norte del puerto, con un paseo marítimo repleto de servicios y restaurantes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('45013','playa','Playa de Almardà','Bandera Azul','Excelente. Gran arenal semiurbano con un cordón dunar de gran valor ecológico perfectamente conservado, aguas muy limpias. Grava fina en la orilla y arena dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('45013','playa','Playa de Corinto-Malvarrosa','Bandera Azul','Excelente. La playa más septentrional y salvaje del municipio, con nula masificación turística y dunas naturales. Compuesta por cantos rodados, grava y pasillos de arena gruesa. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46082','playa','Playa de Racó de Mar','Bandera Azul','Excelente. Considerada de forma recurrente una de las mejores playas de la provincia. Cuenta con dunas protegidas, un paseo marítimo impecable y aguas cristalinas de poca profundidad. Arena blanca y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90053','playa','Playa de Puçol','Bandera Azul','Excelente. Playa semiurbana protegida por espigones paralelos de piedra que calman el oleaje, dotada de un paseo marítimo peatonal muy agradable. Arena fina y dorada con algo de grava. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46204','playa','Playa de Plans-Mar',NULL,'Muy buena. Sucesión de pequeñas calas delimitadas por espigones rectos, ambiente residencial local muy tranquilo. Grava fina y arena dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46204','playa','Playa de Santa Elvira-La Torreta',NULL,'Buena. Zona de playa que cuenta con un tramo acotado oficialmente para el acceso con perros. Compuesta por cantos rodados y arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46204','playa','Playa del Barri de Mar',NULL,'Buena. Situada frente a las urbanizaciones del municipio, paseo cómodo. Arena gruesa y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46199','playa','Playa de Pobla de Farnals (Norte)','Bandera Azul','Excelente. Playa urbana resguardada por el puerto deportivo Pobla Marina, lo que garantiza aguas en calma absoluta ideales para familias. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46164','playa','Playa de Massamagrell',NULL,'Aceptable. Pequeño tramo costero de carácter virgen e intermareal situado en una zona de marjales protegidos, sin servicios turísticos urbanos. Compuesta de grava, tierra y fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46207','playa','Playa de Rafelbunyol',NULL,'Aceptable. Estrecha franja de costa natural continua que comparte el ecosistema de marjal e hito geográfico con Massamagrell. No apta para turismo de masas. Grava y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90052','playa','Playa de El Perelló',NULL,'Muy buena. Municipio administrativamente independiente rodeado por el parque natural. Playa urbana muy familiar y concurrida, estrecha pero con excelentes servicios. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46013','playa','Playa de la Patacona',NULL,'Excelente. Continuación natural de la Malvarrosa de Valencia, muy de moda por sus chiringuitos de diseño y su ambiente joven y deportivo. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46013','playa','Playa de Port Saplaya (Norte y Sur)',NULL,'Muy buena. Playas urbanas que flanquean la pintoresca marina residencial conocida como la "Pequeña Venecia" por sus canales interiores. Aguas muy tranquilas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46250','playa','Playa de la Malvarrosa',NULL,'Excelente. La playa urbana por excelencia de la ciudad, inmortalizada por Sorolla. Inmensamente ancha y flanqueada por un paseo marítimo monumental repleto de restaurantes. Arena fina y dorada. No tiene Bandera Azul (política local de distinciones Q de calidad).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46250','playa','Playa de las Arenas / El Cabañal',NULL,'Excelente. Continuación de la Malvarrosa junto al puerto de Valencia, ambiente tradicional marinero muy animado. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46250','playa','Playa de Pinedo',NULL,'Muy buena. Situada al sur del puerto, cuenta con un tramo delimitado para perros y zona nudista tradicional, protegida de los vientos del norte. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46250','playa','Playa de L''Arbre del Gos',NULL,'Excelente. Primera playa situada en el entorno del Parque Natural de la Albufera, dotada de carril bici y dunas regeneradas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46250','playa','Playa de El Saler',NULL,'Excelente. Impresionante arenal salvaje rodeado de pinares mediterráneos y dunas indómitas de gran valor ecológico. Aguas limpias y abiertas. Arena fina y dorada. No tiene Bandera Azul (por preservación del parque).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46250','playa','Playa de la Garrofera',NULL,'Excelente. Escondida entre la Dehesa de El Saler y el mar, ambiente virgen muy tranquilo y de tradición naturista. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46250','playa','Playa de la Devesa',NULL,'Excelente. La playa más protegida y salvaje del parque natural, acceso restringido a pasarelas para proteger las dunas y la fauna endémica. Arena dorada finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46250','playa','Playa de Recatí (Perellonet)',NULL,'Muy buena. Extensa playa residencial situada frente a la gola de la Albufera, muy frecuentada por residentes locales y amantes del kitesurf. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46235','playa','Playa de Les Palmeres',NULL,'Excelente. Playa urbana tradicional muy familiar con un paseo tranquilo de casas bajas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46235','playa','Playa de Mareny de Barraquetes',NULL,'Excelente. Entorno semiurbano rodeado de campos de arroz, con dunas protegidas y baja densidad de bañistas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46235','playa','Playa de Motilla',NULL,'Muy buena. Pequeña zona de costa residencial de ambiente muy tranquilo. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46235','playa','Playa de Bega de Mar',NULL,'Muy buena. Playa muy ancha con un cordón dunar recuperado excelente para el descanso familiar. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46235','playa','Playa del Rey',NULL,'Muy buena. Limita con el término de Cullera, aguas limpias y tranquilas. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46105','playa','Playa de San Antonio (Cullera)','Bandera Azul','Excelente. La playa más céntrica, urbana y cosmopolita del municipio, protegida por la bahía, con aguas totalmente mansas y someras. Arena dorada finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46105','playa','Playa de Racó','Bandera Azul','Excelente. Zona residencial con grandes torres de apartamentos hoteleros, servicios impecables y escuela de vela. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46105','playa','Playa de El Dossel','Bandera Azul','Excelente. Paisaje espectacular con uno de los cordones dunares más imponentes y mejor conservados de la Comunidad Valenciana, ambiente virgen. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46105','playa','Playa de Los Olivos','Bandera Azul','Excelente. Preciosa cala pequeña de aguas tranquilas encajonada entre dos espigones, ideal para niños pequeños. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46105','playa','Playa de Cap Blanc','Bandera Azul','Excelente. Muy valorada por los amantes del windsurf debido a los regímenes constantes de vientos térmicos por la tarde. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46105','playa','Playa del Far','Bandera Azul','Muy buena. Cala pequeña de carácter rocoso ideal para la práctica del buceo de superficie y la pesca con caña. Arena fina y rocas calizas. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46105','playa','Playa de Marenyet',NULL,'Muy buena. Situada al sur de la desembocadura del río Júcar, playa de mar abierto muy buscada por surfistas locales por su oleaje. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46105','playa','Playa de l''Estany',NULL,'Excelente. Preciosa playa de ambiente rural que colinda con una laguna natural de agua dulce que comunica con el mar. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46238','playa','Playa de Tavernes de la Valldigna','Bandera Azul','Excelente. Gran playa urbana con excelentes equipamientos, ambiente muy familiar y paseo peatonal moderno. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46238','playa','Playa de la Goleta','Bandera Azul','Excelente. Continuación hacia el norte, cuenta con un canal náutico señalizado y dunas naturales en sus márgenes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90054','playa','Playa de Xeraco','Bandera Azul','Excelente. Destaca por su urbanismo de baja densidad libre de grandes torres de ladrillo, manteniendo un cordón dunar inmenso con pasarelas de madera y aguas muy limpias. Arena dorada y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46131','playa','Playa Nord (Gandia)','Bandera Azul','Excelente. Referente turístico nacional de primer orden. Un arenal colosal de más de 3 kilómetros de largo y más de 150 metros de ancho, con un despliegue de servicios e infraestructuras inigualable. Arena dorada finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46131','playa','Playa de L''Auir',NULL,'Excelente. Una de las pocas playas vírgenes y libres de edificación que quedan en la provincia. Alberga dunas móviles protegidas, zona nudista oficial y playa canina. Arena fina y dorada. No tiene Bandera Azul (preservación natural del entorno).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46131','playa','Playa de Venecia (Gandia)',NULL,'Buena. Pequeña playa situada al sur del puerto y la desembocadura del río Serpis, aguas muy tranquilas protegidas por un espigón. Arena fina y vegetación de ribera. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46131','playa','Playa de Rafalcaid',NULL,'Muy buena. Siguiente tramo hacia el sur, de ambiente marcadamente residencial local y tranquilo. Arena fina mezclada con algo de canto rodado. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46113','playa','Playa de Daimús','Bandera Azul','Excelente. Playa familiar muy cuidada que da continuidad a la línea de costa del sur de Gandia, con plazas públicas que mueren en la misma arena. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46140','playa','Playa de Guardamar de la Safor','Bandera Azul','Excelente. Playa pequeña de ambiente residencial muy tranquilo, alejada de las masificaciones y dotada de dunas en regeneración continua. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46048','playa','Playa de Bellreguard','Bandera Azul','Excelente. A pesar de su extensión reducida, cuenta con un nivel de servicios excelente por metro cuadrado de arena y un paseo marítimo peatonal muy dinámico. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46168','playa','Playa de Miramar','Bandera Azul','Excelente. Playa urbana de carácter marcadamente familiar, muy limpia y dotada de bibliomar y todo tipo de facilidades para el baño accesible. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46195','playa','Playa de Piles','Bandera Azul','Excelente. Gran arenal muy espacioso recorrido por un paseo marítimo moderno, ambiente relajado ideal para el turismo de descanso. Arena dorada y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46181','playa','Playa de Terranova','Bandera Azul','Excelente. Playa completamente rodeada de huertos de naranjos y dunas naturales, con nula masificación turística y un manantial de agua dulce anexo ("El Tou"). Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46181','playa','Playa de Pau Pi','Bandera Azul','Excelente. La playa tradicional del municipio, dotada de club náutico y un diseño urbano peatonal muy integrado de casas bajas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46181','playa','Playa de Aigua Morta','Bandera Azul','Excelente. Espectacular arenal donde desemboca el río Bullent (límite del Parque Natural del Marjal de Pego-Oliva), aguas hipertransparentes muy buscadas para el golf y el windsurf. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46181','playa','Playa de L''Aigua Blanca','Bandera Azul','Excelente. Premiada por su calidad ambiental, flanqueada por un cordón dunar amplio que separa los apartamentos de la arena. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46181','playa','Playa de Rabdells',NULL,'Excelente. Playa semiurbana muy tranquila rodeada de campings populares de alta calidad y dunas salvajes. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('46181','playa','Playa de Les Deveses (Oliva)',NULL,'Muy buena. Tramo meridional que conecta directo con el término de Dénia, viento constante idóneo para deportes de vela. Arena fina. No tiene Bandera Azul. Sigo de forma continua con la Provincia de Alicante (Costa Blanca). Las respuestas de la IA pueden contener errores. Más información Has dicho: sigue','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03014','playa','Playa de Les Marines','Bandera Azul','Excelente. Gran playa familiar de aguas tranquilas y poca profundidad, dotada de todo tipo de servicios turísticos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03014','playa','Playa de Les Bovetes','Bandera Azul','Excelente. Extenso arenal muy concurrido en verano, ideal para la práctica de deportes náuticos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03014','playa','Playa de Molins','Bandera Azul','Excelente. Playa tranquila y ventosa por las tardes, lo que la convierte en punto de encuentro para el windsurf. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03014','playa','Playa de Punta del Raset','Bandera Azul','Muy buena. La más cercana al puerto y al centro urbano, muy ancha y con dunas protegidas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03014','playa','Playa de Les Albaranes',NULL,'Muy buena. Zona residencial de baja densidad con un bonito cordón dunar restaurado. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03014','playa','Playa de Marineta Cassiana','Bandera Azul','Muy buena. Situada al sur del puerto, es una bahía casi cerrada de aguas muy mansas y templadas. Arena fina y oscura con presencia de algas (posidonia). Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03014','playa','Playa de Les Rotes (Cala de l''Aigua Dolç / Trampolí)',NULL,'Excelente. Espectacular tramo rocoso integrado en la Reserva Marina del Cabo de San Antonio, paraíso del snorkel. Compuesta íntegramente de roca calcárea y piedra suelta. No tiene Bandera Azul (carácter natural protegido).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03022','playa','Playa de L''Arenal (Jávea)','Bandera Azul','Excelente. La única playa de arena del municipio, situada en el centro de la bahía y rodeada de un paseo repleto de ocio. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03022','playa','Playa de La Granadella','Bandera Azul','Excelente. Catalogada varias veces como una de las calas más bonitas de España. Un cañón de roca con aguas de color verde esmeralda e hipertransparentes. Compuesta de cantos rodados y piedra blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03022','playa','Cala Portitxol / La Barraca',NULL,'Excelente. Pintoresca cala frente a la isla del Portitxol, famosa por sus antiguas casitas de pescadores con puertas pintadas de azul. Grava, cantos rodados y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03022','playa','Playa del Benissero / Primer Muntanyar',NULL,'Muy buena. Tramo de costa abierta ideal para el windsurf y los chiringuitos de verano. Compuesta por piedra tosca natural (fósil) y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03022','playa','Playa de La Grava','Bandera Azul','Muy buena. Situada junto al barrio marinero de Duanes de la Mar y el puerto, de aguas muy limpias. Compuesta enteramente de cantos rodados pulidos. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03022','playa','Cala Blanca',NULL,'Muy buena. Sucesión de dos pequeñas calas unidas por un paseo marítimo esculpido en la roca caliza blanca. Piedra y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03022','playa','Cala Ambolo',NULL,'Excelente. Cala virgen y salvaje situada bajo imponentes acantilados, de tradición nudista. Acceso restringido por riesgo de desprendimientos. Compuesta de piedras y roca. No tiene Bandera Azul. [1, 2, 3]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90008','playa','Cala del Moraig',NULL,'Excelente. Impresionante cala encajonada bajo acantilados colosales, donde se encuentra la Cova dels Arcs (boca de un río subterráneo). Aguas de color turquesa intenso. Compuesta de cantos rodados y roca viva. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90008','playa','Cala Llebeig',NULL,'Muy buena. Cala recóndita y virgen a la que se accede únicamente a pie a través de la ruta de los acantilados o por barranco. Conserva antiguas construcciones de piedra. Piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03037','playa','Playa de L''Ampolla (Moraira)','Bandera Azul','Excelente. Situada a los pies del castillo de Moraira, es la playa urbana más concurrida y cómoda, de aguas muy tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03037','playa','Playa de El Portet','Bandera Azul','Excelente. Preciosa cala con forma de concha y aguas hipertransparentes y mansas, que asemeja una piscina natural caribeña. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03037','playa','Cala Les Platgetes','Bandera Azul','Excelente. Dos pequeñas calas que combinan una zona de arena con una plataforma de roca ideal para pescar o bucear. Arena fina y roca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03037','playa','Cala Andragó',NULL,'Muy buena. Espectacular mirador de roca y pinos, aguas profundas perfectas para el submarinismo. Compuesta enteramente de roca caliza. No tiene Bandera Azul. [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03009','playa','Cala Fustera','Bandera Azul','Excelente. La playa más importante y equipada del municipio, rodeada de pinos que llegan hasta el borde de la arena. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03009','playa','Cala Baladrar',NULL,'Muy buena. Cala salvaje rodeada de un pinar, dividida por un saliente rocoso y de aguas muy transparentes. Compuesta de cantos rodados y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03009','playa','Cala Advocat',NULL,'Buena. Cuenta con un pequeño espigón de piedra que frena las olas y un entorno acantilado muy tranquilo. Grava fina y arena. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03009','playa','Cala Pinets',NULL,'Buena. Pequeña y salvaje, ideal para ir con niños a buscar cangrejos en sus charcas naturales de roca. Piedra y roca. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03010','playa','Playa de la Fossa / Levante','Bandera Azul','Excelente. Un arenal espectacular flanqueado por un animado paseo marítimo y presidido por la imponente mole del Peñón de Ifach. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03010','playa','Playa de Cantal Roig','Bandera Azul','Excelente. Pequeña playa situada justo al lado del puerto pesquero, muy resguardada del viento y con aguas mansas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03010','playa','Playa Arenal-Bol','Bandera Azul','Excelente. El arenal más extenso de Calpe, situado en el centro urbano y con vistas frontales al peñón. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03010','playa','Cala El Racó',NULL,'Muy buena. Situada a los pies del Peñón de Ifach, cuenta con un sendero submarino señalizado para buceo. Compuesta de cantos rodados y piedra suelta. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03010','playa','Cala Les Urques',NULL,'Buena. Cala canina oficial rodeada de naturaleza salvaje al sur del municipio. Piedra y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03010','playa','Cala Gasparet',NULL,'Regular. Completamente aislada, solo accesible por mar o a través de barrancos complejos. Compuesta de cantos rodados. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03004','playa','Playa de Cap Blanch','Bandera Azul','Excelente. Gran playa urbana que conecta el puerto de Altea con El Albir, dotada de un paseo marítimo muy cuidado. Compuesta de cantos rodados (piedra blanca pulida). Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03004','playa','Playa de L''Espigó','Bandera Azul','Excelente. Franja costera recuperada frente al centro del pueblo, muy cómoda y de aguas limpias. Compuesta de cantos rodados y grava. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03004','playa','Playa de L''Olla',NULL,'Muy buena. Situada frente a una pequeña isla accesible a nado o en kayak, famosa por su espectáculo pirotécnico estival. Cantos rodados y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03004','playa','Playa de Barreta de Gualda',NULL,'Buena. Pequeña playa rústica situada junto al puerto deportivo Luis Campomanes. Piedra y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03004','playa','Playa de Mascarat',NULL,'Muy buena. Espectacular entorno rodeado de acantilados colosales en el límite con Calpe. Compuesta de cantos rodados y piedra. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90009','playa','Playa de Raco de L''Albir','Bandera Azul','Excelente. Magnífica playa urbana con un paseo marítimo minimalista de mármol decorado con estrellas (Paseo de las Estrellas del cine). Aguas muy limpias y profundas. Compuesta íntegramente por cantos rodados (piedra redonda blanca). Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90009','playa','Cala Amerador',NULL,'Buena. Cala natural e inhóspita situada bajo el sendero que sube al faro de l''Albir. Roca viva y piedra. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03007','playa','Playa de Levante (Benidorm)','Bandera Azul','Excelente. Una de las playas urbanas más famosas del mundo, con más de 2 km de longitud, sol garantizado todo el día y un despliegue masivo de servicios. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03007','playa','Playa de Poniente (Benidorm)','Bandera Azul','Excelente. El arenal más largo de la ciudad, bordeado por un paseo arquitectónico vanguardista de colores. Más tranquila y residencial que Levante. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03007','playa','Playa de Mal Pas','Bandera Azul','Excelente. Pequeña playa paradisíaca escondida en una cala entre los dos grandes arenales, justo debajo del mirador del Castillo (Balcón del Mediterráneo). Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03007','playa','Cala Tio Ximo',NULL,'Muy buena. Diminuta cala natural situada en el Parque Natural de la Serra Gelada, ideal para el snorkel en aguas profundas y tranquilas. Nudista. Arena fina y rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03007','playa','Cala Almadrava (Benidorm)',NULL,'Muy buena. Vecina de Tio Ximo, muy buscada para el descanso y el buceo de superficie por la limpieza de sus fondos. Arena fina y cantos rodados. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03018','playa','Cala de Finestrat','Bandera Azul','Excelente. Única playa de este municipio, encajada en un entorno urbano denso compartido con Benidorm y Villajoyosa. Una concha de aguas tranquilas y familiares. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03039','playa','Playa de la Vila Joiosa (Centro)','Bandera Azul','Excelente. Espectacular playa urbana flanqueada por las icónicas y fotogénicas fachadas de casas de pescadores pintadas de colores vivos y un gran palmeral. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03039','playa','Playa de Paradís / Paraíso','Bandera Azul','Excelente. Playa semiurbana muy extensa rodeada de campings y vegetación mediterránea, oleaje moderado. Canto rodado en la orilla y arena dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03039','playa','Playa de Varadero / Estudiantes','Bandera Azul','Excelente. Situada cerca del puerto, muy frecuentada por jóvenes por sus chiringuitos de verano. Grava fina y cantos rodados. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03039','playa','Playa de La Caleta','Bandera Azul','Excelente. Cala apartada rodeada de acantilados bajos y un hotel integrado, aguas de color azul turquesa. Compuesta de cantos rodados. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03039','playa','Playa de Bol Nou','Bandera Azul','Excelente. Preciosa cala cerrada por un gran cortado de piedra caliza, aguas muy limpias que ganan profundidad rápidamente. Arena gruesa y cantos rodados. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03039','playa','Playa del Torres',NULL,'Muy buena. Amplia playa natural rodeada de un gran pinar y eucaliptos, con restos de una torre funeraria romana anexa. Compuesta por piedras y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03039','playa','Playa del Racó Conill',NULL,'Excelente. Célebre cala naturista completamente virgen escondida entre acantilados y pinos, fondos de roca excelentes para snorkel. Compuesta de piedra y roca. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03015','playa','Playa de Muchavista','Bandera Azul','Excelente. Inmenso arenal de más de 3 km de longitud que forma una sola pieza con la playa de San Juan de Alicante. Paseo marítimo moderno con tranvía integrado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03015','playa','Playa del Carrer la Mar','Bandera Azul','Excelente. Playa urbana principal del municipio, situada en el antiguo barrio de pescadores, con aguas muy tranquilas e ideales para niños. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03015','playa','Playa de la Almadraba (El Campello)',NULL,'Muy buena. Pequeña playa residencial contigua al yacimiento arqueológico de los Baños de la Reina (piscifactorías romanas talladas en la roca). Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03015','playa','Cala Lanuza',NULL,'Muy buena. Cala en forma de concha situada en la zona norte del municipio, ambiente residencial muy tranquilo. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03015','playa','Cala del Cuartel',NULL,'Buena. Espacio rústico y natural protegido donde se ubica una playa para perros. Compuesta de cantos rodados y grava. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03003','playa','Playa de San Juan','Bandera Azul','Excelente. El arenal estrella de la ciudad; kilométrico, inmensamente ancho y dotado de todo tipo de canchas deportivas, restaurantes y servicios turísticos de primer nivel. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03003','playa','Playa del Postiguet','Bandera Azul','Excelente. Playa urbana icónica situada en el corazón de Alicante, justo a los pies del Castillo de Santa Bárbara y junto al paseo de la Explanada. Aguas muy tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03003','playa','Playa de Urbanova / Saladares','Bandera Azul','Excelente. Gran playa situada al sur de la ciudad, en un entorno residencial tranquilo rodeado de un cordón dunar restaurado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03003','playa','Playa de la Albufereta','Bandera Azul','Muy buena. Playa resguardada en una pequeña bahía al norte de la ciudad, de aguas muy mansas y ligada a los orígenes romanos de Alicante. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03003','playa','Playa de la Almadraba (Alicante)',NULL,'Muy buena. Cala residencial pequeña y muy tranquila, sin apenas oleaje, ideal para contemplar puestas de sol. Arena fina y rocas oscuras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03003','playa','Playa de Agua Amarga',NULL,'Buena. La playa canina adaptada oficial de la ciudad, con servicios específicos para mascotas en verano. Arena gruesa y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03003','playa','Playa de la Isla de Tabarca',NULL,'Excelente. Situada en la única isla habitada de la Comunidad Valenciana (declarada Reserva Marina Nacional). Aguas hipertransparentes repletas de fauna marina. Arena gruesa, grava y cantos rodados. No tiene Bandera Azul (protección medioambiental integrada). [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03016','playa','Playa de El Altet','Bandera Azul','Excelente. Impresionante playa virgen dotada de un complejo dunar inmenso y de alto valor ecológico, sin construcciones cercanas. Arena blanca y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03016','playa','Playa de Los Arenales del Sol','Bandera Azul','Excelente. Amplia playa semiurbana muy popular, conectada con pasarelas de madera sobre las dunas para proteger el entorno. Arena dorada y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03016','playa','Playa del Carabassí',NULL,'Excelente. Gran espacio natural virgen que combina dunas fósiles, pinares y dunas móviles, muy valorada para el nudismo y el relax. Arena dorada y fina. No tiene Bandera Azul (por política de conservación natural estricta).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03016','playa','Playa de La Marina','Bandera Azul','Excelente. Situada en un entorno rodeado de un espeso pinar centenario, cuenta con un camping de gran categoría y excelentes servicios. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03016','playa','Playa de Les Pesqueres-El Rebollo','Bandera Azul','Excelente. Continuación salvaje de La Marina, con un nivel de ocupación bajo y dunas vírgenes espectaculares. Arena blanca y fina. Sí tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03035','playa','Playa de Llevant (Santa Pola)','Bandera Azul','Excelente. Playa urbana principal muy céntrica y dotada de todo tipo de comodidades e infraestructuras. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03035','playa','Playa de Varadero','Bandera Azul','Excelente. Ubicada en la zona residencial este, muy popular para pasear y de ambiente familiar excelente. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03035','playa','Playa de Tamarit',NULL,'Muy buena. Gran playa situada junto a las Salinas de Santa Pola, de aguas extremadamente tranquilas y poco profundas, muy buscada para el kitesurf. Arena fina y oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03035','playa','Playa Lisa',NULL,'Muy buena. Muy ancha y de escasísima profundidad (hay que caminar decenas de metros para que cubra), ideal para niños pequeños. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03035','playa','Calas de Santiago Bernabéu','Bandera Azul','Excelente. Sucesión de calas artificiales protegidas por espigones cruzados que retienen la arena y garantizan un baño sin olas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03035','playa','Calas del Cuartel (Calas del Este)',NULL,'Muy buena. Pequeñas calas naturales de roca situadas bajo el cabo de Santa Pola, idóneas para el snorkel por sus fondos rocosos. Arena fina y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03020','playa','Playa de la Roqueta','Bandera Azul','Excelente. Playa urbana muy céntrica y ancha que cuenta con accesos excelentes y aguas de gran calidad. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03020','playa','Playa de Centre (Guardamar)','Bandera Azul','Excelente. Bordeada por el paseo marítimo principal y muy cercana al famoso parque de Alfonso XIII (las dunas de Guardamar). Arena dorada finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03020','playa','Playa de El Moncayo','Bandera Azul','Excelente. Impresionante arenal semiurbano rodeado de dunas salvajes de gran extensión y arenas calientes. Arena dorada finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03020','playa','Playa de Los Tusales',NULL,'Excelente. Playa completamente virgen y nudista situada al norte de la desembocadura del río Segura, rodeada de un pinar e indómita. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03020','playa','Playa de Los Viveros',NULL,'Excelente. Playa salvaje flanqueada por las dunas vivas y pinos plantados a principios del siglo XX para frenar el avance de la arena sobre el pueblo. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03020','playa','Playa de Les Ortigues',NULL,'Excelente. Kilométrica playa virgen que conecta con el término municipal de Torrevieja, nula edificación. Arena blanca y finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03038','playa','Playa de La Mata','Bandera Azul','Excelente. El arenal más extenso de Torrevieja, con más de 2 km de longitud, flanqueado por un gran paseo de madera y dunas naturales. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03038','playa','Playa de Los Locos','Bandera Azul','Excelente. Playa urbana muy concurrida situada al norte del casco urbano, de aguas tranquilas y oleaje moderado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03038','playa','Playa del Cura','Bandera Azul','Excelente. La playa más céntrica e integrada en la ciudad, rodeada de un paseo marítimo repleto de restaurantes y comercios. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03038','playa','Playa de Los Náufragos','Bandera Azul','Excelente. Situada al sur del puerto pesquero y de la zona de explotación de sal, muy ancha y con un palmeral sobre la arena. Arena fina y dorada con tonos oscuros. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03038','playa','Cala Piteras','Bandera Azul','Excelente. Pequeña zona de baño situada en el límite sur, muy valorada para el snorkel debido a sus praderas de posidonia oceánica. Arena fina y roca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03038','playa','Calas de Torrevieja (Cala Ferris)',NULL,'Muy buena. Precioso rincón natural rodeado de palmeras cocoteras y pequeñas dunas, aguas cristalinas. Compuesta de arena fina y plataformas de roca. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03027','playa','Playa de Punta Prima','Bandera Azul','Excelente. Playa semiurbana que cuenta con un singular ascensor en el acantilado para facilitar el acceso a personas con movilidad reducida. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03027','playa','Playa de La Caleta (Cabo Roig)','Bandera Azul','Excelente. Resguardada al abrigo del Cabo Roig, de aguas hipertransparentes y muy protegida de los vientos dominantes. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03027','playa','Playa de Cala Capitán','Bandera Azul','Excelente. Playa muy singular dividida en dos zonas por una pequeña isla (Isla de la Estaca) unida por una lengua de arena. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03027','playa','Playa Flamenca (Cala Estaca / Cala Mosca)','Bandera Azul','Excelente. Playas cuidadas de carácter residencial con paseos peatonales modernos e infraestructuras excelentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03027','playa','Playa de Campoamor (Aguamarina / Barranco Rubio)','Bandera Azul','Excelente. Playas de gran anchura flanqueadas por urbanizaciones exclusivas y puertos deportivos de recreo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03027','playa','Playa de Mil Palmeras','Bandera Azul','Excelente. Compartida con Pilar de la Horadada, un arenal amplísimo con un nivel de limpieza y servicios óptimo. Arena dorada finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03902','playa','Playa de Mil Palmeras (Pilar)','Bandera Azul','Excelente. El centro turístico costero del municipio, con amplias zonas recreativas y un ambiente familiar inmejorable. Arena dorada finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03902','playa','Playa de Las Higuericas','Bandera Azul','Excelente. Muy famosa en la provincia, cuenta con pasarelas de madera sobre dunas bajas y es muy frecuentada por jóvenes y familias. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03902','playa','Playa de El Conde','Bandera Azul','Excelente. Situada al pie de una antigua torre vigía del siglo XVI que le da un carácter patrimonial único. Aguas someras. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03902','playa','Playa de Jesuitas','Bandera Azul','Excelente. Amplio arenal en forma de ensenada resguardada por pequeños acantilados de roca arcillosa. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('03902','playa','Playa de El Mojón',NULL,'Muy buena. Limítrofe con la Región de Murcia, playa abierta de ambiente tranquilo y tradicional. Arena fina mezclada con algo de grava gruesa. No tiene Bandera Azul. Sigo de forma continua con la Región de Murcia (Costa Cálida) en el siguiente bloque. Las respuestas de la IA pueden contener errores. Más información 27 sitios','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30036','playa','Playa de El Mojón (Murcia)',NULL,'Muy buena. Continuación natural de la costa alicantina, delimitada por un paseo marítimo de madera que bordea el parque natural. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30036','playa','Playa de Las Salinas',NULL,'Excelente. Situada dentro del Parque Natural de las Salinas y Arenales de San Pedro. Un entorno virgen protegido frente al mar Mediterráneo con dunas salvajes. Arena fina y blanca. No tiene Bandera Azul por restricciones de conservación.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30036','playa','Playa de La Llana (Barraca Quemada / Punta de Algas)',NULL,'Excelente. Kilométrica playa virgen en mar abierto accesible únicamente a pie, flanqueada por las dunas y las encañizadas tradicionales. Arena blanca finísima. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30036','playa','Playa de Villananitos',NULL,'Muy buena. Situada en el interior del Mar Menor, colindante con la famosa zona de lodos terapéuticos de Las Charcas. Aguas totalmente mansas, calientes y de muy escasa profundidad. Arena fina y grisácea. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30036','playa','Playa de La Mota',NULL,'Buena. Estrecha franja de arena en el Mar Menor que separa la laguna de los estanques salineros, muy familiar. Arena fina y oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30035','playa','Playa de La Castillica',NULL,'Buena. Playa residencial situada en Santiago de la Ribera (Mar Menor), de ambiente muy tradicional y con pantalanes de madera. Arena fina y gris. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30035','playa','Playa de Barnuevo',NULL,'Muy buena. El centro neurálgico y turístico de Santiago de la Ribera, muy animada y con todo tipo de servicios turísticos a pie de paseo. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30035','playa','Playa de El Pescador',NULL,'Muy buena. Playa familiar de aguas tranquilas y someras, ideal para niños pequeños. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30035','playa','Playa de El Pedrucho (La Manga)',NULL,'Muy buena. Situada en el kilómetro 8 de La Manga, en la vertiente del mar Mediterráneo (Mar Mayor). Amplia, abierta y con oleaje moderado. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30035','playa','Playa de Mistral (La Manga)',NULL,'Buena. Ubicada en el Mar Menor, junto al puerto deportivo Tomás Maestre, de aguas muy tranquilas y protegidas. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30035','playa','Playa del Estacio',NULL,'Muy buena. Gran playa de mar abierto situada al norte del canal del Estacio, zona muy espaciosa. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30902','playa','Playa de Las Palmeras','Bandera Azul','Excelente. Playa urbana totalmente regenerada con un paseo marítimo kilométrico repleto de palmeras monumentales e infraestructuras de accesibilidad. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30902','playa','Playa de Los Narejos','Bandera Azul','Excelente. Muy amplia y con un centro de alto rendimiento de deportes náuticos anexo, vientos excelentes para el aprendizaje de vela. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30902','playa','Playa de El Espejo',NULL,'Muy buena. Situada frente al centro urbano del municipio, presidida por el monumento al pescador. Aguas mansas y someras. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30902','playa','Playa de Manzanares',NULL,'Muy buena. Semicéntrica, flanqueada por antiguas e históricas casas de veraneo de principios del siglo XX con balnearios de madera sobre el agua. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30902','playa','Playa de Carrión',NULL,'Buena. Continuación de Manzanares, ambiente marcadamente familiar y residencial local. Arena fina y gris. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30902','playa','Playa de La Concha (Los Alcázares)',NULL,'Buena. Situada junto al club náutico, la más resguardada de los vientos del norte. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Playa de Cala Cortina','Bandera Azul','Excelente. La playa urbana de la ciudad de Cartagena, situada en una cala protegida por un anfiteatro de roca artificial y acantilados naturales. Aguas hipertransparentes ideales para el snorkel. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Playa de Calblanque (Playa Larga / San Ginés)',NULL,'Excelente. Ubicada en el Parque Natural de Calblanque. Una de las joyas vírgenes del Mediterráneo español. Playas salvajes rodeadas de dunas fósiles, pinares y cerros abruptos. Arena dorada finísima. No tiene Bandera Azul (protección medioambiental estricta y sin servicios).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Playa de Islas Menores','Bandera Azul','Excelente. Situada en el Mar Menor, de ambiente residencial muy cuidado y dotada de un gran paseo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Playa de Mar de Cristal','Bandera Azul','Excelente. Famosa por la altísima calidad y limpieza de sus aguas dentro del entorno del Mar Menor, muy familiar. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Playa de San Ginés (La Azohía)','Bandera Azul','Excelente. Hermosa playa pesquera tradicional situada en la bahía de Mazarrón, resguardada por el cabo Tiñoso. Aguas limpias y tranquilas. Arena fina y cantos rodados. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Playa de El Portús',NULL,'Muy buena. Cala semiurbana dividida en dos sectores, albergando uno de los campings nudistas más antiguos y consolidados de la región. Arena fina y piedras. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Playa de Cabo de Palos (Playa de Levante)',NULL,'Excelente. Enorme arenal que conecta el pueblo pesquero con el inicio de La Manga, mar abierto con oleaje. Arena dorada de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Cala Reona',NULL,'Excelente. Cala escarpada que marca el inicio del espacio protegido de Calblanque, fondos marinos espectaculares integrados en la Reserva Marina de Cabo de Palos. Grava, cantos rodados y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Playa de Galúa (La Manga)','Bandera Azul','Excelente. Ubicada en el mar Mediterráneo, en una de las zonas más hoteleras y activas de La Manga. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30016','playa','Playa de La Barón (La Manga)',NULL,'Muy buena. Situada en la vertiente del Mar Menor, aguas en calma absoluta y muy cálidas. Arena fina. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30026','playa','Playa de Bahía','Bandera Azul','Excelente. Hermosa playa con forma de concha perfecta, muy resguardada del oleaje por los cabos naturales, aguas mansas e ideales para niños. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30026','playa','Playa de Bolnuevo',NULL,'Excelente. Kilométrica playa semiurbana famosa por estar situada justo enfrente de "Las Gredas de Bolnuevo" (formaciones rocosas erosionadas por el viento con formas caprichosas). Arena dorada de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30026','playa','Playa del Castellar','Bandera Azul','Excelente. Gran playa urbana que recorre el paseo marítimo del Puerto de Mazarrón, equipada con todo tipo de servicios náuticos y recreativos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30026','playa','Playa de Nares','Bandera Azul','Excelente. Continuación de El Castellar, de ambiente más residencial y baja densidad de bañistas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30026','playa','Playa de Rihuete','Bandera Azul','Excelente. Situada en el extremo oriental del núcleo urbano, muy concurrida y con una oferta gastronómica muy amplia a pie de arena. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30026','playa','Playa de Percheles',NULL,'Excelente. Joya natural del municipio; una playa paradisíaca en forma de herradura rodeada de un gran palmeral y dunas bajas. Arena fina y dorada. No tiene Bandera Azul (entorno rústico protegido).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30026','playa','Cala de Leño',NULL,'Buena. Cala natural e inhóspita de tradición naturista, rodeada de acantilados áridos. Compuesta de cantos rodados y roca. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30003','playa','Playa de La Carolina','Bandera Azul','Excelente. Catalogada como Paisaje Protegido. Una playa virgen espectacular que mira hacia el castillo de Águilas, con dunas de arena fina y dorada y aguas cristalinas poco profundas. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30003','playa','Playa de Las Delicias','Bandera Azul','Excelente. Gran playa urbana del centro del municipio, flanqueada por un paseo marítimo ajardinado y el puerto deportivo. Arena fina y grisácea. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30003','playa','Playa de Calarreona','Bandera Azul','Excelente. Ubicada en una gran ensenada natural, de aguas muy limpias y someras, ideal para familias y deportes de remo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30003','playa','Playa de Poniente (Águilas)','Bandera Azul','Excelente. Extensa playa urbana que recorre la bahía sur de la ciudad, con pendientes de entrada al agua muy suaves. Arena fina mezclada con canto rodado fino. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30003','playa','Playa de Matalentisco',NULL,'Muy buena. Cala semiurbana virgen encajada en la desembocadura de una rambla, muy tranquila. Arena fina y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30003','playa','Playa de Los Cocedores (Límite con Almería)',NULL,'Excelente. Preciosa cala semicircular encajada entre acantilados de roca arenisca amarilla repletos de antiguas cuevas. Aguas totalmente mansas que simulan una piscina natural. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('30003','playa','Playa de Calabardina',NULL,'Excelente. Situada en la pedanía del mismo nombre, bajo el imponente cabo Cope. Aguas cristalinas en calma absoluta, meca regional del submarinismo. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04021','playa','Playa de San Juan de los Terreros','Bandera Azul','Excelente. Playa urbana principal del núcleo costero, muy cómoda, de aguas cristalinas poco profundas e ideal para familias. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04021','playa','Playa de Mar Serena','Bandera Azul','Excelente. Debe su nombre a la extrema tranquilidad de sus aguas, protegidas por arrecifes naturales de roca. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04021','playa','Playa de Mar Rabiosa','Bandera Azul','Excelente. Separada de Mar Serena por un pichacho de roca accesible a pie, más abierta al mar abierto y con oleaje moderado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04021','playa','Playa de Calipso','Bandera Azul','Excelente. Cala pequeña de ambiente residencial muy cuidado y aguas transparentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04021','playa','Cala Cerrada / Los Cocedores (Parte almeriense)',NULL,'Excelente. Compartida administrativamente con Águilas, entorno kárstico espectacular de aguas mansas. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04035','playa','Playa de Palomares',NULL,'Muy buena. Extenso arenal abierto flanqueado por una gran pinada litoral, ambiente muy tranquilo. Arena oscura de grano medio y grava fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04035','playa','Playa de Villaricos',NULL,'Muy buena. Situada junto al pueblo pesquero, rodeada de fondos marinos rocosos excepcionales para el buceo. Compuesta por grava y cantos rodados oscuros. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04035','playa','Cala Panizo',NULL,'Excelente. Hermosa cala resguardada entre acantilados bajos, muy apartada y de aguas hipertransparentes. Arena fina y dorada (escasas en la zona). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04035','playa','Playa de Pozo del Esparto',NULL,'Muy buena. Playa lineal frente a un paseo marítimo residencial de casas bajas tradicionales. Arena gruesa y grava fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04029','playa','Playa de El Playazo (Vera)','Bandera Azul','Excelente. Uno de los centros de naturismo y nudismo más famosos a nivel mundial, con hoteles y urbanizaciones completamente adaptados. Un arenal inmenso de más de 2 kilómetros de largo y gran anchura. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04029','playa','Playa de Las Marinas-Bolaga','Bandera Azul','Excelente. El tramo más residencial y familiar al sur del municipio, dotado de un gran paseo ajardinado y servicios excelentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04029','playa','Playa de Puerto Rey',NULL,'Muy buena. Situada en la desembocadura de la laguna del río Antas (espacio natural de avistamiento de aves). Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04011','playa','Playa de Garrucha / Las Escobillas','Bandera Azul','Excelente. La gran playa urbana del municipio, protegida de forma artificial por un colosal espigón que frena las corrientes del norte. Paseo marítimo monumental ("el malecón"). Arena dorada de grano grueso. Sí tiene Bandera Azul. Sigo de forma continua con los municipios de Mojácar, Níjar (Cabo de Gata) y el resto de la provincia de Almería. Las respuestas de la IA pueden contener errores. Más información 4 sitios','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04011','playa','Playas en Murcia',NULL,'un paraíso por descubrir entre mar y sol 23 sept 2025 — La Playa de La Llana, situada en San Pedro del Pinatar, es un auténtico paraíso natural que destaca por su belleza y tranquilidad. Minube','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04016','playa','Playa de Marina de la Torre','Bandera Azul','Excelente. Situada frente a un palacio histórico y un campo de golf, dotada de excelentes servicios hoteleros. Arena dorada de grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04016','playa','Playa de El Cantal','Bandera Azul','Excelente. La playa más popular y con más ambiente del municipio, repleta de chiringuitos tradicionales y zonas de ocio a pie de arena. Arena fina y grava dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04016','playa','Playa de Lance Nuevo','Bandera Azul','Excelente. Amplio arenal urbano muy cuidado, dotado de zonas recreativas y fácil aparcamiento. Arena dorada de grano medio y grava. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04016','playa','Playa de Venta del Bancal','Bandera Azul','Excelente. Marca el inicio del paseo marítimo en su zona sur, protegida por un espigón artificial que calma las corrientes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04016','playa','Playa de Macenas',NULL,'Muy buena. Playa natural presidida por una imponente torre de defensa del siglo XVIII (Castillo de Macenas), entorno muy tranquilo. Arena oscura y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04016','playa','Playa de los Granatillos',NULL,'Buena. Cala salvaje totalmente aislada, ideal para desconectar y practicar el snorkel en fondos de roca. Compuesta por piedras y arena gruesa oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04006','playa','Playa de los Muertos',NULL,'Excelente. Catalogada de forma sistemática entre las mejores playas de España. Un monumental acantilado que abraza un mar azul turquesa hipertransparente de gran profundidad. Acceso a pie por un sendero empinado de 15 minutos. Compuesta por piedrecitas blancas finas (grava pulida) que no se pegan al cuerpo. No tiene Bandera Azul (entorno virgen protegido).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04006','playa','Playa de El Ancón','Bandera Azul','Excelente. Gran playa urbana que recorre el paseo marítimo del pueblo, con un nivel de servicios e infraestructuras óptimo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04006','playa','Playa de Las Marinicas','Bandera Azul','Excelente. Situada entre el puerto pesquero y la central térmica, aguas en calma absoluta simulando una piscina natural, ideal para niños pequeños. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04006','playa','Playa de Los Barquicos','Bandera Azul','Excelente. Continuación urbana de El Ancón, muy familiar y de aguas limpias y transparentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04006','playa','Playa de El Algarrobico',NULL,'Buena. Famosa por el polémico hotel edificado en su linde. Playa de mar abierto, aislada y de carácter natural. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04017','playa','Playa de los Genoveses',NULL,'Excelente. Bahía natural virgen de una belleza desértica sobregogedora, rodeada de chumberas y dunas de arena fina. Acceso restringido en verano mediante autobuses o caminos de tierra. Arena dorada y finísima. No tiene Bandera Azul (máxima protección del Parque Natural).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04017','playa','Playa de Mónsul',NULL,'Excelente. Icono cinematográfico internacional (escenario de Indiana Jones). Famosa por su gran roca de lava volcánica ("la peineta") en mitad de la orilla y su duna rampante. Arena oscura finísima de origen volcánico. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04017','playa','Playa de Las Negras',NULL,'Excelente. Situada en el pintoresco núcleo urbano del mismo nombre, flanqueada por el Cerro Negro (un acantilado volcánico espectacular). Aguas muy limpias. Compuesta por cantos rodados oscuros y pasillos de arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04017','playa','Cala de Enmedio',NULL,'Excelente. Joya oculta del parque natural, accesible únicamente a pie desde Agua Amarga o Cala Plomo. Rodeada de dunas fósiles de color blanco puro que contrastan con el azul turquesa del mar. Arena dorada finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04017','playa','Playa de Agua Amarga','Bandera Azul','Excelente. Playa urbana del núcleo residencial, muy cómoda, familiar y resguardada de los vientos por colinas calcáreas perforadas por antiguas cuevas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04017','playa','Playa de San José','Bandera Azul','Excelente. El arenal principal del pueblo de San José, muy concurrida, dotada de todo tipo de servicios turísticos y aguas tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04017','playa','Cala del Plomo',NULL,'Excelente. Cala virgen muy amplia a la que se accede por una pista de tierra de varios kilómetros, rodeada de antiguas huertas y dunas fósiles. Arena fina y cantos rodados en la orilla. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04017','playa','Cala San Pedro',NULL,'Excelente. Famosa por albergar una comunidad hippie permanente y las ruinas de un castillo medieval. Cuenta con un manantial de agua dulce natural y aguas caribeñas. Acceso a pie de una hora o en lancha rápida. Arena blanca y finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04017','playa','Playa de El Playazo (Rodalquilar)',NULL,'Excelente. Impresionante playa flanqueada por el Castillo de San Ramón, oasis de palmeras y acantilados dorados. Aguas someras y tranquilas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04004','playa','Playa de San Miguel / Zapillo','Bandera Azul','Excelente. La gran playa urbana de la ciudad, recorrida por un paseo marítimo kilométrico repleto de vida. Muy ancha y dotada de todos los servicios. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04004','playa','Playa de Nueva Almería','Bandera Azul','Excelente. Continuación hacia el este del Zapillo, zona residencial más tranquila con espacios deportivos y accesibilidad universal. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04004','playa','Playa de Las Salinas (Cabo de Gata)',NULL,'Excelente. El arenal más extenso del municipio (varios kilómetros de longitud lineal en mar abierto), presidido por la icónica iglesia de las Salinas. Arena fina y dorada con fuerte viento por las tardes. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04004','playa','Playa de San Telmo',NULL,'Buena. Pequeña cala situada bajo los acantilados de la carretera hacia Aguadulce, de carácter rocoso y aguas limpias. Arena gruesa y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04004','playa','Playa de El Alquián',NULL,'Buena. Situada cerca del aeropuerto, playa abierta de mar bravo y baja ocupación turística. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04004','playa','Playa de Costacabana',NULL,'Buena. Zona residencial periférica muy afectada por la erosión costera, protegida por espigones de piedra rectos. Arena dorada y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04004','playa','Playa de Retamar',NULL,'Muy buena. Gran playa que da servicio a la urbanización residencial del mismo nombre, equipada con paseo de madera y dunas recuperadas. Arena fina y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04004','playa','Playa de El Toyo',NULL,'Muy buena. Diseñada para los Juegos Mediterráneos, cuenta con una gran plaza mirador y un entorno hotelero sostenible. Arena gruesa y grava fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04004','playa','Playa de Torregarcía',NULL,'Excelente. Marca el inicio del Parque Natural de Cabo de Gata, alberga una ermita histórica y los restos de una factoría romana de salazón. Entorno virgen. Arena fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04023','playa','Playa de Aguadulce','Bandera Azul','Excelente. Una de las playas más concurridas de la provincia, resguardada de las corrientes por el puerto deportivo, con aguas mansas y templadas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04023','playa','Playa de la Romanilla','Bandera Azul','Excelente. Gran playa urbana situada frente al casco urbano principal, muy ancha y con un palmeral monumental sobre el paseo marítimo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04023','playa','Playa de la Bajadilla','Bandera Azul','Excelente. Conecta el puerto pesquero con las zonas hoteleras, con excelentes infraestructuras y un nivel de limpieza óptimo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04023','playa','Playa de Urbanización Roquetas','Bandera Azul','Excelente. Enorme arenal que flanquea la gran zona hotelera del municipio, equipada con todo tipo de ocio náutico y servicios públicos. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04023','playa','Playa de Serena','Bandera Azul','Excelente. Situada junto al campo de golf, destaca por su tranquilidad y su gran anchura, libre de aglomeraciones asfixiantes. Arena blanca y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04023','playa','Playa de Las Salinas (Roquetas)','Bandera Azul','Excelente. Ubicada en la zona norte, sobre antiguas salinas ricas en avistamiento de flamencos, mar abierto de gran calidad de aguas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04023','playa','Playa de Cerrillos',NULL,'Excelente. Playa completamente virgen e infinita integrada en el Paraje Natural de Punta EntinasSabinar, dunas salvajes y nula edificación. Arena fina y dorada. No tiene Bandera Azul (protección ecológica).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04008','playa','Playa de Almerimar (Poniente y Levante)','Bandera Azul','Excelente. Divididas por el gran puerto deportivo de Almerimar, cuentan con un diseño urbano moderno, campos de golf y escuelas de windsurf internacionales. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04008','playa','Playa de Balerma','Bandera Azul','Excelente. Playa urbana ligada a la pedanía marinera tradicional, presidida por una torre vigía medieval y con un ambiente muy familiar. Arena dorada de grano grueso y grava. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04008','playa','Playa de San Miguel (El Ejido)','Bandera Azul','Excelente. Kilométrico arenal lineal que bordea la carretera costera, de baja densidad de ocupación y aguas limpias abiertas. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04008','playa','Playa de Punta Entinas (El Ejido)',NULL,'Excelente. El extremo occidental del paraje natural protegido, dunas indómitas y lagunas salinas salvajes. Un paraíso de paz. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04904','playa','Playa de Balanegra','Bandera Azul','Excelente. Municipio independiente de gran tradición agrícola y marinera, cuenta con un paseo marítimo lineal muy cuidado y familiar. Arena dorada de grano grueso y grava fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04002','playa','Playa de San Nicolás','Bandera Azul','Excelente. La playa urbana por excelencia de Adra, situada junto al puerto y dotada de un paseo marítimo animado con zonas deportivas y juegos. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04002','playa','Playa de Poniente (Adra)','Bandera Azul','Excelente. Muy espaciosa y ancha, ideal para largos paseos, de aguas limpias y oleaje moderado. Arena oscura de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04002','playa','Playa de El Censo','Bandera Azul','Excelente. Conecta de forma peatonal las playas urbanas, galardonada de forma continua por su accesibilidad e infraestructuras. Arena oscura y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04002','playa','Playa de La Juana',NULL,'Buena. Playa natural aislada de carácter rústico situada al este del municipio, baja ocupación. Grava y arena oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('04002','playa','Playa de Guainos',NULL,'Muy buena. Entorno rural de casas bajas marineras tradicionales, aguas muy transparentes. Arena gruesa y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
