INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('19002','playa','Playa de La Herradura','Bandera Azul','Excelente. Impresionante bahía natural flanqueada por los imponentes acantilados de MaroCerro Gordo, un paraíso absoluto para el buceo y el snorkel. Grava fina y arena oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('19002','playa','Playa de San Cristóbal','Bandera Azul','Excelente. Enorme playa urbana muy concurrida, presidida en un extremo por el monumento natural de los Peñones de San Cristóbal. Arena oscura de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
