INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('19002','playa','Playa de Calabajío',NULL,'Buena. Cala semiurbana resguardada por un frondoso parque botánico de palmeras. Arena oscura y grano grueso. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('19002','playa','Playa de Cabria',NULL,'Buena. Cala rústica encajada al final de un barranco, de ambiente tranquilo. Grava y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
