INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18173','playa','Playa de la Charca / Salomar',NULL,'Excelente. Gran playa urbana que ofrece una estampa espectacular con el pueblo blanco de Salobreña y su castillo árabe coronando la colina al fondo. Arena oscura y grava fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18173','playa','Playa de la Guardia',NULL,'Muy buena. Separada de La Charca por el Peñón de Salobreña, rodeada de campos de cultivo tradicionales y ambiente más tranquilo. Arena oscura y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18173','playa','Playa del Cambrón',NULL,'Buena. Cala salvaje totalmente aislada y encajonada bajo acantilados escarpados, nula ocupación turística. Compuesta íntegramente por piedra y roca viva. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18173','playa','Playa del Molino',NULL,'Buena. Continuación natural de la zona costera hacia el oeste, de carácter rústico. Arena oscura de grano medio. No tiene Bandera Azul. [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18140','playa','Playa de Calahonda (Motril)','Bandera Azul','Excelente. Espectacular concha resguardada de aguas hipertransparentes de color azul intenso, ganando gran profundidad a pocos pasos. Arena gruesa y grava fina y limpia. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18140','playa','Playa de Poniente (Motril)','Bandera Azul','Excelente. Enorme playa urbana dotada de un paseo marítimo monumental, carril bici y una amplísima zona de chiringuitos y ocio. Arena oscura y grava fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18140','playa','Playa de Granada','Bandera Azul','Excelente. Zona residencial exclusiva flanqueada por campos de golf, muy ancha y espaciosa, muy buscada para el kitesurf por sus vientos térmicos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
