INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18140','playa','Playa de las Azucenas',NULL,'Buena. Playa natural situada junto al puerto comercial, catalogada en tramos para la protección de la flora litoral y el acceso con perros. Arena oscura y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18140','playa','Cala de la Joya',NULL,'Excelente. Espectacular cala virgen oculta bajo acantilados salvajes, de tradición nudista y acceso peatonal por escaleras escarpadas. Compuesta por piedras y arena gruesa. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18916','playa','Playa de Torrenueva','Bandera Azul','Excelente. Playa urbana principal de este municipio independiente, totalmente equipada, con un paseo marítimo moderno y el famoso puente colgante de Jolúcar sobre los acantilados. Arena oscura y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18916','playa','Playa de La Pelucona / El Cañón','Bandera Azul','Excelente. Continuación del arenal hacia el este, uniendo el casco urbano con los espacios naturales. Arena gruesa y dorada. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90038','playa','Playa de Castell de Ferro',NULL,'Muy buena. Playa urbana principal del núcleo marinero, de aguas limpias y profundas, dominada por el castillo medieval en el monte. Grava y cantos rodados oscuros. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90038','playa','Playa de Cambriles',NULL,'Muy buena. Compartida con el municipio de Lújar, de carácter semiurbano y ambiente familiar muy tranquilo. Grava fina y arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90038','playa','Playa del Sotillo',NULL,'Buena. Amplio tramo lineal de costa abierta frente a zonas agrícolas y residenciales de baja densidad. Grava y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90038','playa','Playa de Rijana',NULL,'Excelente. Una de las joyas paisajísticas de la provincia; cala virgen encajada en la autovía costera, con las ruinas de una torre vigía y arrecifes de roca que emergen del mar turquesa. Compuesta por piedras y grava fina. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18124','playa','Playa de Cambriles (Parte occidental)',NULL,'Muy buena. Pequeña franja playera asignada a este término rural, perfectamente integrada en el paseo y servicios continuos de Castell de Ferro. Grava y arena oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18170','playa','Playa de Casarones',NULL,'Buena. Pequeño núcleo costero tradicional de pescadores, ambiente familiar muy local y nula masificación. Compuesta por cantos rodados y grava gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18170','playa','Playa de El Lance',NULL,'Buena. Franja de costa lineal estrecha junto a la carretera nacional, aguas limpias de mar abierto. Grava y piedra. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18162','playa','Playa de La Mamola',NULL,'Muy buena. Playa urbana defendida por varios espigones de piedra en forma de "T" que calman por completo el oleaje del mar de Alborán. Paseo marítimo muy cuidado. Arena oscura de grano grueso y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18162','playa','Playa de Guarea',NULL,'Buena. Cala completamente natural aislada de los núcleos, frecuentada por pescadores de caña. Compuesta enteramente de piedras y cantos rodados. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('18177','playa','Playa de Melicena',NULL,'Muy buena. Preciosa playa rural situada al pie del peñón de Melicena y su torre vigía, ambiente tranquilo y aguas muy transparentes. Grava fina y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
