INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90037','playa','Playa de La Rábita',NULL,'Muy buena. Gran playa urbana resguardada por espigones artificiales, con un paseo marítimo moderno y excelente oferta de restauración local. Arena oscura de grano grueso y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90037','playa','Playa de El Pozuelo',NULL,'Buena. Situada en el límite oriental con la provincia de Almería, entorno de carácter agrícola marcadamente tranquilo. Grava y arena oscura. No tiene Bandera Azul. Sigo de forma continua con la Provincia de Málaga (Costa del Sol). Las respuestas de la IA pueden contener errores. Más información 9 sitios','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90037','playa','Playa de la Guardia',NULL,'con una longitud de un kilómetro de largo y una anchura media de 25 metros, estamos ante una playa carente de... Hoteles.net Mostrar todo Has dicho: sigue','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29075','playa','Playa de Burriana','Bandera Azul','Excelente. La playa más famosa y concurrida de Nerja, rodeada de restaurantes y famosa por sus paellas a la leña, inmortalizada en la serie Verano Azul. Arena dorada de grano grueso. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29075','playa','Playa de Maro (Cala de Maro)',NULL,'Excelente. Espectacular cala virgen oculta bajo los acantilados de Maro-Cerro Gordo. Entorno de cascadas naturales que caen al mar, aguas hipertransparentes ideales para kayak y snorkel. Compuesta de arena gruesa y cantos rodados finos. No tiene Bandera Azul (protección medioambiental estricta). [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29075','playa','Playa de El Salón',NULL,'Muy buena. Pequeña y pintoresca cala urbana con antiguas casas de pescadores, situada justo a los pies del Balcón de Europa. Acceso peatonal en pendiente. Arena fina y oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29075','playa','Playa de Calahonda (Nerja)',NULL,'Excelente. Icono fotográfico de la localidad, situada bajo el Balcón de Europa, flanqueada por acantilados y grandes rocas. Arena fina y oscura. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29075','playa','Playa de Torrecilla',NULL,'Excelente. Playa urbana muy bien equipada con un paseo marítimo moderno al oeste del centro del municipio. Arena fina mezclada con algo de grava gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29075','playa','Playa de El Playazo (Nerja)',NULL,'Muy buena. El arenal más extenso y menos urbanizado del municipio, de carácter rural y con huertos tradicionales colindantes. Arena oscura de grano grueso y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29091','playa','Playa de Ferrara','Bandera Azul','Excelente. La playa urbana principal del municipio, muy amplia y dotada de un paseo marítimo animado con todo tipo de infraestructuras y accesos para movilidad reducida. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29091','playa','Playa de El Morche','Bandera Azul','Excelente. Gran arenal semiurbano con zonas residenciales de baja altura y un cordón dunar restaurado en algunas zonas. Aguas muy tranquilas y someras. Arena dorada y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29091','playa','Playa de las Dunas',NULL,'Muy buena. Espacio protegido que conserva el último complejo dunar de la Costa del Sol oriental. Arena fina y grisácea. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29091','playa','Playa del Peñoncillo',NULL,'Muy buena. Extensa playa lineal paralela a la carretera costera, de ambiente más tranquilo y con chiringuitos tradicionales. Arena oscura de grano grueso. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29091','playa','Playa de Calaceite',NULL,'Buena. Pequeña franja de costa bajo colinas escarpadas, de carácter rústico e ideal para el buceo. Grava, cantos rodados y arena oscura. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29094','playa','Playa de Torre del Mar','Bandera Azul','Excelente. Inmenso arenal urbano de más de 3 kilómetros de longitud dotado de un paseo marítimo colosal con pistas deportivas, zonas infantiles y carriles bici. Arena oscura de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29094','playa','Playa de Benajarafe','Bandera Azul','Excelente. Playa semiurbana muy amplia vinculada al núcleo residencial tradicional del mismo nombre. Ambiente marcadamente familiar. Arena oscura de grano fino. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29094','playa','Playa de Caleta de Vélez','Bandera Azul','Excelente. Situada junto al puerto pesquero y deportivo, muy resguardada del viento y de ambiente tranquilo. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29094','playa','Playa de Almayate',NULL,'Muy buena. Extensa playa totalmente virgen y aislada rodeada de campos de cultivo, con una zona nudista tradicional muy consolidada. Arena oscura y gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29094','playa','Playa de Lagos (Vélez-Málaga)',NULL,'Buena. Pequeña playa lineal en el límite oriental del municipio, ambiente residencial local de casas bajas. Compuesta por cantos rodados y grava gruesa. No tiene Bandera Azul. [1, 2, 3]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29082','playa','Playa de Cala del Moral','Bandera Azul','Excelente. Gran playa urbana situada en una ensenada protegida, conectada con el Rincón a través de los túneles peatonales del acantilado de El Cantal. Arena oscura y fina con grava. Sí tiene Bandera Azul. [1, 2, 3]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29082','playa','Playa de Rincón de la Victoria',NULL,'Muy buena. Amplio arenal que flanquea todo el centro urbano, con un paseo marítimo repleto de palmeras y chiringuitos tradicionales de espetos de sardinas. Arena oscura y fina. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29082','playa','Playa de Torre de Benagalbón',NULL,'Muy buena. Tramo costero residencial de carácter semiurbano, baja densidad de bañistas y espacios muy amplios. Arena oscura de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29067','playa','Playa de la Malagueta','Bandera Azul','Excelente. La playa urbana por excelencia de la capital malagueña, situada junto al muelle uno y el centro de la ciudad. Muy ancha y dotada de un icónico letrero de letras de arena y grandes palmerales. Arena oscura de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29067','playa','Playa de la Misericordia','Bandera Azul','Excelente. Inmenso arenal del sector oeste de la ciudad, presidido por las antiguas chimeneas industriales del siglo XIX. Muy espaciosa y con excelentes equipamientos. Arena oscura de grano fino. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29067','playa','Playa de Pedregalejo','Bandera Azul','Excelente. Antigua barriada tradicional de pescadores configurada por pequeñas calas circulares protegidas por espigones de piedra. Eje gastronómico de espetos y chiringuitos de la ciudad. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29067','playa','Playa de El Palo','Bandera Azul','Excelente. Continuación de Pedregalejo, con la misma estructura de calas artificiales seguras sin oleaje e idóneas para familias. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29067','playa','Playa de San Andrés','Bandera Azul','Muy buena. Situada junto al puerto comercial, muy céntrica y de fácil acceso urbano. Arena oscura de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29067','playa','Playa de Guadalmar',NULL,'Muy buena. Ubicada cerca del paraje natural de la desembocadura del río Guadalhorce y de la ruta de aproximación del aeropuerto. Cuenta con una zona nudista oficial. Arena oscura y fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29067','playa','Playa de El Candado',NULL,'Buena. Pequeña playa semiurbana situada junto al puerto deportivo del mismo nombre, de ambiente residencial tranquilo. Arena fina y grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29067','playa','Playa de los Baños del Carmen',NULL,'Pintoresca. Espacio histórico costero que alberga un antiguo balneario de principios del siglo XX. No destaca para el baño cómodo pero posee un enorme valor estético. Cantos rodados y roca. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29901','playa','Playa de los Álamos','Bandera Azul','Excelente. El arenal más joven y dinámico del municipio, famoso por sus chiringuitos musicales, festivales y la práctica de kitesurf y windsurf. Arena oscura y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29901','playa','Playa de Playamar',NULL,'Excelente. Amplia playa urbana flanqueada por grandes torres hoteleras, dotada de todo tipo de servicios náuticos y recreativos. Arena oscura de grano fino. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29901','playa','Playa de El Bajondillo',NULL,'Excelente. Integrada en el centro urbano principal de Torremolinos, accesible mediante escaleras históricas o ascensor municipal. Muy concurrida. Arena oscura de grano fino. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29901','playa','Playa de La Carihuela',NULL,'Excelente. Tradicional barrio marinero reconvertido en un inmenso arenal turístico internacional, célebre por sus restaurantes de pescaíto frito. Arena fina y oscura. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29025','playa','Playa de Fuente de la Salud','Bandera Azul','Excelente. Situada en el límite oriental del municipio, colindante con el multipremiado puerto deportivo Puerto Marina. Aguas muy tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29025','playa','Playa de Torrebermeja-Santa Ana','Bandera Azul','Excelente. Gran playa urbana dotada de un paseo marítimo moderno, zonas verdes de césped anexas a la arena y áreas deportivas. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29025','playa','Playa de Bil-Bil',NULL,'Excelente. Presidida por un castillo de estilo neoárabe de color rojo construido en los años 30 que hoy sirve de centro cultural. Arena fina y oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29025','playa','Playa de Arroyo de la Miel / Los Melilleros','Bandera Azul','Excelente. Una de las más populares y queridas de la localidad, dividida por un saliente rocoso natural, ambiente muy familiar. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29025','playa','Playa de Carvajal (Benalmádena)',NULL,'Muy buena. Extenso arenal compartido con Fuengirola, rodeado de chiringuitos y una gran oferta hotelera. Arena oscura de grano grueso. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29025','playa','Playa de Benalnatura',NULL,'Excelente. Una de las playas nudistas pioneras y más consolidadas de la Costa del Sol. Una pequeña cala oculta bajo acantilados verdes y densa vegetación, con un ambiente muy cuidado. Arena gruesa y piedra fina. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29054','playa','Playa de los Boliches-Las Gaviotas','Bandera Azul','Excelente. Un referente de accesibilidad universal e infraestructuras turísticas a nivel nacional. Muy ancha, perfectamente cuidada y paralela al paseo marítimo principal. Arena dorada de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29054','playa','Playa de Carvajal (Fuengirola)','Bandera Azul','Excelente. El tramo oriental del municipio, muy amplio, dotada de una inmensa cantidad de servicios lúdicos y de ocio familiar. Arena dorada y grano grueso. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29054','playa','Playa de Fuengirola (Centro)','Bandera Azul','Excelente. Playa urbana situada frente al casco antiguo y el puerto deportivo, muy cómoda y accesible. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29054','playa','Playa del Castillo','Bandera Azul','Excelente. Situada a los pies del imponente Castillo Sohail, cuenta con una zona delimitada oficialmente para el acceso con perros y parcelas específicas con barcas para barbacoas. Arena fina y oscura. Sí tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29070','playa','Playa de La Cala de Mijas','Bandera Azul','Excelente. Antigua zona marinera convertida en centro urbano costero, dotada de la Senda Litoral de madera y servicios excelentes. Arena dorada de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29070','playa','Playa de El Bombo','Bandera Azul','Excelente. Continuación de La Cala hacia el oeste, de aguas limpias y profundas a los pocos metros del borde, ideal para el snorkel. Arena oscura y grava fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29070','playa','Playa de Calahonda (Mijas)','Bandera Azul','Excelente. Playa residencial flanqueada por urbanizaciones exclusivas, integrada en un espacio de interés natural por la calidad de sus fondos marinos. Arena dorada y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29070','playa','Playa de Algaida',NULL,'Muy buena. Tramo costero recorrido por la pasarela de madera, rodeado de dunas protegidas y pinares autóctonos. Arena fina. No tiene Bandera Azul. [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29069','playa','Playa de Puerto Banús / Río Verde','Bandera Azul','Excelente. Playa protegida por un gran dique artificial, situada junto a la famosa marina de lujo, de aguas totalmente calmas y someras. Arena dorada y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29069','playa','Playa de Casablanca','Bandera Azul','Excelente. Gran playa semiurbana respaldada por un paseo marítimo arbolado sin asfalto, dotada de oasis de palmeras y chiringuitos de alta gama. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29069','playa','Playa de El Faro','Bandera Azul','Excelente. Pequeña y resguardada playa situada en pleno centro urbano junto al puerto deportivo de Marbella, aguas muy tranquilas perfectas para niños. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29069','playa','Playa de San Pedro Alcántara','Bandera Azul','Excelente. Kilométrica playa urbana con un paseo marítimo amplio y ajardinado, de carácter muy residencial y tranquilo. Grava fina y arena dorada regenerada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29069','playa','Playa de Venus','Bandera Azul','Muy buena. Situada en pleno casco urbano, muy concurrida en temporada alta y con una amplísima oferta de hamacas y servicios náuticos. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29069','playa','Playa de Artola-Cabopino',NULL,'Excelente. Considerada la joya virgen de Marbella. Un espectacular sistema dunar protegido (Dunas de Artola) flanqueado por pinos y una torre vigía del siglo XIV. Cuenta con zona nudista. Arena blanca y finísima. No tiene Bandera Azul (preservación natural libre de pavimentos).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29069','playa','Playa de El Alicate',NULL,'Excelente. Una de las playas más exclusivas del municipio, rodeada de residencias de lujo y chiringuitos selectos, de gran anchura. Arena fina y dorada. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29051','playa','Playa de La Rada','Bandera Azul','Excelente. La playa urbana por excelencia de Estepona, de más de 2 kilómetros de longitud, paralela al reformado casco antiguo lleno de flores y al paseo marítimo. Arena fina y grisácea. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29051','playa','Playa de El Cristo','Bandera Azul','Excelente. Preciosa cala pequeña protegida de los vientos por un espigón natural, lo que genera una piscina de aguas templadas que apenas cubre, ideal para niños pequeños. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29051','playa','Playa de Arroyo Vaquero / Costa Natura',NULL,'Muy buena. Playa amplia que alberga el primer complejo nudista autorizado de la Costa del Sol occidental, ambiente muy tranquilo. Arena gruesa y cantos rodados finos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29051','playa','Playa del Padrón','Bandera Azul','Excelente. Situada junto a la desembocadura del río del mismo nombre y rodeada de centros comerciales turísticos y palmerales. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29051','playa','Playa de Bahía Dorada',NULL,'Buena. Zona residencial caracterizada por formaciones rocosas naturales en el agua que atraen a gran cantidad de fauna para snorkel. Grava y arena oscura. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29041','playa','Playa de Ancha','Bandera Azul','Excelente. La playa principal de la pequeña franja costera de este municipio serrano. Un arenal muy amplio y cuidado, integrado en el paseo marítimo residencial. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29041','playa','Playa de la Sal',NULL,'Muy buena. Debe su nombre a una antigua torre de salazón medieval situada sobre un promontorio rocoso, de ambiente tranquilo. Arena dorada de grano grueso y piedra fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29068','playa','Playa de Sabinillas','Bandera Azul','Excelente. Gran playa urbana vinculada al núcleo marinero de San Luis de Sabinillas, dotada de un paseo peatonal muy animado y servicios excelentes. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29068','playa','Playa de La Duquesa / El Castillo',NULL,'Muy buena. Situada junto al puerto deportivo de La Duquesa y el castillo fortificado del siglo XVIII, de aguas muy limpias. Arena gruesa y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('29068','playa','Playa de Punta Chullera',NULL,'Excelente. Espectacular entorno natural caracterizado por afloramientos de rocas calcáreas y acantilados bajos que forman pequeñas calas de aguas hipertransparentes, idóneas para el snorkel. Grava fina, arena dorada y piedra. No tiene Bandera Azul. [1] Sigo de forma continua con la Provincia de Cádiz (Costa de la Luz). Las respuestas de la IA pueden contener errores. Más información 35 sitios','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11033','playa','Playa de Sotogrande / Guadalquitón',NULL,'Excelente. Kilométrica playa virgen en su mayor parte, flanqueada por la urbanización de lujo y el estuario del río Guadiaro. Arena fina, dorada y zonas de grava. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11033','playa','Playa de Torreguadiaro','Bandera Azul','Excelente. Playa semiurbana muy popular, dotada de una laguna interior protegida y un gran paseo marítimo de madera con restaurantes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11033','playa','Playa de Cala Sardina / El Cabrero','Bandera Azul','Excelente. La playa más oriental de la provincia, rodeada de acantilados bajos y vegetación mediterránea, aguas cristalinas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11033','playa','Playa de Guadarranque',NULL,'Buena. Situada junto a la desembocadura del río Guadarranque, condicionada visualmente por las industrias cercanas de la bahía. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11022','playa','Playa de Sobrevela','Bandera Azul','Excelente. Enorme arenal en mar abierto que se extiende hacia el norte, muy espacioso y con un nivel de servicios óptimo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11022','playa','Playa de La Atunara / Santa Bárbara',NULL,'Muy buena. Vinculada al barrio marinero tradicional de La Línea, con vistas directas a la cara norte del Peñón de Gibraltar. Arena dorada de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11022','playa','Playa de Poniente (La Línea)',NULL,'Buena. Situada en el interior de la bahía de Algeciras, junto al puerto deportivo y la frontera, aguas tranquilas sin apenas oleaje. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16002','playa','Playa de Getares','Bandera Azul','Excelente. Gran playa urbana situada en una hermosa bahía rodeada de acantilados y el parque natural, con un paseo marítimo animado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16002','playa','Playa de El Rinconcillo',NULL,'Muy buena. La playa más tradicional y familiar de la ciudad, situada en el interior de la bahía, de aguas mansas pero condicionada visualmente por el puerto industrial. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11035','playa','Playa de Bolonia',NULL,'Excelente. Catalogada de forma recurrente entre las playas más espectaculares de Europa. Un paraje virgen salvaje que alberga una duna gigante natural y las impresionantes ruinas romanas de Baelo Claudia a pie de arena. Arena blanca finísima. No tiene Bandera Azul por preservación ecológica rígida.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11035','playa','Playa de Valdevaqueros',NULL,'Excelente. Meca mundial del windsurf y kitesurf debido a los regímenes constantes de viento de levante. Entorno natural espectacular con dunas y pinos. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11035','playa','Playa de Los Lances (Norte y Sur)','Bandera Azul','Excelente. Kilométrico arenal indómito de más de 3 kilómetros frente al estrecho de Gibraltar. Espacio natural protegido de dunas y marismas. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11035','playa','Playa Chica (Tarifa)',NULL,'Muy buena. Pequeña playa urbana situada junto al istmo, la última playa del mar Mediterráneo antes de pasar al océano Atlántico. Aguas frías y transparentes. Arena fina. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90031','playa','Playa de Zahara de los Atunes','Bandera Azul','Excelente. Impresionante y kilométrico arenal de arenas calientes y aguas cristalinas, muy cotizado por el turismo nacional y sus chiringuitos de calidad. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90031','playa','Playa de Los Caños de Meca',NULL,'Excelente. Famosa por sus acantilados cubiertos de pinos y los caños de agua dulce que brotan de las paredes de roca. Ambiente bohemio y naturista. Arena fina y dorada con rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90031','playa','Playa de Zahora',NULL,'Excelente. Playa virgen y salvaje que culmina en el icónico Faro de Trafalgar, escenario de la histórica batalla naval. Fuertes corrientes y puestas de sol monumentales. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90031','playa','Playa de Nuestra Señora del Carmen',NULL,'Muy buena. La playa urbana principal del pueblo de Barbate, muy ancha, resguardada y dotada de un paseo marítimo cómodo. Arena fina y dorada. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11039','playa','Playa de El Palmar',NULL,'Excelente. La única playa de este famoso pueblo blanco, convertida en uno de los grandes templos del surf, el ocio juvenil y el ecoturismo de Andalucía. Kilómetros de costa virgen protegida por dunas bajas con pasarelas de madera. Arena dorada y finísima. No tiene Bandera Azul (enfocada a la gestión integrada sin pavimentos).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16008','playa','Playa de Los Bateles','Bandera Azul','Excelente. La playa urbana principal del municipio, inmensamente ancha, situada en la desembocadura del río Salado, meca del kitesurf local. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16008','playa','Playa de La Fontanilla','Bandera Azul','Excelente. Continuación de Los Bateles, muy familiar y famosa por albergar los mejores restaurantes de atún rojo de almadraba a pie de arena. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16008','playa','Calas de Roche (Cala Encendida / Cala Tío Juan de Medina)',NULL,'Excelente. Sucesión de calas salvajes excavadas bajo impresionantes acantilados de tierra rojiza cubiertos de pinos, protegidas de los fuertes vientos de levante. Arena fina y dorada con rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16008','playa','Playa de Fuente del Gallo',NULL,'Muy buena. Espectacular playa encajada bajo un acantilado vertical imponente, desaparece casi por completo durante la pleamar. Arena fina. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16007','playa','Playa de La Barrosa','Bandera Azul','Excelente. Considerada una de las mejores playas de España. Un arenal colosal de más de 5 kilómetros de largo dividido en un tramo urbano con paseo marítimo y una inmensa zona virgen flanqueada por pinares y hoteles de gran lujo (Novo Sancti Petri). Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16007','playa','Playa de Sancti Petri','Bandera Azul','Excelente. Situada frente al místico Castillo de Sancti Petri y el canal de la ría, un entorno natural bellísimo muy buscado para contemplar puestas de sol y deportes de remo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11031','playa','Playa de Camposoto / El Castillo','Bandera Azul','Excelente. Playa completamente virgen integrada en el Parque Natural de la Bahía de Cádiz. Antigua zona militar libre de ladrillo, dotada de pasarelas kilométricas de madera y senderos sobre marismas. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16009','playa','Playa de La Victoria','Bandera Azul','Excelente. Considerada la mejor playa urbana de Europa. Un arenal inmenso perfectamente integrado en la avenida principal de la ciudad, con un despliegue de servicios públicos impecable. Arena dorada y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16009','playa','Playa de La Caleta','Bandera Azul','Excelente. Icono histórico y cultural de la ciudad, encajada en el barrio de la Viña entre los castillos coloniales de Santa Catalina y San Sebastián. Escenario cinematográfico internacional. Arena fina y dorada con rocas. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16009','playa','Playa de Cortadura','Bandera Azul','Excelente. La playa más extensa del municipio, situada en el istmo de entrada a la ciudad, rodeada de un complejo dunar salvaje restaurado. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('16009','playa','Playa de Santa María del Mar','Bandera Azul','Excelente. Hermosa playa con forma de concha resguardada por dos espigones de piedra, de ambiente muy familiar y con vistas preciosas a la catedral barroca de Cádiz. Arena fina y dorada. Sí tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11028','playa','Playa de La Cachucha',NULL,'Buena. Playa urbana situada en el interior del saco de la bahía de Cádiz, de aguas mansas, templadas y con barros tradicionales de uso medicinal. Muy afectada por las mareas. Arena fina y fango. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11028','playa','Playa del Río San Pedro',NULL,'Aceptable. Franja de arena situada en el canal del río, de carácter residencial local muy tranquilo. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11027','playa','Playa de Valdelagrana','Bandera Azul','Excelente. Inmenso arenal urbano dotado de un paseo marítimo animado, aguas muy tranquilas de poca profundidad e ideal para familias, colindante con el parque natural. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11027','playa','Playa de Fuentebravía','Bandera Azul','Excelente. Situada en una zona residencial muy cotizada, encajada bajo pequeños acantilados arcillosos, servicios excelentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11027','playa','Playa de La Calita / La Muralla',NULL,'Muy buena. Pequeña y resguardada cala situada junto a las ruinas del castillo de Santa Catalina, de aguas muy limpias. Arena fina y rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11027','playa','Playa de Las Redes / El Ancla',NULL,'Excelente. Extensa playa residencial de arenas blancas y aguas abiertas atlánticas de gran calidad. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11027','playa','Playa de Santa Catalina / Los Toruños',NULL,'Excelente. Integrada en el Parque Metropolitano, un espacio virgen inmenso de dunas y marismas ideal para el ecoturismo. Arena blanca fina. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11030','playa','Playa de la Costilla','Bandera Azul','Excelente. Espectacular playa urbana principal galardonada de forma sistemática por su calidad, con un paseo marítimo integrado y los famosos corrales de pesca tradicionales anexos. Arena dorada y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11030','playa','Playa de Punta Candor','Bandera Azul','Excelente. Entorno natural de una belleza salvaje, flanqueada por pinares autóctonos protegidos y dunas bajas. Arena blanca y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11030','playa','Playa de La Ballena','Bandera Azul','Excelente. Gran playa que da servicio al complejo turístico Costa Ballena, muy ancha, espaciosa y con dunas restauradas excelentes. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11030','playa','Playa del Chorrillo / Rompidillo','Bandera Azul','Excelente. Situada entre el puerto pesquero y las murallas históricas, aguas muy tranquilas protegidas del viento por el espigón. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11030','playa','Playa de Galeones','Bandera Azul','Excelente. Playa urbana muy cuidada situada junto a la base naval militar, de ambiente muy familiar. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90032','playa','Playa de Regla','Bandera Azul','Excelente. Una de las playas más famosas y concurridas de Andalucía, presidida por el faro más alto de España y el Santuario de la Virgen de Regla. Aguas muy ricas en yodo. Arena dorada finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90032','playa','Playa de Camarón-La Laguna','Bandera Azul','Excelente. Espacio natural protegido que alberga dunas bajas donde habita el camaleón común, dotada de pasarelas de madera excelentes. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90032','playa','Playa de Las Tres Piedras','Bandera Azul','Excelente. Gran playa que conecta con el término de Rota, famosa por sus arrecifes naturales visibles en bajamar y sus chiringuitos gastronómicos modernos. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90032','playa','Playa de la Cruz del Mar','Bandera Azul','Excelente. Situada junto al puerto deportivo y pesquero, de aguas tranquilas y familiares vinculadas a la gastronomía local de mariscos. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11032','playa','Playa de Bajo de Guía',NULL,'Excelente. Famosa mundialmente por ser el escenario de las históricas Carreras de Caballos de Sanlúcar. Situada en la desembocadura del río Guadalquivir, ofrece vistas espectaculares al Parque Nacional de Doñana justo enfrente. Arena fina y dorada. No tiene Bandera Azul (por corrientes fluviales intensas).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11032','playa','Playa de Las Piletas',NULL,'Muy buena. Continuación natural de Bajo de Guía, dotada de un paseo arbolado agradable de ambiente familiar. Arena fina y conchas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11032','playa','Playa de la Calzada',NULL,'Muy buena. El tramo playero urbano principal donde se concentran los grandes eventos del verano y las carreras de caballos. Arena dorada de grano medio. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11032','playa','Playa de la Jara',NULL,'Muy buena. Situada en una zona residencial tranquila, flanqueada por acantilados bajos arcillosos y corrales de pesca artesanales. Arena fina y piedras en bajamar. No tiene Bandera Azul. Sigo de forma continua con la Provincia de Huelva (Costa de la Luz Occidental). Las respuestas de la IA pueden contener errores. Más información 6 sitios','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('11032','playa','Calas de Roche (Conil ( Conil de la Frontera ) )',NULL,'al estar protegidas por altos acantilados rojizos, el viento pasa por arriba y t... El Viaje de Sofi Mostrar todo Has dicho: sigue','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('22002','playa','Playa de Matalascañas (Torre de la Higuera)','Bandera Azul','Excelente. Kilométrico arenal famoso por albergar la icónica "Torre del Loro" volcada en la orilla. Es la playa más cercana al Parque Nacional de Doñana, con un contraste espectacular entre dunas blancas y servicios urbanos. Arena blanca finísima. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('22002','playa','Playa de Doñana',NULL,'Excelente. Espacio estrictamente virgen y protegido dentro del Parque Nacional, de acceso restringido para preservar el ecosistema dunar móvil y la fauna endémica. Arena fina y blanca. No tiene Bandera Azul por motivos de conservación ecológica estricta. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21050','playa','Playa de Mazagón (Moguer)','Bandera Azul','Excelente. Impresionante playa salvaje encajada bajo el espectacular acantilado arenoso del Médano de Asperillo. Rodeada de pinares y con un nivel de ocupación bajísimo. Arena fina y dorada. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21050','playa','Playa del Parador',NULL,'Excelente. Sector virgen dotado de un parador nacional de turismo en la cima del acantilado, pasarelas de madera integradas en la naturaleza. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21055','playa','Playa de Mazagón (Palos)','Bandera Azul','Excelente. Tramo urbano de la localidad gestionado por este municipio histórico, dotado de puerto deportivo y paseo marítimo con excelentes restaurantes marineros. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21055','playa','Playa de las Dunas',NULL,'Muy buena. Zona residencial de baja densidad con un bonito pinar litoral y dunas protegidas. Arena fina. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21041','playa','Playa del Espigón',NULL,'Muy buena. Única playa de la capital, situada dentro del Paraje Natural de las Marismas del Odiel. Un entorno completamente salvaje de más de dos kilómetros lineales de mar abierto y dunas bajas, libre de edificaciones y con zona oficialmente canina. Arena fina y dorada. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21060','playa','Playa de Punta Umbría','Bandera Azul','Excelente. La playa urbana por excelencia de los onubenses, inmensamente ancha y dotada de un paseo arbolado moderno y todo tipo de chiringuitos de calidad. Arena blanca finísima. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21060','playa','Playa de El Portil (Punta Umbría)','Bandera Azul','Excelente. Playa residencial muy tranquila situada frente a la Flecha de El Rompido, de aguas totalmente calmas simulando una laguna interior gigante. Arena fina y blanca. Sí tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21060','playa','Playa de La Canaleta','Bandera Azul','Excelente. Situada en el vértice de la ría de Huelva, muy buscada para escuelas de vela y deportes náuticos. Arena dorada y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21060','playa','Playa de los Enebrales',NULL,'Excelente. Impresionante paraje virgen cruzado por un carril bici, donde un espeso bosque de enebros y pinos llega directo hasta el borde de la arena fina. Un paraíso de paz. Arena blanca fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21021','playa','Playa de San Miguel','Bandera Azul','Excelente. Situada en la desembocadura del río Piedras, de aguas cálidas y tranquilas ideales para el baño infantil y la práctica del piragüismo. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21021','playa','Playa de El Rompido',NULL,'Muy buena. Ubicada junto al encantador pueblo marinero tradicional, con pantalanes de madera y barcas fondeadas frente al paisaje de la flecha arenosa. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21021','playa','Playa del Caño de la Culata',NULL,'Muy buena. Hermoso tramo natural donde se cruzan las marismas, dunas bajas de arena fina y abundante vegetación de ribera. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21044','playa','Playa de Islantilla (Compartida con Isla Cristina)','Bandera Azul','Excelente. Referente del turismo sostenible de la provincia. Un arenal kilométrico flanqueado por un paseo marítimo elegante, palmerales, hoteles de alta gama y campos de golf. Arena dorada finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21044','playa','Playa de La Antilla','Bandera Azul','Excelente. Playa urbana tradicional muy familiar, muy ancha y cuidada, famosa por su animada avenida de chiringuitos gastronómicos. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21044','playa','Playa de Nueva Umbría',NULL,'Excelente. Espectacular lengua de arena virgen (la Flecha del Rompido) con el océano por un lado y la ría por el otro. Zona nudista oficial, aislamiento absoluto y nula edificación. Arena blanca finísima. No tiene Bandera Azul (preservación natural rígida). [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21042','playa','Playa Central','Bandera Azul','Excelente. La playa urbana principal del municipio, muy amplia y dotada de un pinar inmenso con senderos peatonales y servicios públicos excelentes. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21042','playa','Playa de Islantilla (Sector Isla Cristina)','Bandera Azul','Excelente. Cuenta con un centro de actividades náuticas de primer orden y excelentes pasarelas de madera sobre las dunas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21042','playa','Playa del Cantil',NULL,'Muy buena. Situada en el interior del puerto y la ría, aguas en calma total sin apenas oleaje, de ambiente muy marinero. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21042','playa','Playa de Punta del Caimán',NULL,'Excelente. Conectada mediante un largo puente peatonal sobre las marismas, un entorno natural paradisíaco de aguas templadas. Arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('21042','playa','Playa del Hoyo',NULL,'Excelente. Rodeada por una densa masa forestal de pinos piñoneros con áreas de picnic y ocio familiar integrado. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('22006','playa','Playa de Isla Canela','Bandera Azul','Excelente. Inmenso arenal de marea cambiante situado en la desembocadura del río Guadiana (frontera con Portugal). Aguas extremadamente someras y cálidas, meca regional del kitesurf. Arena dorada y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('22006','playa','Playa de Punta del Moral','Bandera Azul','Excelente. Antigua barriada de pescadores reconvertida en un núcleo turístico exclusivo con puerto deportivo y excelentes servicios hoteleros y de restauración a pie de arena. Arena fina y blanca. Sí tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07040','playa','Playa de Palma (El Arenal)','Bandera Azul','Excelente. Kilométrica playa urbana que recorre toda la bahía de Palma, flanqueada por un paseo marítimo interminable de palmeras, hoteles y comercios. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07040','playa','Playa de Can Pere Antoni','Bandera Azul','Muy buena. La playa más cercana al centro histórico y la catedral de Palma, muy cómoda para los residentes y con carril bici integrado. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07040','playa','Playa de Ciudad Jardín','Bandera Azul','Muy buena. De ambiente marcadamente residencial local, protegida por espigones paralelos de piedra que calman el oleaje. Arena fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07040','playa','Cala Estància','Bandera Azul','Excelente. Pequeña cala artificial con forma de concha cerrada por espigones, oleaje nulo y aguas totalmente mansas. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07040','playa','Cala Major','Bandera Azul','Excelente. Playa urbana tradicional resguardada del viento por acantilados residenciales, aguas muy limpias y turquesas. Arena fina y blanca. Sí tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90018','playa','Playa de Palmira (Peguera)','Bandera Azul','Excelente. Playa urbana de gran elegancia con un paseo marítimo peatonal ajardinado, aguas muy tranquilas e ideales para familias. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90018','playa','Playa de Tora (Peguera)','Bandera Azul','Excelente. Siguiente arenal del núcleo, rodeada de pinos mediterráneos y de gran anchura. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90018','playa','Playa de Santa Ponça','Bandera Azul','Excelente. Gran playa situada en una bahía profunda resguardada de las corrientes, flanqueada por un pinar inmenso con césped. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90018','playa','Playa de Palmanova','Bandera Azul','Excelente. Muy espaciosa y con un nivel de servicios públicos impecable, dotada de todo tipo de deportes náuticos. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90018','playa','Playa de Es Carregador','Bandera Azul','Excelente. Pequeña cala residencial muy cuidada y limpia al este del núcleo de Palmanova. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90018','playa','Playa de Son Maties','Bandera Azul','Excelente. Gran cala urbana que completa la terna de Palmanova, de aguas hipertransparentes de color azul intenso. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90018','playa','Playa de Illetes / Cala Comptessa',NULL,'Excelente. Preciosas calas de alta gama rodeadas de pinos y rocas calizas, aguas caribeñas de color verde esmeralda. Arena fina y blanca con rocas. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90017','playa','Playa de Camp de Mar','Bandera Azul','Excelente. Famosa por albergar un icónico restaurante situado en un islote rocoso en mitad del agua, conectado a la playa por una pasarela de madera. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90017','playa','Playa de Sant Elm','Bandera Azul','Excelente. Dividida en dos sectores (uno de arena y otro de grava), ofrece vistas espectaculares a la isla protegida de Dragonera, aguas cristalinas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90017','playa','Cala Llamp',NULL,'Muy buena. Espectacular cala rocosa encajada bajo acantilados colosales, sin arena natural, equipada con escaleras de acceso directo a aguas profundas ideales para buceo. No tiene Bandera Azul. Sigo de forma continua con el resto de Mallorca (Ses Salines, Alcúdia, Pollença), Menorca, e Ibiza. Las respuestas de la IA pueden contener errores. Más información 16 sitios','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07021','playa','Playa de Es Trenc',NULL,'Excelente. Uno de los arenales vírgenes más icónicos y protegidos de Mallorca, rodeado de un sistema de dunas salvajes y salinas. Aguas someras hipertransparentes de color azul turquesa. Arena blanca finísima. No tiene Bandera Azul por su estatus de parque natural protegido.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07021','playa','Playa del Carbo (Es Carbó)',NULL,'Excelente. Playa completamente virgen de acceso exclusivo a pie (unos 30 minutos desde la Colonia de Sant Jordi), aislamiento absoluto. Arena fina y blanca con presencia de posidonia. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07021','playa','Playa de Es Dolç',NULL,'Muy buena. Situada cerca del núcleo urbano pero manteniendo un entorno dunar natural, aguas cristalinas y limpias. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07020','playa','Cala Mondragó (Sa Font de n''Alis)','Bandera Azul','Excelente. Ubicada dentro del Parque Natural de Mondragó, rodeada de humedales, pinos y acantilados bajos de piedra caliza. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07020','playa','Playa de S''Amarador','Bandera Azul','Excelente. Conectada por un sendero litoral con Cala Mondragó, un arenal virgen espectacular con una laguna de agua dulce anexa. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07020','playa','Cala Santanyí','Bandera Azul','Excelente. Cala urbana resguardada por altos acantilados con pinos, de aguas muy mansas y color esmeralda, muy familiar. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07020','playa','Cala Llombards',NULL,'Excelente. Preciosa cala encajada en un desfiladero rocoso, de aguas transparentes que simulan una piscina natural profunda, ideal para saltos de roca y snorkel. Arena blanca fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07020','playa','Caló des Moro',NULL,'Excelente. Una de las playas más fotografiadas del Mediterráneo por sus aguas hipertransparentes entre dos paredes de roca colosales. Espacio diminuto y masificado, sin servicios. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07020','playa','Cala S''Almunia',NULL,'Muy buena. Antigua cala de pescadores vecina del Caló des Moro, flanqueada por rampas de madera para barcas tradicionales. Roca viva y pasillos de arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07008','playa','Cala Marçal','Bandera Azul','Excelente. La playa más grande y equipada de Portocolom, encajada en una entrada de mar profunda que mitiga el oleaje. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07008','playa','Cala Sa Nau',NULL,'Excelente. Cala virgen al final de un largo y sinuoso meandro rocoso, rodeada de pinos y con un chiringuito muy popular. Arena blanca y finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07008','playa','Playa de S''Arenal de Portocolom',NULL,'Muy buena. Situada en la cara interior de la bahía, frente al faro histórico, aguas en calma absoluta. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07033','playa','Cala Varques',NULL,'Excelente. Cala virgen y salvaje de tradición nudista, rodeada de bosques y famosa por sus cuevas submarinas y su puente de roca natural. Acceso a pie de 20 minutos. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07033','playa','Cala Domingos (Gran y Petita)','Bandera Azul','Excelente. Dos calas de gran calidad turística situadas en el núcleo de Cales de Mallorca, unidas por un sendero sobre las rocas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07033','playa','Cala Mendia','Bandera Azul','Excelente. Hermosa entrada de mar de aguas azul turquesa rodeada de acantilados residenciales de baja altura. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07033','playa','Cala Anguila','Bandera Azul','Excelente. Vecina de Cala Mendia, flanqueada por formaciones de piedra caliza blanca y una densa vegetación mediterránea. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07033','playa','Playa de Porto Cristo',NULL,'Muy buena. Playa urbana situada junto al puerto pesquero y las famosas Cuevas del Drach, aguas tranquilas de ría. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90019','playa','Cala Agulla','Bandera Azul','Excelente. Gran playa virgen declarada Área Natural de Especial Interés, rodeada de dunas salvajes y un pinar inmenso, oleaje moderado. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90019','playa','Cala Mesquida','Bandera Azul','Excelente. Impresionante playa salvaje flanqueada por dunas gigantes protegidas por pasarelas de madera, mar abierto con oleaje fuerte ideal para el surf. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90019','playa','Cala Gat',NULL,'Muy buena. Pequeña cala de aguas hipertransparentes situada a las afueras de Cala Ratjada, rodeada de acantilados bajos. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90019','playa','Playa de Canyamel','Bandera Azul','Excelente. Playa semiurbana resguardada por un torrente natural y colinas verdes, aguas limpias y profundas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90019','playa','Font de Sa Cala',NULL,'Muy buena. Cala turística equipada que debe su nombre a manantiales de agua dulce submarinos que brotan en la zona. Arena fina y rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07004','playa','Cala Torta',NULL,'Excelente. Espectacular playa completamente salvaje y aislada, abierta al norte con oleaje moderado, entorno árido e indómito. Arena dorada de grano grueso. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07004','playa','Cala Mitjana (Artà)',NULL,'Excelente. Vecina de Cala Torta, virgen, rodeada de dunas bajas y campos de matorral mediterráneo. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07004','playa','S''Arenalet des Verger',NULL,'Excelente. Ubicada en el Parque Natural de la Península de Llevant, una de las playas más aisladas de Mallorca, acceso a pie de 3 horas. Arena blanca y fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07055','playa','Playa de Can Picafort','Bandera Azul','Excelente. Gran playa urbana que recorre el paseo marítimo principal del núcleo turístico, dotada de todo tipo de servicios e infraestructuras. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07055','playa','Playa de Son Bauló','Bandera Azul','Excelente. Situada en la desembocadura de un torrente, marca el inicio de una zona arqueológica y natural virgen. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07055','playa','Playa de Son Serra de Marina',NULL,'Excelente. Playa totalmente natural e indómita, meca local del kitesurf y el windsurf por sus vientos, con zona nudista. Arena dorada de grano grueso y dunas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07001','playa','Playa de Alcúdia (Playa Gran)','Bandera Azul','Excelente. Un arenal colosal de más de 3 kilómetros de largo en la bahía de Alcúdia. Aguas extremadamente someras (hay que caminar mucho para que cubra) y mansas, ideal para familias. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07001','playa','Playa de Sant Pere / Sant Joan (Mal Pas)',NULL,'Excelente. Dos pequeñas calas residenciales de aguas turquesas que ofrecen vistas espectaculares a la península de Formentor. Arena blanca y muy fina. No tienen Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07001','playa','Playa de Coll Baix',NULL,'Excelente. Espectacular cala virgen oculta bajo acantilados colosales, acceso peatonal complejo por montaña o en barco. Compuesta de cantos rodados y grava gris oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07017','playa','Playa de Formentor (Cala Pi)','Bandera Azul','Excelente. Icono del turismo aristocrático internacional, flanqueada por un denso bosque de pinos cuyas ramas tocan el agua del mar. Aguas hipertransparentes de color verde esmeralda. Arena blanca y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07017','playa','Playa de Llenaire / Port de Pollença','Bandera Azul','Excelente. Gran playa urbana que bordea el paseo marítimo del puerto, muy resguardada por la bahía y muy valorada para el windsurf ligero. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07017','playa','Cala Sant Vicenç (Cala Barques / Cala Molins)','Bandera Azul','Excelente. Sucesión de calas situadas bajo el imponente perfil de la sierra de Tramuntana, aguas profundas de color azul marino intenso. Arena blanca y fina con zonas de roca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07017','playa','Cala Figuera (Pollenca)',NULL,'Excelente. Cala virgen espectacular situada en el cabo de Formentor, encajada entre acantilados verticales verticales. Grava, cantos rodados y roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07061','playa','Playa de C''an Repic / Es Traves',NULL,'Muy buena. Playas urbanas situadas en la hermosa bahía circular del Port de Sóller, flanqueadas por el tranvía histórico y restaurantes. Aguas en calma total. Arena dorada, grava y cantos rodados finos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90020','playa','Cala Deià',NULL,'Excelente. Pintoresca cala de alta calidad paisajística encajada en la sierra de Tramuntana, rodeada de antiguos muelles y dos restaurantes tradicionales de pescado sobre las rocas. Aguas verde esmeralda profundas. Compuesta de cantos rodados, piedra y grandes bloques de roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07063','playa','Playa de Port de Valldemossa',NULL,'Buena. Cala rústica situada al final de una carretera de montaña muy estrecha y empinada, entorno salvaje imponente. Compuesta por piedras, cantos rodados y fondos rocosos para snorkel. No tiene Bandera Azul. ISLA DE MENORCA','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07006','playa','Cala Macarella y Macarelleta',NULL,'Excelente. Postales paradisíacas por excelencia de Menorca, acantilados blancos cubiertos de pinos que encierran un mar turquesa sobre fondo de arena blanca finísima. No tienen Bandera Azul por preservación ecológica.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07006','playa','Cala en Turqueta',NULL,'Excelente. Cala virgen escondida entre densos pinares, de aguas hipertransparentes de color azul celeste. Arena blanca y finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07006','playa','Playa de Son Saura (Bellavista / Es Banyul)',NULL,'Excelente. Extenso arenal virgen del sur, dividido en dos playas por un islote de roca, aguas muy someras y familiares. Arena blanca y fina con restos de posidonia. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07006','playa','Cala Algaiarens (La Vall)',NULL,'Excelente. Playas vírgenes de la costa norte (Es Tancats / Es Bot), rodeadas de dunas, sistemas boscosos y torrentes. Arena fina y blanca (inusual en el norte). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07006','playa','Cala Morell',NULL,'Muy buena. Cala residencial de carácter rocoso rodeada de cuevas prehistóricas, plataformas artificiales de cemento para el baño. Roca viva y poca arena gruesa. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07006','playa','Cala Blanca (Menorca)',NULL,'Muy buena. Cala urbana pequeña y muy resguardada del oleaje, de aguas limpias y comerciales. Arena fina y blanca. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07037','playa','Playa de Cavalleria',NULL,'Excelente. Impresionante playa virgen de la costa norte, flanqueada por acantilados de arcilla roja y dunas fósiles, mar abierto de gran belleza agreste. Arena dorada gruesa y tonos rojizos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07037','playa','Cala Pregonda',NULL,'Excelente. Considerada una de las playas más singulares del mundo; paisaje lunar con rocas volcánicas de color amarillo y rojo que protegen la cala como un arrecife natural. Arena dorada de grano grueso. No tiene Bandera Azul (protección integral).','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07037','playa','Playa de Son Bou (Compartida con Alaior)',NULL,'Ver sección Alaior.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90016','playa','Playa de Son Bou',NULL,'Excelente. La playa más larga de Menorca (casi 3 kilómetros), flanqueada por un humedal protegido (Prat de Son Bou) rico en avistamiento de aves y dunas. Aguas abiertas y cristalinas. Arena dorada y finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90016','playa','Cala en Porter',NULL,'Excelente. Espectacular cala encajada en el cañón de un barranco monumental, lo que genera una piscina natural sin olas totalmente protegida del viento. Arena blanca y fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07902','playa','Cala Binigaus',NULL,'Excelente. Extensa playa virgen del sur conectada con la playa de Santo Tomás, rodeada de acantilados arcillosos y de tradición nudista. Arena blanca y fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07902','playa','Playa de Santo Tomás / San Adeodato',NULL,'Muy buena. Playas semiurbanas integradas en un complejo residencial respetuoso, dotadas de paseos de madera cómodos. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90021','playa','Playa de Es Grau',NULL,'Excelente. Situada dentro del Parque Natural de s''Albufera des Grau, bahía totalmente cerrada por una isla que garantiza aguas mansas que no cubren, ideal para niños. Arena fina y grisáeca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90021','playa','Cala Presili / Cala Tortuga',NULL,'Excelente. Playas vírgenes de la costa norte situadas bajo el espectacular perfil del Faro de Favaritx, paisaje de pizarra negra desértico. Arena fina y oscura. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07052','playa','Playa de Punta Prima (Menorca)',NULL,'Excelente. Playa urbana de aguas de color azul turquesa intenso que mira directo a la Isla del Aire y su faro histórico. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07052','playa','Caló Blanc',NULL,'Muy buena. Diminuta cala excavada en roca blanca caliza lisa, aguas hipertransparentes muy cotizadas para saltar al mar. Roca viva y un minúsculo pasillo de arena fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07052','playa','Cala Binibèquer',NULL,'Excelente. Preciosa cala pequeña rodeada de pinos y contigua al famoso pueblo blanco recreado de pescadores de Binibeca Vell. Arena fina y blanca. No tiene Bandera Azul. ISLA DE IBIZA','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90023','playa','Playa de Ses Salines (Ibiza)',NULL,'Excelente. Una de las playas más famosas de la isla, integrada en el parque natural de las salinas, frecuentada por celebridades y dotada de chiringuitos de lujo. Aguas turquesas poco profundas. Arena blanca finísima. No tiene Bandera Azul por normativas del parque.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90023','playa','Cala D''Hort',NULL,'Excelente. Famosa mundialmente por ofrecer las mejores vistas frontales al imponente y místico islote de Es Vedrà que emerge 400 metros del agua. Arena fina, grava y cantos rodados. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90023','playa','Cala Conta (Platges de Comte)',NULL,'Excelente. Conjunto de calas que ofrecen una de las mejores puestas de sol de Ibiza, de aguas hipertransparentes sobre fondos de arena blanca pura que simulan una piscina natural. Arena blanca y fina con rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90023','playa','Cala Bassa',NULL,'Excelente. Bahía natural rodeada de un frondoso bosque de sabinas centenarias, de aguas mansas de color turquesa y servicios turísticos muy exclusivos. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90023','playa','Playa d''en Bossa (Compartida con Ibiza Ciudad)',NULL,'Muy buena. La playa más larga de la isla, epicentro mundial del ocio nocturno y clubes de playa hoteleros. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07054','playa','Playa de Santa Eulària','Bandera Azul','Excelente. Gran playa urbana totalmente reformada libre de humos, con un paseo marítimo ajardinado excelente y aguas tranquilas. Arena fina y blanca. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07054','playa','Cala Llonga','Bandera Azul','Excelente. Profunda bahía en forma de desfiladero que frena por completo las corrientes marinas, muy familiar y cómoda. Arena blanca y muy fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07054','playa','Playa de Es Canar','Bandera Azul','Muy buena. Playa turística en forma de herradura muy frecuentada, ligada al famoso mercadillo hippie de Punta Arabí. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07054','playa','Cala Nova',NULL,'Excelente. Playa semiurbana abierta al este con un oleaje moderado muy divertido, rodeada de pinares y dunas bajas. Arena dorada de excelente calidad. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90022','playa','Cala Benirràs',NULL,'Excelente. Famosa internacionalmente por su fiesta de tambores dominguera durante la puesta de sol frente al islote del "Dedo de Dios". Entorno virgen de pinares. Arena gruesa y cantos rodados finos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90022','playa','Cala San Vicente (Ibiza)','Bandera Azul','Excelente. Gran playa resguardada por colinas imponentes, de aguas azul marino intensas y paseos peatonales modernos con palmeras. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90022','playa','Cala Xarraca',NULL,'Muy buena. Cala rústica ideal para el snorkel debido a la pureza de sus aguas y la presencia de cuevas y rocas calizas. Arena gruesa, grava y roca. No tiene Bandera Azul. ISLA DE FORMENTERA','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07009','playa','Playa de Ses Illetes',NULL,'Excelente. Catalogada de forma sistemática entre las mejores playas del mundo. Una lengua de arena blanca finísima rodeada de aguas hipertransparentes gracias a las praderas de posidonia oceánica (Patrimonio de la Humanidad). No tiene Bandera Azul por restricciones de servicios pesados en parque natural.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07009','playa','Playa de Llevant (Formentera)',NULL,'Excelente. Situada en la cara opuesta de Ses Illetes, en mar abierto, más ventosa y con oleaje moderado, ambiente nudista y virgen. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07009','playa','Playa de Migjorn',NULL,'Excelente. El arenal más extenso de la isla (5 kilómetros de longitud en forma de arco al sur), que combina tramos de arena pura con zonas rocosas y pasarelas de madera. Arena fina y blanca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07009','playa','Caló des Mort',NULL,'Excelente. Minúscula cala virgen encajada bajo acantilados arcillosos bajos, un paraíso absoluto de aguas de color azul turquesa. Espacio muy reducido. Arena blanca y fina combinada con rocas. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07009','playa','Playa de Es Pujols',NULL,'Muy buena. La única playa urbana y comercial de la isla, protegida por una línea de islotes rocosos, con un paseo animado y casetas de pescadores. Arena fina y blanca. No tiene Bandera Azul. [1, 2] Con esta entrega completamos las Islas Baleares, Andalucía, Murcia, Comunidad Valenciana, Cataluña, País Vasco, Cantabria y la zona norte de Galicia. ¿Deseas que abordemos la costa atlántica de las Islas Canarias o prefieres cerrar el listado aquí para tu Word? Las respuestas de la IA pueden contener errores. Más información 3 sitios','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('07009','playa','Playa Migjorn ( playa de Migjorn )',NULL,'con casi 5 kilómetros, es la playa más larga de la isla y ocupa casi toda la zona sur. Aunque... Hoteles.net','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35016','playa','Playa de Las Canteras','Bandera Azul','Excelente. Considerada una de las mejores playas urbanas del mundo. Cuenta con una barra de arrecife de arenisca natural ("la barra") que actúa como rompeolas y crea una piscina natural gigante para el snorkel. Arena dorada y finísima. Sí tiene Bandera Azul. [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35016','playa','Playa de Las Alcaravaneras',NULL,'Aceptable. Situada en pleno centro de la ciudad, flanqueada por las instalaciones del puerto de la Luz. Aguas totalmente en calma, muy orientada a deportes de arena y vela. Arena dorada de grano medio. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35016','playa','Playa de la Laja',NULL,'Muy buena. Ubicada en el acceso sur de la ciudad, expuesta al mar abierto con oleaje fuerte, cuenta con tres espectaculares piscinas artificiales de agua marina. Arena fina y gris oscura (volcánica). No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35016','playa','Playa de San Cristóbal',NULL,'Buena. Barrio marinero tradicional de casas de colores a pie de mar, ambiente muy local. Compuesta principalmente por cantos rodados (callaos) y roca viva. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35019','playa','Playa de Maspalomas','Bandera Azul','Excelente. Un monumento natural de fama mundial por su impresionante campo de dunas vivas, su charca y su faro decimonónico. Kilómetros de arena fina y dorada que se funden con el mar abierto. Sí tiene Bandera Azul. [1, 2, 3]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35019','playa','Playa del Inglés','Bandera Azul','Excelente. Continuación natural de Maspalomas, es uno de los epicentros turísticos y de ocio más importantes de Europa, inmensamente ancha y dotada de todos los servicios turísticos posibles. Arena fina y dorada. Sí tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35019','playa','Playa de San Agustín','Bandera Azul','Excelente. Playa semiurbana de ambiente más residencial y tranquilo, muy protegida del viento y del oleaje, ideal para familias. Arena oscura de grano fino. Sí tiene Bandera Azul. [1, 2, 3]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35019','playa','Playa de Las Burras','Bandera Azul','Excelente. Hermosa concha resguardada por espigones artificiales que garantizan un baño totalmente seguro sin corrientes. Arena fina y oscura. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35019','playa','Playa de Meloneras',NULL,'Muy buena. Situada al oeste del faro, bordeada por un elegante paseo marítimo de alta gama. Arena dorada mezclada con cantos rodados finos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35012','playa','Playa de Mogán','Bandera Azul','Excelente. Preciosa playa urbana resguardada junto al pintoresco Puerto de Mogán (la "Venecia de Canarias"). Aguas en calma absoluta que simulan una piscina natural. Arena dorada y finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35012','playa','Playa de Amadores','Bandera Azul','Excelente. Bahía artificial en forma de media luna perfecta con aguas de color azul turquesa transparente y oleaje nulo. Arena blanca caliza y fina. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35012','playa','Playa de Puerto Rico',NULL,'Muy buena. La primera playa artificial creada en la isla, totalmente rodeada de complejos hoteleros en los acantilados, aguas muy mansas. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35012','playa','Playa de Anfi del Mar (La Verga)',NULL,'Excelente. Playa privada de una urbanización de lujo pero de acceso público, rodeada de palmeras cocoteras y aguas cristalinas. Arena blanca y finísima (importada del Caribe). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35012','playa','Playa de Patalavaca',NULL,'Muy buena. Dividida en dos calas por un saliente rocoso, ambiente residencial muy tranquilo. Arena oscura de grano fino. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35015','playa','Playa de Sotavento',NULL,'Excelente. Un espectáculo de la naturaleza donde la marea baja crea una inmensa laguna de aguas turquesas y someras separada del mar abierto por una barra de arena, meca mundial del kitesurf. Arena blanca y finísima. No tiene Bandera Azul por preservación ecológica.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35015','playa','Playa de Matorral (Morro Jable)','Bandera Azul','Excelente. Kilométrico arenal de arenas blancas y aguas cristalinas presidido por un faro y un saladar protegido de alto valor ecológico. Arena blanca finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35015','playa','Playa de Cofete',NULL,'Excelente. Una de las playas más salvajes, indómitas y sobrecogedoras de España. Kilómetros de arena virgen bajo el imponente macizo montañoso de Jandía. Acceso complejo por pista de tierra. Prohibición de baño casi total por corrientes mortales. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35015','playa','Playa de Costa Calma',NULL,'Excelente. Gran playa urbana y residencial de aguas muy limpias y tranquilas, muy resguardada de los vientos dominantes. Arena blanca y fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35015','playa','Playa de La Pared',NULL,'Muy buena. Situada en la costa de barlovento, paisaje agreste con acantilados esculpidos y puestas de sol monumentales, muy valorada para el surf. Arena oscura de grano fino. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35014','playa','Grandes Playas de Corralejo','Bandera Azul','Excelente. Espectacular conjunto de playas kilométricas integradas en el Parque Natural de las Dunas de Corralejo. Aguas turquesas y transparentes con vistas directas a la Isla de Lobos. Arena blanca finísima (formada por restos de conchas trituradas). Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35014','playa','Playa de la Concha (El Cotillo)',NULL,'Excelente. Bahía natural circular protegida de forma natural por arrecifes de roca volcánica negra ("bajas") que impiden la entrada de olas, formando lagunas turquesas someras perfectas para niños. Arena blanca finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35014','playa','Playa de Los Charcos',NULL,'Excelente. Sucesión de pequeñas calas salvajes donde las coladas de lava forman charcas naturales cristalinas al norte de El Cotillo. Arena blanca y roca volcánica. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35014','playa','Playa de El Moro',NULL,'Excelente. Pequeña playa virgen muy buscada para el aprendizaje de surf en la linde de las dunas. Arena blanca y fina. No tiene Bandera Azul. [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35034','playa','Playas de Papagayo',NULL,'Excelente. Sucesión de calas vírgenes (Cala Papagayo, Playa Mujeres, El Pozo) encajadas entre acantilados del Monumento Natural de Los Ajaches. Aguas verde esmeralda en calma absoluta y transparentes. Arena dorada y finísima. No tiene Bandera Azul por restricciones de servicios en espacio protegido.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35034','playa','Playa de Dorada (Playa Blanca)',NULL,'Excelente. Playa urbana totalmente reformada y protegida por espigones que garantizan aguas en calma absoluta, ideal para familias. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35034','playa','Playa de Flamingo',NULL,'Muy buena. Pequeño arenal artificial resguardado flanqueado por palmeras y complejos residenciales. Arena dorada y fina. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35028','playa','Playa Grande (Puerto del Carmen)','Bandera Azul','Excelente. El arenal urbano más famoso y extenso del municipio, flanqueado por la gran avenida comercial, palmerales y aguas muy tranquilas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35028','playa','Playa de Matagorda','Bandera Azul','Excelente. Gran playa lineal muy expuesta al viento, ideal para deportes náuticos ligeros y pasear bajo la ruta de los aviones del aeropuerto. Arena dorada de grano medio. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35028','playa','Playa de los Pocillos','Bandera Azul','Excelente. Inmensamente ancha, en días de marea viva se forman lagunas de agua marina poco profundas sobre la arena. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('35028','playa','Playa Chica / Pila de la Barrilla','Bandera Azul','Excelente. Pequeña cala resguardada por rocas volcánicas, considerada uno de los mejores puntos de buceo de Canarias por sus cuevas submarinas. Arena fina. Sí tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38012','playa','Playa de Las Teresitas',NULL,'Excelente. La playa urbana de la capital, un arenal artificial flanqueado por miles de palmeras datileras y protegido por un rompeolas exento de 1,5 kilómetros que elimina por completo el oleaje. Arena dorada y finísima (importada del desierto del Sáhara). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38012','playa','Playa de Las Gaviotas',NULL,'Muy buena. Cala salvaje situada bajo acantilados colosales del macizo de Anaga, de tradición nudista y oleaje moderado. Arena negra muy fina (volcánica). No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38012','playa','Playa de Almáciga',NULL,'Excelente. Ubicada en pleno Parque Rural de Anaga, una playa indómita y espectacular de mar abierto con olas potentes y rocas basálticas. Arena negra fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38012','playa','Playa de Benijo',NULL,'Excelente. Una de las playas más fotogénicas de España debido a los impresionantes "roques" (islas de roca afilada) que emergen del Atlántico frente a la orilla. Puestas de sol monumentales, corrientes peligrosas. Arena negra volcánica muy fina. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90045','playa','Playa de Las Vistas',NULL,'Excelente. Inmenso arenal urbano diseñado en forma de concha doble con una isla artificial de la que brota un chorro de agua marina. Servicios de accesibilidad universal impecables y aguas en calma total. Arena dorada y fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90045','playa','Playa de Los Cristianos',NULL,'Muy buena. Ubicada junto al puerto comercial del mismo nombre, aguas totalmente mansas protegidas por los muelles, ambiente marinero tradicional. Arena fina y dorada. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90045','playa','Playa del Camisón',NULL,'Excelente. Preciosa cala artificial protegida por espigones curvados, rodeada de hoteles de gran lujo y palmerales. Arena fina y dorada. No tiene Bandera Azul. [1]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38001','playa','Playa de El Duque','Bandera Azul','Excelente. Una de las playas más exclusivas y cuidadas de la isla, flanqueada por un paseo marítimo señorial esculpido en piedra y hoteles de cinco estrellas. Arena fina y dorada. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38001','playa','Playa de Fañabé / Torviscas','Bandera Azul','Excelente. Gran complejo de playas urbanas conectadas, muy anchas y dotadas de todo tipo de infraestructuras náuticas, lúdicas y comerciales. Arena fina de tonalidades grises. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38001','playa','Playa de La Enramada',NULL,'Buena. Playa rústica modificada artificialmente para mejorar el baño, ambiente muy relajado. Compuesta por grava fina, arena gris y cantos rodados volcánicos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38001','playa','Playa de Diego Hernández (Playa Blanca)',NULL,'Excelente. Cala virgen salvaje oculta tras un espacio natural protegido, de aguas hipertransparentes y tradición nudista. Arena fina y dorada (inusual en el sur profundo). No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38013','playa','Playa de La Arena (Santiago del Teide)','Bandera Azul','Excelente. Galardonada con la Bandera Azul de forma consecutiva desde los años 80 por la excelencia de sus aguas. Encajada bajo acantilados bajos, de arenas negras que se calientan mucho con el sol. Arena negra volcánica finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38013','playa','Playa de Los Guíos',NULL,'Excelente. Una de las estampas más espectaculares de Canarias, situada justo a los pies de los colosales Acantilados de Los Gigantes (paredes verticales de roca basáltica de 600 metros de altura). Arena negra volcánica muy fina. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38011','playa','Playa Jardín',NULL,'Excelente. Impresionante complejo playero urbano diseñado por el célebre artista canario César Manrique. Rodeada de jardines de flora exótica, cascadas de agua y cuevas de piedra volcánica. Oleaje moderado a fuerte. Arena negra volcánica finísima. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38011','playa','Playa de Martiánez',NULL,'Buena. Situada junto al lago artificial del mismo nombre, playa abierta al mar bravo y muy frecuentada por surfistas locales. Arena negra y cantos rodados volcánicos. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38011','playa','Playa de San Telmo',NULL,'Muy buena. Pequeña cala tradicional excavada en el arrecife de roca volcánica del paseo marítimo, forma charcas tranquilas y cristalinas en bajamar. Arena negra y roca. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38023','playa','Playa de Bajamar','Bandera Azul','Muy buena. El municipio no destaca por playas de arena cómodas, pero cuenta con un complejo monumental de piscinas naturales de agua salada alimentadas directamente por el batir de las olas del Atlántico, totalmente equipadas. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38023','playa','Playa del Arenal',NULL,'Buena. Playa salvaje situada bajo acantilados en la costa norte, accesible solo a pie en bajamar. Arena negra fina y callaos. No tiene Bandera Azul. [1, 2]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('90046','playa','Playa de Los Cancajos','Bandera Azul','Excelente. Sucesión de calas protegidas de forma artificial por rompeolas de roca basáltica negra, lo que frena el mar bravo del norte y crea aguas tranquilas ideales para el snorkel y el buceo. Arena negra volcánica finísima. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38024','playa','Playa de Puerto Naos','Bandera Azul','Excelente. La playa más extensa de la isla, flanqueada por un paseo marítimo de palmeras, de arenas negras muy finas y aguas de gran transparencia. Arena negra volcánica. Sí tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38024','playa','Playa de Charco Verde','Bandera Azul','Excelente. Hermosa cala semiurbana encajada entre acantilados bajos cubiertos de plataneras, de aguas muy tranquilas y protegidas de las corrientes. Arena negra volcánica fina. Sí tiene Bandera Azul. [1, 2, 3, 4]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38049','playa','Playa de Vueltas',NULL,'Muy buena. Situada al abrigo del puerto pesquero, aguas en calma absoluta libres de corrientes atlánticas, muy familiar. Arena negra fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38049','playa','Playa de La Calera',NULL,'Excelente. La playa más extensa del municipio, situada bajo el imponente acantilado del barrio tradicional. Aguas limpias y oleaje moderado. Arena negra volcánica muy fina. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38049','playa','Playa del Inglés (La Gomera)',NULL,'Excelente. Impresionante playa completamente virgen y salvaje que combina la arena volcánica con el verde de la montaña canaria, de tradición nudista. Mar muy peligroso por corrientes. Arena negra fina. No tiene Bandera Azul. [1, 2, 3, 4, 5]','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38048','playa','Playa de La Caleta (El Hierro)',NULL,'Muy buena. El municipio destaca por sus zonas de baño volcánicas. Cuenta con una gran piscina artificial de agua marina regulada y grabados rupestres prehispánicos anexos en la roca. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,nivel_sello,descripcion,fuente,fecha_ingesta) VALUES ('38048','playa','Playa del Pozo de las Calcosas',NULL,'Espectacular. Barrio tradicional de casas construidas con piedra volcánica y techos de paja, con una impresionante piscina natural encajada en un acantilado de roca negra batido por el mar. No tiene Bandera Azul.','inventario_playas_pdf',date('now'));

